// id 格式：TOEIC_Part5_題號 / TOEIC_Part6_題號（題號重複時尾端加 _2、_3…）；no 是原檔題號，出題時會顯示在題目前面（例如 101、A2-例題-1）。
// 處理紀錄：Part 5 去除 1 題完全重複；Part 6 的 62 篇文章只有 27 篇不同，重複的只保留一份（共 108 題）；
//          Part 5 其中一題（題號 106）的「正確答案」欄位寫成 (B) to recruit，但詳解與選項都指向 (A) to recruit，已改為 (A)；
//          Part 6 兩篇課本文章（135-138）裡 [135][136] 空格標記遺失，已依答案補回。
// Part 6 欄位：passages 是文章；每題的 p 是文章編號、n 是空格號碼、g 用來讓同一篇文章的題目連續出現。

MCQ_SETS.push({
  id: "toeic5",
  name: "TOEIC Part 5（單句填空）",
  filters: ["分類"],
  questions: [
    {"id": "TOEIC_Part5_101", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Judging from recent sales, Athena Footwear's marketing campaign has _______ been a success.", "o": ["(A) clear", "(B) clearly", "(C) clearer", "(D) clearing"], "a": "B", "e": "【題目中文翻譯】\n從最近的銷售數字來看，雅典娜鞋業的行銷活動顯然獲得了成功。\n\n【選項中文語義與詞性】\n(A) 為字根「clear」之詞性變化形\n(B) 為字根「clearly」之詞性變化形\n(C) 為字根「clearer」之詞性變化形\n(D) 為字根「clearing」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) clearly。\n空格位於助動詞 has 與連繫動詞 been 之間，修飾動詞片語或全句，應填入副詞 clearly。選項為同字根不同詞性，分類為「詞性」。"},
    {"id": "TOEIC_Part5_102", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The _______ of a new chief executive officer at Perillon Industrial will be announced before the shareholder meeting.", "o": ["(A) appoints", "(B) appoint", "(C) appointment", "(D) appointed"], "a": "C", "e": "【題目中文翻譯】\n佩里隆工業新任執行長的任命將在股東大會前宣布。\n\n【選項中文語義與詞性】\n(A) 為字根「appoints」之詞性變化形\n(B) 為字根「appoint」之詞性變化形\n(C) 為字根「appointment」之詞性變化形\n(D) 為字根「appointed」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) appointment。\n定冠詞 The 後面接名詞作主詞，故事選名詞 appointment。選項為同字根衍生詞，分類為「詞性」。"},
    {"id": "TOEIC_Part5_103", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Many Grayton Construction employees know how to use a forklift, but only a few of _______ are licensed to operate them.", "o": ["(A) they", "(B) them", "(C) theirs", "(D) themselves"], "a": "B", "e": "【題目中文翻譯】\n格雷頓建設的許多員工都知道如何使用堆高機，但只有少數人獲得操作執照。\n\n【選項中文語義與詞性】\n(A) 為字根「they」之詞性變化形\n(B) 為字根「them」之詞性變化形\n(C) 為字根「theirs」之詞性變化形\n(D) 為字根「themselves」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) them。\n介系詞 of 後面接受格代名詞，作介系詞的受詞，故選 them。選項屬於代名詞格位變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_104", "no": "104", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "At Kaplan Optics, trainees are _______ to learn from each other by sharing their experiences from past design projects.", "o": ["(A) responded", "(B) excelled", "(C) maintained", "(D) encouraged"], "a": "D", "e": "【題目中文翻譯】\n在卡普蘭光學，實習生被鼓勵透過分享過去設計專案的經驗互相學習。\n\n【選項中文語義與詞性】\n(A) 「responded」（單字字義對照）\n(B) 「excelled」（單字字義對照）\n(C) 「maintained」（單字字義對照）\n(D) 「encouraged」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) encouraged。\n語意為「被鼓勵 (are encouraged to) 互相學習」，4個選項皆為不同意義的動詞單字，故分類為「字彙」。"},
    {"id": "TOEIC_Part5_105", "no": "105", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "_______ his medical record, Mr. Richmond was admitted to Maryport General Hospital on November 22.", "o": ["(A) As soon as", "(B) In compliance with", "(C) According to", "(D) Instead of"], "a": "C", "e": "【題目中文翻譯】\n根據他的病歷，里士滿先生於 11 月 22 日入住瑪麗港總醫院。\n\n【選項中文語義與詞性】\n(A) 「As soon as」（介系詞/介系詞片語）\n(B) 「In compliance with」（介系詞/介系詞片語）\n(C) 「According to」（介系詞/介系詞片語）\n(D) 「Instead of」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (C) According to。\n後接名詞 his medical record，表達「根據病歷紀錄」，故選介系詞片語 According to。選項多為介系詞/介系詞片語，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_106", "no": "106", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Trentex Consulting security guards must do _______ they can to ensure the safety of employees and visitors.", "o": ["(A) whatever", "(B) whenever", "(C) however", "(D) wherever"], "a": "A", "e": "【題目中文翻譯】\n特倫特克斯諮詢公司的安衛警衛必須盡其所能，確保員工和訪客的安全。\n\n【選項中文語義與詞性】\n(A) 「whatever」（連接詞/關係詞）\n(B) 「whenever」（連接詞/關係詞）\n(C) 「however」（連接詞/關係詞）\n(D) 「wherever」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (A) whatever。\n作動詞 do 的受詞，whatever they can 表示「任何他們能做的事」。選項皆為複合關係代名詞/副詞（連接詞類），分類為「連結詞」。"},
    {"id": "TOEIC_Part5_107", "no": "107", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Lewis Palmer has been assigned to _______ the cause of a recent equipment malfunction at the plant.", "o": ["(A) inform", "(B) determine", "(C) prevent", "(D) conclude"], "a": "B", "e": "【題目中文翻譯】\n路易斯·帕爾默已被指派去查明該廠近期設備故障的原因。\n\n【選項中文語義與詞性】\n(A) 「inform」（單字字義對照）\n(B) 「determine」（單字字義對照）\n(C) 「prevent」（單字字義對照）\n(D) 「conclude」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) determine。\n配合受詞 the cause (原因)，表達「查明/確定原因」，故選 determine。選項為4個不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_108", "no": "108", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The relationships that the staff members have formed with clients have _______ contributed to the company's success.", "o": ["(A) signified", "(B) significant", "(C) significantly", "(D) significance"], "a": "C", "e": "【題目中文翻譯】\n員工與客戶建立的關係對公司的成功有著顯著的貢獻。\n\n【選項中文語義與詞性】\n(A) 為字根「signified」之詞性變化形\n(B) 為字根「significant」之詞性變化形\n(C) 為字根「significantly」之詞性變化形\n(D) 為字根「significance」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) significantly。\n空格修飾動詞 contributed，應填入副詞 significantly。選項為同字根之詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_109", "no": "109", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "_______ at the new McLaren Institute is primarily centered on solar power generation.", "o": ["(A) Research", "(B) Researchers", "(C) Researched", "(D) Researches"], "a": "A", "e": "【題目中文翻譯】\n新邁克拉倫研究所的研究主要集中在太陽能發電上。\n\n【選項中文語義與詞性】\n(A) 為字根「Research」之詞性變化形\n(B) 為字根「Researchers」之詞性變化形\n(C) 為字根「Researched」之詞性變化形\n(D) 為字根「Researches」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) Research。\n動詞為單數 is，且主詞指「研究（不可數名詞）」，故選 Research。選項為同字根詞性及單複數變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_110", "no": "110", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Wentworth Contractors has adopted the _______ latest techniques for mixing cement.", "o": ["(A) so", "(B) many", "(C) much", "(D) very"], "a": "D", "e": "【題目中文翻譯】\n溫特沃斯承包商採用了最新穎的水泥混合技術。\n\n【選項中文語義與詞性】\n(A) 「so」（單字字義對照）\n(B) 「many」（單字字義對照）\n(C) 「much」（單字字義對照）\n(D) 「very」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) very。\nthe very + 最高級 (the very latest) 用於加強最高級語意，表示「最新的」。選項為不同副詞/限定詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_111", "no": "111", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Everyone _______ the parking attendants on duty will gather to hear the president's announcement.", "o": ["(A) rather", "(B) except", "(C) other", "(D) between"], "a": "B", "e": "【題目中文翻譯】\n除了值班的停車場管理員外，所有人都要集合聽取總裁的宣布。\n\n【選項中文語義與詞性】\n(A) 「rather」（介系詞/介系詞片語）\n(B) 「except」（介系詞/介系詞片語）\n(C) 「other」（介系詞/介系詞片語）\n(D) 「between」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (B) except。\nEveryone except... 表示「除了...以外的每個人」。except 在此作介系詞使用，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_112", "no": "112", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Topaz Tennis Club members who want to renew their membership card _______ it expires may do so at the reception counter.", "o": ["(A) still", "(B) until", "(C) before", "(D) whether"], "a": "C", "e": "【題目中文翻譯】\n黃玉網球俱樂部會員若想在會員卡到期前續卡，可至接待櫃檯辦理。\n\n【選項中文語義與詞性】\n(A) 「still」（連接詞/關係詞）\n(B) 「until」（連接詞/關係詞）\n(C) 「before」（連接詞/關係詞）\n(D) 「whether」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (C) before。\n引導時間副詞子句 it expires，語意為「在到期之前」，故選屬連接詞性質的 before。選項包含連接詞/副詞，分類為「連結詞」。"},
    {"id": "TOEIC_Part5_113", "no": "113", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The seminar room's _______ seating capacity is only forty, so Professor Ramos delivered his presentation in the auditorium.", "o": ["(A) maximum", "(B) maximization", "(C) maximizing", "(D) maximize"], "a": "A", "e": "【題目中文翻譯】\n研討室的最大座位容量只有四十人，因此拉莫斯教授在大禮堂發表了他的簡報。\n\n【選項中文語義與詞性】\n(A) 為字根「maximum」之詞性變化形\n(B) 為字根「maximization」之詞性變化形\n(C) 為字根「maximizing」之詞性變化形\n(D) 為字根「maximize」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) maximum。\n修飾名詞片語 seating capacity，需填入形容詞 maximum。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_114", "no": "114", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Applications for admission can be processed _______ all the necessary documents have been received.", "o": ["(A) first", "(B) soon", "(C) next", "(D) once"], "a": "D", "e": "【題目中文翻譯】\n一旦收到所有必要文件，即可開始處理入學申請。\n\n【選項中文語義與詞性】\n(A) 「first」（連接詞/關係詞）\n(B) 「soon」（連接詞/關係詞）\n(C) 「next」（連接詞/關係詞）\n(D) 「once」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (D) once。\n連接兩個完整的句子（子句），表達「一旦...就...」，應選擇從屬連接詞 once。選項涉及連接詞功能，分類為「連結詞」。"},
    {"id": "TOEIC_Part5_115", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "A replacement will not be hired until January unless the division _______ needs to fill the position immediately.", "o": ["(A) true", "(B) truth", "(C) truly", "(D) truthful"], "a": "C", "e": "【題目中文翻譯】\n除非該部門確實需要立即填補該職缺，否則要到一月才會聘用替代人員。\n\n【選項中文語義與詞性】\n(A) 為字根「true」之詞性變化形\n(B) 為字根「truth」之詞性變化形\n(C) 為字根「truly」之詞性變化形\n(D) 為字根「truthful」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) truly。\n空格修飾動詞 needs，應填入副詞 truly（確實地）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_116", "no": "116", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The number of subscribers to the community newsletter reached 12,500 this week following a steady _______ in subscriptions in March.", "o": ["(A) extension", "(B) addition", "(C) increase", "(D) raise"], "a": "C", "e": "【題目中文翻譯】\n在三月份訂閱量穩定增加之後，本週社區通訊的訂閱人數達到 12,500 人。\n\n【選項中文語義與詞性】\n(A) 「extension」（單字字義對照）\n(B) 「addition」（單字字義對照）\n(C) 「increase」（單字字義對照）\n(D) 「raise」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) increase。\na steady increase in... 表示「...的穩定成長/增加」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_117", "no": "117", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Granger will send applications to two different agencies to obtain the permits _______ for erecting a barn.", "o": ["(A) required", "(B) requiring", "(C) requires", "(D) requirement"], "a": "A", "e": "【題目中文翻譯】\n格蘭傑先生將向兩個不同機構提出申請，以取得建造穀倉所需的許可證。\n\n【選項中文語義與詞性】\n(A) 為字根「required」之詞性變化形\n(B) 為字根「requiring」之詞性變化形\n(C) 為字根「requires」之詞性變化形\n(D) 為字根「requirement」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) required。\n修飾前面的名詞 permits，表達「被需要的許可證」，用過去分詞 required 後置修飾。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_118", "no": "118", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Donna Clark asked her assistant to find out which galleries exhibit the works _______ are shown in the book of paintings.", "o": ["(A) such", "(B) that", "(C) about", "(D) what"], "a": "B", "e": "【題目中文翻譯】\n唐娜·克拉克請助理去查明哪些畫廊展出了該畫冊中展示的作品。\n\n【選項中文語義與詞性】\n(A) 「such」（連接詞/關係詞）\n(B) 「that」（連接詞/關係詞）\n(C) 「about」（連接詞/關係詞）\n(D) 「what」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (B) that。\n引導關係子句修飾先行詞 the works，作子句的主詞，故選關係代名詞 that。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_119", "no": "119", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The Sanderton Public Library will be closed for renovations _______ on Monday, May 4.", "o": ["(A) will begin", "(B) has begun", "(C) beginner", "(D) beginning"], "a": "D", "e": "【題目中文翻譯】\n桑德頓市立圖書館將從 5 月 4 日星期一開始閉館進行裝修。\n\n【選項中文語義與詞性】\n(A) 為字根「will begin」之詞性變化形\n(B) 為字根「has begun」之詞性變化形\n(C) 為字根「beginner」之詞性變化形\n(D) 為字根「beginning」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) beginning。\nbeginning on + 日期 表示「自...起/從...開始」。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_120", "no": "120", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "This e_mail serves _______ confirmation that Glennfirth Hotel has received your reservation request.", "o": ["(A) with", "(B) to", "(C) as", "(D) for"], "a": "C", "e": "【題目中文翻譯】\n此電子郵件作為格倫弗斯飯店已收到您的預訂請求的確認函。\n\n【選項中文語義與詞性】\n(A) 「with」（介系詞/介系詞片語）\n(B) 「to」（介系詞/介系詞片語）\n(C) 「as」（介系詞/介系詞片語）\n(D) 「for」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (C) as。\nserve as... 為固定搭配，表示「充當/作為...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_121", "no": "121", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Irwin agreed to write letters of _______ for the interns who had successfully completed all the requirements of their internships.", "o": ["(A) recommends", "(B) recommended", "(C) recommending", "(D) recommendation"], "a": "D", "e": "【題目中文翻譯】\n歐文先生同意為成功完成實習所有要求的實習生撰寫推薦信。\n\n【選項中文語義與詞性】\n(A) 為字根「recommends」之詞性變化形\n(B) 為字根「recommended」之詞性變化形\n(C) 為字根「recommending」之詞性變化形\n(D) 為字根「recommendation」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) recommendation。\nletters of recommendation 為固定片語（推薦信），介系詞 of 後接名詞 recommendation。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_122", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Instructions have been posted above each washing machine so that customers can _______ refer to them.", "o": ["(A) commonly", "(B) consecutively", "(C) eagerly", "(D) easily"], "a": "D", "e": "【題目中文翻譯】\n每台洗衣機上方都張貼了說明，以便顧客輕鬆參考。\n\n【選項中文語義與詞性】\n(A) 「commonly」（單字字義對照）\n(B) 「consecutively」（單字字義對照）\n(C) 「eagerly」（單字字義對照）\n(D) 「easily」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) easily。\neasily refer to them 表示「輕鬆地參考說明」。4個選項為不同意義副詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_123", "no": "123", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Hospital nurses are _______ to take paid vacation days after a six_month probationary period.", "o": ["(A) dependable", "(B) necessary", "(C) eligible", "(D) accurate"], "a": "C", "e": "【題目中文翻譯】\n醫院護理師在六個月試用期滿後有資格享受有薪年假。\n\n【選項中文語義與詞性】\n(A) 「dependable」（單字字義對照）\n(B) 「necessary」（單字字義對照）\n(C) 「eligible」（單字字義對照）\n(D) 「accurate」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) eligible。\nbe eligible to V 表示「有資格做...」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_124", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Hospital nurses are required to take paid vacation days after a six_month probationary period.", "o": ["(A) dependable", "(B) necessary", "(C) eligible", "(D) required"], "a": "C", "e": "【題目中文翻譯】\n醫院護理師在過試用期後即符合帶薪休假的資格。\n\n【選項中文語義與詞性】\n(A) 「dependable」（單字字義對照）\n(B) 「necessary」（單字字義對照）\n(C) 「eligible」（單字字義對照）\n(D) 「required」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) eligible。\nbe eligible to 表示符合權利/資格條件。4個選項為不同字彙，分類為「字彙」。"},
    {"id": "TOEIC_Part5_125", "no": "125", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "After working in Australia for seven years, Lisa Marley has _______ to Toronto to take a managerial position.", "o": ["(A) considered", "(B) returned", "(C) removed", "(D) visited"], "a": "B", "e": "【題目中文翻譯】\n在澳洲工作七年後，麗莎·馬利已返回多倫多擔任管理職務。\n\n【選項中文語義與詞性】\n(A) 「considered」（單字字義對照）\n(B) 「returned」（單字字義對照）\n(C) 「removed」（單字字義對照）\n(D) 「visited」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) returned。\nreturned to Toronto 表示「返回多倫多」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_126", "no": "126", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The turnout for yesterday's country music festival was larger than anticipated, _______ the poor weather.", "o": ["(A) even", "(B) notwithstanding", "(C) concerning", "(D) through"], "a": "B", "e": "【題目中文翻譯】\n儘管天氣不佳，昨天鄉村音樂節的出席人數仍高於預期。\n\n【選項中文語義與詞性】\n(A) 「even」（介系詞/介系詞片語）\n(B) 「notwithstanding」（介系詞/介系詞片語）\n(C) 「concerning」（介系詞/介系詞片語）\n(D) 「through」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (B) notwithstanding。\nnotwithstanding the poor weather 作介系詞使用，表示「儘管天氣惡劣」。選項屬介系詞功能，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_127", "no": "127", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The new bins have a lid that flips up for easy _______ of large bags of garbage.", "o": ["(A) allowance", "(B) rejection", "(C) disposal", "(D) dismissal"], "a": "C", "e": "【題目中文翻譯】\n新型垃圾桶設有可向上翻開的蓋子，方便處置大袋垃圾。\n\n【選項中文語義與詞性】\n(A) 「allowance」（單字字義對照）\n(B) 「rejection」（單字字義對照）\n(C) 「disposal」（單字字義對照）\n(D) 「dismissal」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) disposal。\ndisposal of garbage 為習慣用語（垃圾處理/丟棄）。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_128", "no": "128", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Although the YRL_11 monitor looks _______ to other models, it is made of a brand_new lightweight material.", "o": ["(A) similarity", "(B) similarities", "(C) similar", "(D) similarly"], "a": "C", "e": "【題目中文翻譯】\n雖然 YRL-11 螢幕看起來與其他型號相似，但它是由全新的輕量材料製成的。\n\n【選項中文語義與詞性】\n(A) 為字根「similarity」之詞性變化形\n(B) 為字根「similarities」之詞性變化形\n(C) 為字根「similar」之詞性變化形\n(D) 為字根「similarly」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) similar。\n連繫動詞 looks 後接形容詞作補語，look similar to...（看起來與...相似）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_129", "no": "129", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The decision to release the new smartphone ahead of schedule was based _______ on the marketing director's recommendation.", "o": ["(A) currently", "(B) evenly", "(C) gradually", "(D) solely"], "a": "D", "e": "【題目中文翻譯】\n提早發表新智慧型手機的決定完全是基於行銷總監的建議。\n\n【選項中文語義與詞性】\n(A) 「currently」（單字字義對照）\n(B) 「evenly」（單字字義對照）\n(C) 「gradually」（單字字義對照）\n(D) 「solely」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) solely。\nbased solely on... 表示「完全基於/單純基於...」。4個選項為不同副詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_130", "no": "130", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The event would not have been successful if we _______ the support of local businesses.", "o": ["(A) do not have", "(B) will not have", "(C) have not had", "(D) had not had"], "a": "D", "e": "【題目中文翻譯】\n如果沒有當地企業的支持，這項活動就不會取得成功。\n\n【選項中文語義與詞性】\n(A) 為字根「do not have」之詞性變化形\n(B) 為字根「will not have」之詞性變化形\n(C) 為字根「have not had」之詞性變化形\n(D) 為字根「had not had」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) had not had。\n與過去事實相反的條件句：If + S + had p.p., S + would have p.p.。主要子句為 would not have been，條件子句應填 had not had。屬於動詞時態/態樣變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_101_2", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Owing to its extensive housing development, Akron has become a _______ populated city in the last three decades.", "o": ["(A) densely", "(B) dense", "(C) denseness", "(D) density"], "a": "A", "e": "【題目中文翻譯】\n由於大規模的住宅開發，阿克倫在過去三十年中已成為一個人口稠密的城市。\n\n【選項中文語義與詞性】\n(A) 為字根「densely」之詞性變化形\n(B) 為字根「dense」之詞性變化形\n(C) 為字根「denseness」之詞性變化形\n(D) 為字根「density」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) densely。\n空格修飾形容詞（分詞）populated，需填入副詞 densely（稠密地）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_102_2", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Annette Choi has finally realized that the _______ of the new job outweigh the costs and will accept the offer.", "o": ["(A) beneficial", "(B) benefit", "(C) benefits", "(D) benefited"], "a": "C", "e": "【題目中文翻譯】\n安妮特·崔終於意識到新工作的好處大於代價，並將接受該工作機會。\n\n【選項中文語義與詞性】\n(A) 為字根「beneficial」之詞性變化形\n(B) 為字根「benefit」之詞性變化形\n(C) 為字根「benefits」之詞性變化形\n(D) 為字根「benefited」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) benefits。\n定冠詞 the 後接名詞，且動詞為複數動詞 outweigh，故主詞需用複數名詞 benefits。選項為同字根變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_103_2", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Our CEO requests that we _______ the new branch location confidential until all employees have been informed.", "o": ["(A) are keeping", "(B) keep", "(C) kept", "(D) will keep"], "a": "B", "e": "【題目中文翻譯】\n我們的執行長要求在通知所有員工之前，對新分公司位置保密。\n\n【選項中文語義與詞性】\n(A) 為字根「are keeping」之詞性變化形\n(B) 為字根「keep」之詞性變化形\n(C) 為字根「kept」之詞性變化形\n(D) 為字根「will keep」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) keep。\n要求動詞 request + that + S + (should) + V原形，故答案為 keep。屬於動詞文法時態/假設法變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_104_2", "no": "104", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The new employee orientation will be held at the company's headquarters _______ 9:00 A.M. to 11:00 A.M. on Monday, September 6.", "o": ["(A) from", "(B) between", "(C) at", "(D) on"], "a": "A", "e": "【題目中文翻譯】\n新員工培訓將於 9 月 6 日星期一上午 9:00 至 11:00 在公司總部舉行。\n\n【選項中文語義與詞性】\n(A) 「from」（介系詞/介系詞片語）\n(B) 「between」（介系詞/介系詞片語）\n(C) 「at」（介系詞/介系詞片語）\n(D) 「on」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (A) from。\nfrom... to... 表示「從...到...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_105_2", "no": "105", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "All of the documents on our overseas projects are made available in _______ Korean and English.", "o": ["(A) both", "(B) either", "(C) also", "(D) too"], "a": "A", "e": "【題目中文翻譯】\n我們海外專案的所有文件均提供韓文和英文兩種版本。\n\n【選項中文語義與詞性】\n(A) 「both」（連接詞/關係詞）\n(B) 「either」（連接詞/關係詞）\n(C) 「also」（連接詞/關係詞）\n(D) 「too」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (A) both。\nboth A and B 為對等相關連接詞（韓文與英文兩者皆有）。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_106_2", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Those advertising agencies claim _______ new Web marketing promotion will boost profits more effectively than any other strategy.", "o": ["(A) themselves", "(B) their", "(C) them", "(D) they"], "a": "B", "e": "【題目中文翻譯】\n這些廣告公司聲稱，他們的新網路行銷推廣將比任何其他策略更有效地提升利潤。\n\n【選項中文語義與詞性】\n(A) 為字根「themselves」之詞性變化形\n(B) 為字根「their」之詞性變化形\n(C) 為字根「them」之詞性變化形\n(D) 為字根「they」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) their。\n修飾名詞片語 new Web marketing promotion，需填入所有格代名詞 their。屬代名詞格位變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_107_2", "no": "107", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ace Technologies Ltd. firmly believes that its high_tech products are the _______ of any available on the market.", "o": ["(A) finely", "(B) fine", "(C) finer", "(D) finest"], "a": "D", "e": "【題目中文翻譯】\n王牌科技股份有限公司堅信，其高科技產品是市場上所有產品中最優秀的。\n\n【選項中文語義與詞性】\n(A) 為字根「finely」之詞性變化形\n(B) 為字根「fine」之詞性變化形\n(C) 為字根「finer」之詞性變化形\n(D) 為字根「finest」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) finest。\nthe + 最高級 + of any... 表示「所有中最好的/最優秀的」，故選 finest。屬於形容詞比較等級變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_108_2", "no": "108", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "_______ at 3 P.M. Thursday this year's state fair will commence at the Central Slate Fairgrounds.", "o": ["(A) Precise", "(B) Precisely", "(C) Preciseness", "(D) Precision"], "a": "B", "e": "【題目中文翻譯】\n今年州博覽會將於星期四下午 3 點整在中央斯萊特博覽會場地準時開始。\n\n【選項中文語義與詞性】\n(A) 為字根「Precise」之詞性變化形\n(B) 為字根「Precisely」之詞性變化形\n(C) 為字根「Preciseness」之詞性變化形\n(D) 為字根「Precision」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) Precisely。\nprecisely at 3 P.M. 副詞修飾時間介系詞片語，表示「準時於...」。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_109_2", "no": "109", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "All the managers admit that Ms. Jensen is fully qualified _______ the sales head position.", "o": ["(A) by", "(B) for", "(C) in", "(D) with"], "a": "B", "e": "【題目中文翻譯】\n所有經理都承認詹森女士完全有資格勝任銷售主管一職。\n\n【選項中文語義與詞性】\n(A) 「by」（介系詞/介系詞片語）\n(B) 「for」（介系詞/介系詞片語）\n(C) 「in」（介系詞/介系詞片語）\n(D) 「with」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (B) for。\nbe qualified for + 名詞/職位 表示「有資格擔任...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_110_2", "no": "110", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "As a courtesy to your coworkers please _______ from smoking anywhere other than in designated areas.", "o": ["(A) limit", "(B) prevent", "(C) refrain", "(D) stop"], "a": "C", "e": "【題目中文翻譯】\n為了禮貌起見，請勿在指定區域以外的任何地方吸菸。\n\n【選項中文語義與詞性】\n(A) 「limit」（單字字義對照）\n(B) 「prevent」（單字字義對照）\n(C) 「refrain」（單字字義對照）\n(D) 「stop」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) refrain。\nrefrain from N/Ving 表示「忍住/克制不做...」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_111_2", "no": "111", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The city is planning to renovate the auditorium _______ several historic politicians made speeches.", "o": ["(A) whose", "(B) that", "(C) where", "(D) which"], "a": "C", "e": "【題目中文翻譯】\n該市正計劃翻新幾位歷史政治家曾發表演講的大禮堂。\n\n【選項中文語義與詞性】\n(A) 「whose」（連接詞/關係詞）\n(B) 「that」（連接詞/關係詞）\n(C) 「where」（連接詞/關係詞）\n(D) 「which」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (C) where。\n先行詞為地點 the auditorium，子句中缺乏地點副詞，應使用關係副詞 where。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_112_2", "no": "112", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "After weeks of rumors in the press the candidate _______ announced his intention to run for governor.", "o": ["(A) formally", "(B) exactly", "(C) formerly", "(D) hopefully"], "a": "A", "e": "【題目中文翻譯】\n經過媒體數週的傳聞後，該候選人正式宣布參選州長。\n\n【選項中文語義與詞性】\n(A) 「formally」（單字字義對照）\n(B) 「exactly」（單字字義對照）\n(C) 「formerly」（單字字義對照）\n(D) 「hopefully」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) formally。\nformally announced 表示「正式宣布」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_113_2", "no": "113", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Just a decade ago even this type of slow processor was considered to be _______.", "o": ["(A) relative", "(B) decorative", "(C) informative", "(D) innovative"], "a": "D", "e": "【題目中文翻譯】\n就在十年前，即使是這種慢速處理器也被認為具有創新性。\n\n【選項中文語義與詞性】\n(A) 「relative」（單字字義對照）\n(B) 「decorative」（單字字義對照）\n(C) 「informative」（單字字義對照）\n(D) 「innovative」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) innovative。\nconsidered to be innovative 表示「被認為是創新的」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_114_2", "no": "114", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "With their reinforced outer layers, Beck's outdoor lamps can _______ well both the hot and cold weather.", "o": ["(A) withstands", "(B) withstood", "(C) withstand", "(D) withstanding"], "a": "C", "e": "【題目中文翻譯】\n憑藉其強化外層，貝克的戶外燈具能夠很好地抵禦酷暑和嚴寒。\n\n【選項中文語義與詞性】\n(A) 為字根「withstands」之詞性變化形\n(B) 為字根「withstood」之詞性變化形\n(C) 為字根「withstand」之詞性變化形\n(D) 為字根「withstanding」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) withstand。\n助動詞 can 後面接原形動詞 withstand（承受/抵禦）。選項為同字根動詞時態與態樣變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_115_2", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Victoria Community House will eventually be renovated _______ a library which will contain history_related books and videos.", "o": ["(A) inclusion", "(B) including", "(C) to include", "(D) included"], "a": "C", "e": "【題目中文翻譯】\n維多利亞社區中心最終將進行翻新，擴建一個包含歷史相關書籍和影片的圖書館。\n\n【選項中文語義與詞性】\n(A) 為字根「inclusion」之詞性變化形\n(B) 為字根「including」之詞性變化形\n(C) 為字根「to include」之詞性變化形\n(D) 為字根「included」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) to include。\nto include... 作目的或結果不定詞片語「以包含.../翻新納入...」。選項為同字根衍生變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_116_2", "no": "116", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The Sunshine Foundation provides _______ to local residents who lost their homes.", "o": ["(A) control", "(B) education", "(C) relief", "(D) representation"], "a": "C", "e": "【題目中文翻譯】\n陽光基金會向失去家園的當地居民提供救濟。\n\n【選項中文語義與詞性】\n(A) 「control」（單字字義對照）\n(B) 「education」（單字字義對照）\n(C) 「relief」（單字字義對照）\n(D) 「representation」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) relief。\nprovide relief to... 表示「向...提供救濟/援助」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_117_2", "no": "117", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Ms. Harris needed to clear the round table _______ scattered documents after the product development meeting.", "o": ["(A) for", "(B) of", "(C) on", "(D) with"], "a": "B", "e": "【題目中文翻譯】\n產品開發會議結束後，哈里斯女士需要清空圓桌上散落的文件。\n\n【選項中文語義與詞性】\n(A) 「for」（介系詞/介系詞片語）\n(B) 「of」（介系詞/介系詞片語）\n(C) 「on」（介系詞/介系詞片語）\n(D) 「with」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (B) of。\nclear A of B 為固定片語，表示「清理A上的B（雜物/文件）」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_118_2", "no": "118", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Ms. Perry was evaluated very high _______ the fact that she brought in three large clients this quarter.", "o": ["(A) due to", "(B) even though", "(C) unless", "(D) whereas"], "a": "A", "e": "【題目中文翻譯】\n鑑於佩里女士本季度帶來了三位大客戶，她獲得了極高的評價。\n\n【選項中文語義與詞性】\n(A) 「due to」（介系詞/介系詞片語）\n(B) 「even though」（介系詞/介系詞片語）\n(C) 「unless」（介系詞/介系詞片語）\n(D) 「whereas」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (A) due to。\n後接名詞片語 the fact that...，應使用介系詞片語 due to。選項包含介系詞與連接詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_119_2", "no": "119", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "One _______ of a good system project manager is the ability to coordinate people and other resources.", "o": ["(A) aspiration", "(B) attempt", "(C) position", "(D) characteristic"], "a": "D", "e": "【題目中文翻譯】\n一名優秀的系統專案經理的特徵之一是協調人員和其他資源的能力。\n\n【選項中文語義與詞性】\n(A) 「aspiration」（單字字義對照）\n(B) 「attempt」（單字字義對照）\n(C) 「position」（單字字義對照）\n(D) 「characteristic」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) characteristic。\nOne characteristic of... 表示「...的特徵之一」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_120_2", "no": "120", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The following notice is important and requires the _______ attention of the addressee.", "o": ["(A) consistent", "(B) immediate", "(C) late", "(D) optional"], "a": "B", "e": "【題目中文翻譯】\n以下通知非常重要，需要收件人立即關注。\n\n【選項中文語義與詞性】\n(A) 「consistent」（單字字義對照）\n(B) 「immediate」（單字字義對照）\n(C) 「late」（單字字義對照）\n(D) 「optional」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) immediate。\nimmediate attention 表示「立即的關注/即時處理」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_121_2", "no": "121", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "_______ has been discussed about the mayor's resignation but there has been no official comment.", "o": ["(A) Another", "(B) Every", "(C) Much", "(D) Several"], "a": "C", "e": "【題目中文翻譯】\n關於市長辭職的事宜已經討論了很多，但尚未有官方回應。\n\n【選項中文語義與詞性】\n(A) 「Another」（單字字義對照）\n(B) 「Every」（單字字義對照）\n(C) 「Much」（單字字義對照）\n(D) 「Several」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) Much。\nMuch 代替不可數討論量，作不可數主詞配合單數動詞 has been discussed。選項為不同代名詞/限定詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_122_2", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Dr. Gerald Schmitz was proud to be one of _______ a few professors to receive the award in physics.", "o": ["(A) almost", "(B) among", "(C) those", "(D) only"], "a": "D", "e": "【題目中文翻譯】\n傑拉德·施密茨博士很自豪能成為僅有的幾位獲得物理學獎的教授之一。\n\n【選項中文語義與詞性】\n(A) 「almost」（單字字義對照）\n(B) 「among」（單字字義對照）\n(C) 「those」（單字字義對照）\n(D) 「only」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) only。\none of only a few... 表示「僅有的少數人之一」。4個選項為不同字彙，分類為「字彙」。"},
    {"id": "TOEIC_Part5_123_2", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Please complete the _______ application form and return it to our company by November 21.", "o": ["(A) enclose", "(B) enclosed", "(C) enclosing", "(D) enclosure"], "a": "B", "e": "【題目中文翻譯】\n請填妥隨附的申請表，並於 11 月 21 日之前寄回本公司。\n\n【選項中文語義與詞性】\n(A) 為字根「enclose」之詞性變化形\n(B) 為字根「enclosed」之詞性變化形\n(C) 為字根「enclosing」之詞性變化形\n(D) 為字根「enclosure」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) enclosed。\n修飾名詞 application form，用過去分詞 enclosed 作形容詞「隨附的」。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_124_2", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Tonghae Motors announced that it will be _______ its TM_2500 SUV because of a problem with the steering system.", "o": ["(A) advertising", "(B) developing", "(C) introducing", "(D) redesigning"], "a": "D", "e": "【題目中文翻譯】\n東海汽車宣布，由於轉向系統存在問題，將重新設計其 TM_2500 SUV。\n\n【選項中文語義與詞性】\n(A) 「advertising」（單字字義對照）\n(B) 「developing」（單字字義對照）\n(C) 「introducing」（單字字義對照）\n(D) 「redesigning」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) redesigning。\n語意因轉向系統有問題，故需要「重新設計 (redesigning)」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_125_2", "no": "125", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "_______ she had excellent references, Ms. Baker's application for the position of executive assistant was accepted.", "o": ["(A) Although", "(B) As", "(C) Despite", "(D) Even if"], "a": "B", "e": "【題目中文翻譯】\n由於貝克女士擁有優秀的推薦信，她應徵執行助理職位的申請獲得了批准。\n\n【選項中文語義與詞性】\n(A) 「Although」（連接詞/關係詞）\n(B) 「As」（連接詞/關係詞）\n(C) 「Despite」（連接詞/關係詞）\n(D) 「Even if」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (B) As。\n表示因果關係「因為/由於她有優秀推薦信」，用從屬連接詞 As。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_126_2", "no": "126", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "CircleMart sells two types of rechargeable batteries, both of _______ have been sold out for a few days.", "o": ["(A) that", "(B) what", "(C) which", "(D) whom"], "a": "C", "e": "【題目中文翻譯】\nCircleMart 銷售兩種充電電池，兩種電池都已經售罄好幾天了。\n\n【選項中文語義與詞性】\n(A) 「that」（連接詞/關係詞）\n(B) 「what」（連接詞/關係詞）\n(C) 「which」（連接詞/關係詞）\n(D) 「whom」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (C) which。\n介系詞 of 後引導非限定關係子句修飾物 (batteries)，需使用關係代名詞 which (both of which)。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_127_2", "no": "127", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Micron Pharmaceuticals will postpone the launch of their new medication until its effect _______.", "o": ["(A) has been reconfirmed", "(B) reconfirm", "(C) reconfirmed", "(D) was reconfirmed"], "a": "A", "e": "【題目中文翻譯】\n美光製藥將推遲新藥的推出，直到其療效得到再次確認。\n\n【選項中文語義與詞性】\n(A) 為字根「has been reconfirmed」之詞性變化形\n(B) 為字根「reconfirm」之詞性變化形\n(C) 為字根「reconfirmed」之詞性變化形\n(D) 為字根「was reconfirmed」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) has been reconfirmed。\nuntil 時間副詞子句中，用現在完成式代替未來完成式，且主詞 its effect 為被動關係，故選 has been reconfirmed。分類為「詞性」。"},
    {"id": "TOEIC_Part5_128_2", "no": "128", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Only the sturdy guardrail on the side of the road prevented the car _______ falling off the cliff.", "o": ["(A) from", "(B) of", "(C) through", "(D) with"], "a": "A", "e": "【題目中文翻譯】\n只有路邊堅固的護欄防止了汽車墜落山崖。\n\n【選項中文語義與詞性】\n(A) 「from」（介系詞/介系詞片語）\n(B) 「of」（介系詞/介系詞片語）\n(C) 「through」（介系詞/介系詞片語）\n(D) 「with」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (A) from。\nprevent A from Ving 為固定搭配，表示「防止A做...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_129_2", "no": "129", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "They are fighting against the _______ to retain their market share in the beverage industry.", "o": ["(A) chance", "(B) wind", "(C) wall", "(D) odds"], "a": "D", "e": "【題目中文翻譯】\n他們正在克服重重困難，以保持在飲料行業的市場份額。\n\n【選項中文語義與詞性】\n(A) 「chance」（單字字義對照）\n(B) 「wind」（單字字義對照）\n(C) 「wall」（單字字義對照）\n(D) 「odds」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) odds。\nfight against the odds 表示「克服重重困難/逆境搏鬥」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_130_2", "no": "130", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Nothing is more important for a newspaper reporter than to find a _______ source of information.", "o": ["(A) changeable", "(B) dispensable", "(C) purchasable", "(D) reliable"], "a": "D", "e": "【題目中文翻譯】\n對於報社記者來說，沒有什麼比找到可靠的信息來源更重要的了。\n\n【選項中文語義與詞性】\n(A) 「changeable」（單字字義對照）\n(B) 「dispensable」（單字字義對照）\n(C) 「purchasable」（單字字義對照）\n(D) 「reliable」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) reliable。\na reliable source of information 表示「可靠的資訊來源」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_101_3", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Since its launch, XJ400 has quickly become a _______ for the mobile phone industry.", "o": ["(A) standardize", "(B) standardizing", "(C) standardized", "(D) standard"], "a": "D", "e": "【題目中文翻譯】\n自推出以來，XJ400 已迅速成為手機行業的標準。\n\n【選項中文語義與詞性】\n(A) 為字根「standardize」之詞性變化形\n(B) 為字根「standardizing」之詞性變化形\n(C) 為字根「standardized」之詞性變化形\n(D) 為字根「standard」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) standard。\n冠詞 a 後面接名詞 standard 作補語。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_102_3", "no": "102", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Anyone interested in the Marketing Director position should immediately telephone Mr. Kim _______ visit him in person.", "o": ["(A) or", "(B) also", "(C) not", "(D) but"], "a": "A", "e": "【題目中文翻譯】\n任何對行銷總監職位感興趣的人應立即致電金先生或親自拜訪他。\n\n【選項中文語義與詞性】\n(A) 「or」（連接詞/關係詞）\n(B) 「also」（連接詞/關係詞）\n(C) 「not」（連接詞/關係詞）\n(D) 「but」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (A) or。\ntelephone... or visit... 連接兩個平行動作（致電或親自拜訪），用對等連接詞 or。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_103_3", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "After _______ the faulty parts of the printer, the repairperson gave it a thorough cleaning.", "o": ["(A) replace", "(B) replaced", "(C) replaces", "(D) replacing"], "a": "D", "e": "【題目中文翻譯】\n在更換印表機的故障零件後，維修人員對其進行了徹底的清潔。\n\n【選項中文語義與詞性】\n(A) 為字根「replace」之詞性變化形\n(B) 為字根「replaced」之詞性變化形\n(C) 為字根「replaces」之詞性變化形\n(D) 為字根「replacing」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) replacing。\n介系詞 After 後面接動名詞 replacing 作受詞。選項為同字根動詞變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_104_3", "no": "104", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Those who live in this residential area should have good _______ to large shopping centers and supermarkets.", "o": ["(A) access", "(B) accessible", "(C) accessibly", "(D) accession"], "a": "A", "e": "【題目中文翻譯】\n居住在該住宅區的居民應能便利地前往大型購物中心和超市。\n\n【選項中文語義與詞性】\n(A) 為字根「access」之詞性變化形\n(B) 為字根「accessible」之詞性變化形\n(C) 為字根「accessibly」之詞性變化形\n(D) 為字根「accession」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) access。\nhave good access to... 表示「可以方便使用/到達...」。形容詞 good 後接不可數名詞 access。分類為「詞性」。"},
    {"id": "TOEIC_Part5_105_3", "no": "105", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Since the local companies scrapped unprofitable products and devoted more resources to products with more potential, _______ have started making profits.", "o": ["(A) their", "(B) theirs", "(C) them", "(D) they"], "a": "D", "e": "【題目中文翻譯】\n由於當地公司廢除了不盈利的產品，並將更多資源投入到更有潛力的產品中，他們已經開始獲利。\n\n【選項中文語義與詞性】\n(A) 為字根「their」之詞性變化形\n(B) 為字根「theirs」之詞性變化形\n(C) 為字根「them」之詞性變化形\n(D) 為字根「they」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) they。\n主要子句需要主格代名詞 they 作動詞 have started 的主詞。屬代名詞格位變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_106_3", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The _______ version of the keynote speech for next week's annual shareholders' meeting will be available later today.", "o": ["(A) final", "(B) finality", "(C) finalize", "(D) finally"], "a": "A", "e": "【題目中文翻譯】\n下週年度股東大會主題演講的最終版本將於今天晚些時候提供。\n\n【選項中文語義與詞性】\n(A) 為字根「final」之詞性變化形\n(B) 為字根「finality」之詞性變化形\n(C) 為字根「finalize」之詞性變化形\n(D) 為字根「finally」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) final。\n修飾名詞 version，需填入形容詞 final（最終的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_107_3", "no": "107", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The division led by Mr. Davidson has recorded the best sales performance _______.", "o": ["(A) ever", "(B) never", "(C) since", "(D) until"], "a": "A", "e": "【題目中文翻譯】\n戴維森先生領導的部門創下了有史以來最好的銷售業績。\n\n【選項中文語義與詞性】\n(A) 「ever」（單字字義對照）\n(B) 「never」（單字字義對照）\n(C) 「since」（單字字義對照）\n(D) 「until」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) ever。\nthe best... ever 表示「有史以來最好的...」。選項為不同副詞/介系詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_108_3", "no": "108", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Mr. Henderson was recruited to head MNN Chemicals, Inc. in order to _______ the troubled firm.", "o": ["(A) recognize", "(B) recreate", "(C) reorganize", "(D) represent"], "a": "C", "e": "【題目中文翻譯】\n亨德森先生被招聘來領導 MNN 化工公司，以整頓這家陷入困境的公司。\n\n【選項中文語義與詞性】\n(A) 「recognize」（單字字義對照）\n(B) 「recreate」（單字字義對照）\n(C) 「reorganize」（單字字義對照）\n(D) 「represent」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) reorganize。\nin order to reorganize the troubled firm 表示「為了改組整頓這家困境中的公司」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_109_3", "no": "109", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Anzai from CBC corporation _______ us a visit later this month.", "o": ["(A) paid", "(B) pays", "(C) will pay", "(D) has paid"], "a": "C", "e": "【題目中文翻譯】\nCBC 公司的安西先生將在本月晚些時候拜訪我們。\n\n【選項中文語義與詞性】\n(A) 為字根「paid」之詞性變化形\n(B) 為字根「pays」之詞性變化形\n(C) 為字根「will pay」之詞性變化形\n(D) 為字根「has paid」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) will pay。\n時間標示為 later this month（本月晚些時候），動詞應使用未來式 will pay。屬於時態變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_110_3", "no": "110", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Jim Thompson has decided to pursue a career in medicine _______ he still expresses a great interest in modern American arts.", "o": ["(A) since", "(B) so", "(C) although", "(D) unless"], "a": "C", "e": "【題目中文翻譯】\n儘管吉姆·湯普森仍對美國現代藝術表現出極大的興趣，但他已決定從事醫學事業。\n\n【選項中文語義與詞性】\n(A) 「since」（連接詞/關係詞）\n(B) 「so」（連接詞/關係詞）\n(C) 「although」（連接詞/關係詞）\n(D) 「unless」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (C) although。\n引導讓步狀語子句「雖然他仍對藝術有興趣」，用屬連接詞 although。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_111_3", "no": "111", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Lida Ward was a dependable team player, _______ good judgment and mature outlook resulted in a logical and reliable approach to her endeavors.", "o": ["(A) what", "(B) which", "(C) whom", "(D) whose"], "a": "D", "e": "【題目中文翻譯】\n莉達·沃德是一位可靠的團隊成員，她的良好判斷力和成熟眼光使其工作方法邏輯嚴密且可靠。\n\n【選項中文語義與詞性】\n(A) 「what」（連接詞/關係詞）\n(B) 「which」（連接詞/關係詞）\n(C) 「whom」（連接詞/關係詞）\n(D) 「whose」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (D) whose。\n先行詞為人 (Lida Ward)，修飾名詞片語 good judgment，需使用關係代名詞所有格 whose。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_112_3", "no": "112", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "With their concerted efforts, the research team at Pacific Laboratories has finally gained _______ results in their new synthetic fabric development.", "o": ["(A) satisfaction", "(B) satisfy", "(C) satisfactory", "(D) satisfactorily"], "a": "C", "e": "【題目中文翻譯】\n經過共同努力，太平洋實驗室的研究團隊終於在新合成纖維開發方面取得了令人滿意的成果。\n\n【選項中文語義與詞性】\n(A) 為字根「satisfaction」之詞性變化形\n(B) 為字根「satisfy」之詞性變化形\n(C) 為字根「satisfactory」之詞性變化形\n(D) 為字根「satisfactorily」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) satisfactory。\n修飾名詞 results，需填入形容詞 satisfactory（令人滿意的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_113_3", "no": "113", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "To attract customers to your online business, experts say you should _______ update your Web site.", "o": ["(A) continually", "(B) increasingly", "(C) particularly", "(D) recently"], "a": "A", "e": "【題目中文翻譯】\n為了吸引客戶關注您的線上業務，專家表示您應該不斷更新您的網站。\n\n【選項中文語義與詞性】\n(A) 「continually」（單字字義對照）\n(B) 「increasingly」（單字字義對照）\n(C) 「particularly」（單字字義對照）\n(D) 「recently」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) continually。\ncontinually update... 表示「持續不斷地更新...」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_114_3", "no": "114", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "After working intensely on it for months, Jim Hant was finally able to _______ the deal with the telecom giant.", "o": ["(A) close", "(B) draw", "(C) form", "(D) open"], "a": "A", "e": "【題目中文翻譯】\n經過數月的密集努力，吉姆·漢特終於能夠與這家電信巨頭達成交易。\n\n【選項中文語義與詞性】\n(A) 「close」（單字字義對照）\n(B) 「draw」（單字字義對照）\n(C) 「form」（單字字義對照）\n(D) 「open」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) close。\nclose the deal 為固定搭配，表示「達成交易/敲定協議」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_115_3", "no": "115", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "More than 350 _______ restaurants in the bay area are listed on this food_related online directory.", "o": ["(A) proactive", "(B) probable", "(C) productive", "(D) promising"], "a": "D", "e": "【題目中文翻譯】\n該美食相關線上目錄中列出了灣區 350 多家有前途的餐廳。\n\n【選項中文語義與詞性】\n(A) 「proactive」（單字字義對照）\n(B) 「probable」（單字字義對照）\n(C) 「productive」（單字字義對照）\n(D) 「promising」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) promising。\npromising restaurants 表示「有前途/發展潛力的餐廳」。4個選項為不同形容詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_116_3", "no": "116", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The product development team _______ us the new product if it had been ready in time.", "o": ["(A) would be shown", "(B) would have been shown", "(C) would have shown", "(D) would show"], "a": "C", "e": "【題目中文翻譯】\n如果新產品及時準備好，產品開發團隊本來會向我們展示它的。\n\n【選項中文語義與詞性】\n(A) 為字根「would be shown」之詞性變化形\n(B) 為字根「would have been shown」之詞性變化形\n(C) 為字根「would have shown」之詞性變化形\n(D) 為字根「would show」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) would have shown。\n假設法與過去事實相反：If + S + had p.p., S + would have p.p.。團隊主動向我們展示 (show us)，故選 would have shown。分類為「詞性」。"},
    {"id": "TOEIC_Part5_117_3", "no": "117", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Marble University is considered the top academic _______ in the world for marine biology.", "o": ["(A) instituted", "(B) institutions", "(C) institutional", "(D) institution"], "a": "D", "e": "【題目中文翻譯】\n馬爾堡大學被認為是世界上海洋生物學領域頂尖的學術機構。\n\n【選項中文語義與詞性】\n(A) 為字根「instituted」之詞性變化形\n(B) 為字根「institutions」之詞性變化形\n(C) 為字根「institutional」之詞性變化形\n(D) 為字根「institution」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) institution。\nthe top academic institution（單數名詞），修飾大學主詞。選項為同字根詞性及單複數變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_118_3", "no": "118", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Mr. Emerson has assigned the sales promotion work _______ Joyce Morgan.", "o": ["(A) as", "(B) to", "(C) over", "(D) for"], "a": "B", "e": "【題目中文翻譯】\n愛默生先生已將促銷工作指派給喬伊斯·摩根。\n\n【選項中文語義與詞性】\n(A) 「as」（介系詞/介系詞片語）\n(B) 「to」（介系詞/介系詞片語）\n(C) 「over」（介系詞/介系詞片語）\n(D) 「for」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (B) to。\nassign A to B 表示「將A指派給B」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_119_3", "no": "119", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Rebel Corporation is intent on becoming a major _______ in the world computer and communications market.", "o": ["(A) competition", "(B) force", "(C) lead", "(D) runner"], "a": "B", "e": "【題目中文翻譯】\nRebel 公司意圖成為世界電腦和通信市場的主要力量。\n\n【選項中文語義與詞性】\n(A) 「competition」（單字字義對照）\n(B) 「force」（單字字義對照）\n(C) 「lead」（單字字義對照）\n(D) 「runner」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) force。\na major force in the market 表示「市場上的主要力量/主要勢力」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_120_3", "no": "120", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Lower interest rates can positively affect corporate profits _______ decreased loan costs.", "o": ["(A) for", "(B) from", "(C) of", "(D) with"], "a": "D", "e": "【題目中文翻譯】\n較低的利率可以透過減少貸款成本對企業利潤產生積極影響。\n\n【選項中文語義與詞性】\n(A) 「for」（介系詞/介系詞片語）\n(B) 「from」（介系詞/介系詞片語）\n(C) 「of」（介系詞/介系詞片語）\n(D) 「with」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (D) with。\nwith decreased loan costs 介系詞片語表示「伴隨/透過減少的貸款成本」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_121_3", "no": "121", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The Managing Director said that the company would have to take drastic _______ to address this situation.", "o": ["(A) fashions", "(B) measures", "(C) methods", "(D) ways"], "a": "B", "e": "【題目中文翻譯】\n總經理表示公司將不得不採取嚴厲措施來解決這種情況。\n\n【選項中文語義與詞性】\n(A) 「fashions」（單字字義對照）\n(B) 「measures」（單字字義對照）\n(C) 「methods」（單字字義對照）\n(D) 「ways」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) measures。\ntake drastic measures 為固定搭配，表示「採取嚴厲/果斷措施」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_122_3", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "A cooking contest took place between two of the city's most _______ chefs.", "o": ["(A) compassionate", "(B) sincere", "(C) prominent", "(D) wealthy"], "a": "C", "e": "【題目中文翻譯】\n該市兩位最傑出的廚師之間舉行了一場烹飪比賽。\n\n【選項中文語義與詞性】\n(A) 「compassionate」（單字字義對照）\n(B) 「sincere」（單字字義對照）\n(C) 「prominent」（單字字義對照）\n(D) 「wealthy」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) prominent。\nprominent chefs 表示「傑出/著名的廚師」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_123_3", "no": "123", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "According to the manufacturer, NP_445B is equivalent _______ NT_38 that is out of production.", "o": ["(A) after", "(B) to", "(C) in", "(D) at"], "a": "B", "e": "【題目中文翻譯】\n據製造商稱，NP_445B 等同於已停產的 NT_38。\n\n【選項中文語義與詞性】\n(A) 「after」（介系詞/介系詞片語）\n(B) 「to」（介系詞/介系詞片語）\n(C) 「in」（介系詞/介系詞片語）\n(D) 「at」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (B) to。\nbe equivalent to... 為固定搭配，表示「等同於...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_124_3", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "This facility has conducted emergency _______ involving local police several times.", "o": ["(A) alarms", "(B) bills", "(C) drills", "(D) kits"], "a": "C", "e": "【題目中文翻譯】\n該設施已多次組織當地警察進行緊急演習。\n\n【選項中文語義與詞性】\n(A) 「alarms」（單字字義對照）\n(B) 「bills」（單字字義對照）\n(C) 「drills」（單字字義對照）\n(D) 「kits」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) drills。\nconduct emergency drills 表示「進行緊急演習」。4個選項為不同名詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_125_3", "no": "125", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Both the city mayor and the city council promised that they would immediately _______ funds for the popular project.", "o": ["(A) adequate", "(B) appropriate", "(C) proper", "(D) relevant"], "a": "B", "e": "【題目中文翻譯】\n市長和市議會都承諾，他們將立即為這個受歡迎的項目撥款。\n\n【選項中文語義與詞性】\n(A) 「adequate」（單字字義對照）\n(B) 「appropriate」（單字字義對照）\n(C) 「proper」（單字字義對照）\n(D) 「relevant」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) appropriate。\nappropriate funds 在此作動詞，表示「撥出款項/劃撥資金」。4個選項字義不同，分類為「字彙」。"},
    {"id": "TOEIC_Part5_126_3", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Starting next month, routine fire safety inspections will be _______ on a monthly basis.", "o": ["(A) alerted", "(B) conducted", "(C) engaged", "(D) protected"], "a": "B", "e": "【題目中文翻譯】\n從下個月開始，將每月進行定期消防安全檢查。\n\n【選項中文語義與詞性】\n(A) 「alerted」（單字字義對照）\n(B) 「conducted」（單字字義對照）\n(C) 「engaged」（單字字義對照）\n(D) 「protected」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) conducted。\ninspections will be conducted 表示「檢查將被執行/進行」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_127_3", "no": "127", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "If the paperwork arrives on time, _______ in the accounting division should process this payment by Friday.", "o": ["(A) whatever", "(B) someone", "(C) which", "(D) who"], "a": "B", "e": "【題目中文翻譯】\n如果文件按時到達，會計部門的人應該在星期五之前處理這筆付款。\n\n【選項中文語義與詞性】\n(A) 「whatever」（單字字義對照）\n(B) 「someone」（單字字義對照）\n(C) 「which」（單字字義對照）\n(D) 「who」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) someone。\nsomeone in the accounting division 表示「會計部門的某個人」。選項為不同不定代名詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_128_3", "no": "128", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Customer service representatives are specially trained in _______ with dissatisfied customers.", "o": ["(A) dealing", "(B) following", "(C) managing", "(D) persuading"], "a": "A", "e": "【題目中文翻譯】\n客戶服務代表接受過應對不滿意客戶的專門培訓。\n\n【選項中文語義與詞性】\n(A) 「dealing」（單字字義對照）\n(B) 「following」（單字字義對照）\n(C) 「managing」（單字字義對照）\n(D) 「persuading」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) dealing。\ndeal with... 表示「處理/應對...」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_129_3", "no": "129", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The investment firm has agreed _______ 100 million dollars for this amusement complex project.", "o": ["(A) being paid", "(B) paying", "(C) to pay", "(D) pay"], "a": "C", "e": "【題目中文翻譯】\n該投資公司已同意為該娛樂綜合體項目支付 1 億美元。\n\n【選項中文語義與詞性】\n(A) 為字根「being paid」之詞性變化形\n(B) 為字根「paying」之詞性變化形\n(C) 為字根「to pay」之詞性變化形\n(D) 為字根「pay」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) to pay。\nagree 後面接不定詞 to V (agree to pay)。屬動詞句型與詞性結構變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_130_3", "no": "130", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Ms. Moody was told she would be transferred to an _______ company sometime in the first quarter next year.", "o": ["(A) associable", "(B) artificial", "(C) affiliated", "(D) automatic"], "a": "C", "e": "【題目中文翻譯】\n穆迪女士被告知她將於明年第一季度的某個時候被調往一家關係企業/子公司。\n\n【選項中文語義與詞性】\n(A) 「associable」（單字字義對照）\n(B) 「artificial」（單字字義對照）\n(C) 「affiliated」（單字字義對照）\n(D) 「automatic」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) affiliated。\nan affiliated company 表示「關係企業/子公司」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_101_4", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The information session will provide an overview of the basic legal _______ that small businesses have been facing in the competitive market.", "o": ["(A) issuable", "(B) issued", "(C) issues", "(D) issuing"], "a": "C", "e": "【題目中文翻譯】\n簡報會將概述小企業在競爭市場中面臨的基本法律問題。\n\n【選項中文語義與詞性】\n(A) 為字根「issuable」之詞性變化形\n(B) 為字根「issued」之詞性變化形\n(C) 為字根「issues」之詞性變化形\n(D) 為字根「issuing」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) issues。\n修飾語形容詞 legal 後面接名詞 issues 作賓語。選項為同字根衍生詞變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_102_4", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The security guards _______ supposed to meet at 7:15 A.M. in front of the main gate of the event site.", "o": ["(A) are", "(B) has", "(C) have", "(D) is"], "a": "A", "e": "【題目中文翻譯】\n保安人員應於上午 7:15 在活動現場主門前集合。\n\n【選項中文語義與詞性】\n(A) 為字根「are」之詞性變化形\n(B) 為字根「has」之詞性變化形\n(C) 為字根「have」之詞性變化形\n(D) 為字根「is」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (A) are。\n主詞 The security guards 為複數名詞，be supposed to 結構中 be 動詞應用 are。屬於動詞一致性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_103_4", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Roberts finished _______ the newspaper article on global warming just before the deadline.", "o": ["(A) edit", "(B) editing", "(C) to edit", "(D) to editing"], "a": "B", "e": "【題目中文翻譯】\n羅伯茨先生在截止日期前剛剛完成了關於全球變暖的報紙文章的編輯。\n\n【選項中文語義與詞性】\n(A) 為字根「edit」之詞性變化形\n(B) 為字根「editing」之詞性變化形\n(C) 為字根「to edit」之詞性變化形\n(D) 為字根「to editing」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) editing。\nfinish 後接動名詞 Ving (finish editing)。屬於動詞句型變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_104_4", "no": "104", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "In case there is any change in _______ your address or phone number, please inform us as soon as possible.", "o": ["(A) either", "(B) both", "(C) neither", "(D) but also"], "a": "A", "e": "【題目中文翻譯】\n如果您的地址或電話號碼有任何變更，請儘快通知我們。\n\n【選項中文語義與詞性】\n(A) 「either」（連接詞/關係詞）\n(B) 「both」（連接詞/關係詞）\n(C) 「neither」（連接詞/關係詞）\n(D) 「but also」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (A) either。\neither A or B（A或B兩者之一）對等連接詞搭配。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_105_4", "no": "105", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Many critics praised the _______ performances in the movie, and it became a major hit.", "o": ["(A) impressed", "(B) impression", "(C) impressionable", "(D) impressive"], "a": "D", "e": "【題目中文翻譯】\n許多影評人讚揚了電影中令人印象深刻的表演，這部電影成為一部大熱之作。\n\n【選項中文語義與詞性】\n(A) 為字根「impressed」之詞性變化形\n(B) 為字根「impression」之詞性變化形\n(C) 為字根「impressionable」之詞性變化形\n(D) 為字根「impressive」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) impressive。\n修飾名詞 performances，應使用形容詞 impressive（令人印深刻的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_106_4", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "After the civil engineering firm submitted the necessary documents, City Hall let _______ go ahead with the bridgework.", "o": ["(A) their", "(B) theirs", "(C) them", "(D) they"], "a": "C", "e": "【題目中文翻譯】\n在土木工程公司提交必要的文件後，市政廳允許他們繼續進行橋樑工程。\n\n【選項中文語義與詞性】\n(A) 為字根「their」之詞性變化形\n(B) 為字根「theirs」之詞性變化形\n(C) 為字根「them」之詞性變化形\n(D) 為字根「they」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) them。\n使役動詞 let 後接受格代名詞 them 作受詞 (let them go)。屬代名詞格位變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_107_4", "no": "107", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "_______ to employment at Blackstone Financial, Inc., Ms. Nakayama served as a support staff member at Martin International Co.", "o": ["(A) Ahead", "(B) Before", "(C) Earlier", "(D) Prior"], "a": "D", "e": "【題目中文翻譯】\n在入職黑石金融公司之前，中山女士在馬丁國際公司擔任支援人員。\n\n【選項中文語義與詞性】\n(A) 「Ahead」（介系詞/介系詞片語）\n(B) 「Before」（介系詞/介系詞片語）\n(C) 「Earlier」（介系詞/介系詞片語）\n(D) 「Prior」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (D) Prior。\nprior to + N 表示「在...之前」，作介系詞片語使用。分類為「介系詞」。"},
    {"id": "TOEIC_Part5_108_4", "no": "108", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Of all the beverages in the taste test, Citrus Squeeze was chosen as the _______.", "o": ["(A) more refreshing", "(B) most refreshing", "(C) refresh", "(D) refreshing"], "a": "B", "e": "【題目中文翻譯】\n在品嘗測試的所有飲料中，Citrus Squeeze 被選為最令人心曠神怡的飲料。\n\n【選項中文語義與詞性】\n(A) 為字根「more refreshing」之詞性變化形\n(B) 為字根「most refreshing」之詞性變化形\n(C) 為字根「refresh」之詞性變化形\n(D) 為字根「refreshing」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) most refreshing。\nOf all the beverages（在所有飲料中）限定三者以上的範圍，用最高級 the most refreshing。分類為「詞性」。"},
    {"id": "TOEIC_Part5_109_4", "no": "109", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "They said their time was spent _______ at the lecture gaining a new perspective on the field of logistics.", "o": ["(A) productive", "(B) productively", "(C) productiveness", "(D) productivity"], "a": "B", "e": "【題目中文翻譯】\n他們說他們在講座上充實地度過了時間，獲得了物流領域的新視角。\n\n【選項中文語義與詞性】\n(A) 為字根「productive」之詞性變化形\n(B) 為字根「productively」之詞性變化形\n(C) 為字根「productiveness」之詞性變化形\n(D) 為字根「productivity」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) productively。\nspend time productively 用副詞修飾動詞被動結構 was spent。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_110_4", "no": "110", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Their new laptop is much more lightweight and inexpensive compared _______ their previous model.", "o": ["(A) for", "(B) in", "(C) of", "(D) to"], "a": "D", "e": "【題目中文翻譯】\n與之前的機型相比，他們的新款筆記本電腦更輕巧、更便宜。\n\n【選項中文語義與詞性】\n(A) 「for」（介系詞/介系詞片語）\n(B) 「in」（介系詞/介系詞片語）\n(C) 「of」（介系詞/介系詞片語）\n(D) 「to」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (D) to。\ncompared to... / compared with... 為固定介系詞片語「與...相比」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_111_4", "no": "111", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "A complimentary copy of our informative booklet, Smart Investment Guide, is available for all those _______ attend the seminar.", "o": ["(A) what", "(B) where", "(C) which", "(D) who"], "a": "D", "e": "【題目中文翻譯】\n所有參加研討會的人都可以免費獲得我們內容豐富的小冊子《明智投資指南》。\n\n【選項中文語義與詞性】\n(A) 「what」（連接詞/關係詞）\n(B) 「where」（連接詞/關係詞）\n(C) 「which」（連接詞/關係詞）\n(D) 「who」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (D) who。\nthose who attend...（那些參加...的人），先行詞 those 指人，引導關係子句需用關係代名詞 who。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_112_4", "no": "112", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Kim used his _______ in the finance industry to help his acquaintance obtain a job after graduating from college.", "o": ["(A) connecting", "(B) connections", "(C) connector", "(D) connects"], "a": "B", "e": "【題目中文翻譯】\n金先生利用他在金融界的關係，幫助他的熟人在大學畢業後找到了一份工作。\n\n【選項中文語義與詞性】\n(A) 為字根「connecting」之詞性變化形\n(B) 為字根「connections」之詞性變化形\n(C) 為字根「connector」之詞性變化形\n(D) 為字根「connects」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (B) connections。\n所有格 his 後面接名詞 connections（人脈關係）。選項為同字根衍生變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_113_4", "no": "113", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Recently, demand for domestic products has been increasing, _______ in the automotive sector.", "o": ["(A) especially", "(B) habitually", "(C) hardly", "(D) scarcely"], "a": "A", "e": "【題目中文翻譯】\n最近對國產產品的需求一直在增加，尤其是在汽車領域。\n\n【選項中文語義與詞性】\n(A) 「especially」（單字字義對照）\n(B) 「habitually」（單字字義對照）\n(C) 「hardly」（單字字義對照）\n(D) 「scarcely」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) especially。\nespecially in... 表示「特別是在...領域」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_114_4", "no": "114", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Some professional chefs recommend serrated kitchen knives because _______ they do not slice as smoothly as fine_edged ones, they never need sharpening.", "o": ["(A) instead", "(B) neither", "(C) still", "(D) while"], "a": "D", "e": "【題目中文翻譯】\n一些專業廚師推薦鋸齒廚刀，因為雖然它們切起來不如細刃廚刀平滑，但它們永遠不需要磨刀。\n\n【選項中文語義與詞性】\n(A) 「instead」（連接詞/關係詞）\n(B) 「neither」（連接詞/關係詞）\n(C) 「still」（連接詞/關係詞）\n(D) 「while」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (D) while。\n引導讓步對比子句「雖然...但是...」，需使用屬從屬連接詞 while。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_115_4", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "By the end of next month, Mr. Harrison's team will _______ this long_term marketing project.", "o": ["(A) be finished", "(B) finishing", "(C) have finished", "(D) have been finished"], "a": "C", "e": "【題目中文翻譯】\n到下個月底，哈里森先生的團隊將完成這個長期行銷項目。\n\n【選項中文語義與詞性】\n(A) 為字根「be finished」之詞性變化形\n(B) 為字根「finishing」之詞性變化形\n(C) 為字根「have finished」之詞性變化形\n(D) 為字根「have been finished」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) have finished。\nBy the end of next month 為未來完成式時間標記 (will have p.p.)，且團隊主動完成專案，故選 have finished。分類為「詞性」。"},
    {"id": "TOEIC_Part5_116_4", "no": "116", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Environmental activists have long advocated the use of more _______ energy sources such as solar and wind power.", "o": ["(A) diverse", "(B) monotonous", "(C) standardized", "(D) unified"], "a": "A", "e": "【題目中文翻譯】\n環保人士長期以來一直倡導使用更多多元化的能源，例如太陽能和風能。\n\n【選項中文語義與詞性】\n(A) 「diverse」（單字字義對照）\n(B) 「monotonous」（單字字義對照）\n(C) 「standardized」（單字字義對照）\n(D) 「unified」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (A) diverse。\ndiverse energy sources 表示「多元化/多樣化的能源」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_117_4", "no": "117", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "People attributed the company's improved business results _______ the decisiveness of the former CEO.", "o": ["(A) from", "(B) in", "(C) on", "(D) to"], "a": "D", "e": "【題目中文翻譯】\n人們將公司業績的改善歸功於前執行長的的果斷。\n\n【選項中文語義與詞性】\n(A) 「from」（介系詞/介系詞片語）\n(B) 「in」（介系詞/介系詞片語）\n(C) 「on」（介系詞/介系詞片語）\n(D) 「to」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (D) to。\nattribute A to B 為固定搭配，表示「將A歸因於/歸功於B」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_119_4", "no": "119", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The CEO mentioned that the employee's longtime effort finally _______ off as their yearly sales doubled.", "o": ["(A) cut", "(B) paid", "(C) put", "(D) set"], "a": "B", "e": "【題目中文翻譯】\n執行長提到，隨著年度銷售額翻倍，員工長期以來的努力終於得到了回報。\n\n【選項中文語義與詞性】\n(A) 「cut」（單字字義對照）\n(B) 「paid」（單字字義對照）\n(C) 「put」（單字字義對照）\n(D) 「set」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) paid。\npay off 為固定動詞片語，表示「得到回報/取得成功」。4個選項為不同動詞，分類為「字彙」。"},
    {"id": "TOEIC_Part5_120_4", "no": "120", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "As she thought about her job prospects in the current economy, Ms. Connor became _______ optimistic.", "o": ["(A) increase", "(B) increased", "(C) increasing", "(D) increasingly"], "a": "D", "e": "【題目中文翻譯】\n當她思考當前經濟形勢下的求職前景時，康納女士變得越來越樂觀。\n\n【選項中文語義與詞性】\n(A) 為字根「increase」之詞性變化形\n(B) 為字根「increased」之詞性變化形\n(C) 為字根「increasing」之詞性變化形\n(D) 為字根「increasingly」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (D) increasingly。\n修飾形容詞 optimistic，應填入副詞 increasingly（越來越/日趨地）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_121_4", "no": "121", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "We are writing to _______ about the schedule delay for the underground mall repair work.", "o": ["(A) acquire", "(B) conquer", "(C) inquire", "(D) require"], "a": "C", "e": "【題目中文翻譯】\n我們致函旨在詢問地下商場維修工程進度延誤的情況。\n\n【選項中文語義與詞性】\n(A) 「acquire」（單字字義對照）\n(B) 「conquer」（單字字義對照）\n(C) 「inquire」（單字字義對照）\n(D) 「require」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) inquire。\ninquire about... 表示「詢問/打聽...」。4個選項為拼寫相似但意義不同的生字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_122_4", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Everyone at the meeting was impressed with Mr. Lee's _______ plan for the coming trade show.", "o": ["(A) collaborate", "(B) elaborate", "(C) evaporate", "(D) incorporate"], "a": "B", "e": "【題目中文翻譯】\n會議上的每個人都對李先生為即將到來的貿易展覽會所做的周密計劃印象深刻。\n\n【選項中文語義與詞性】\n(A) 「collaborate」（單字字義對照）\n(B) 「elaborate」（單字字義對照）\n(C) 「evaporate」（單字字義對照）\n(D) 「incorporate」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) elaborate。\nelaborate plan 表示「精心的/周密的計劃」。4個選項為不同字彙，分類為「字彙」。"},
    {"id": "TOEIC_Part5_123_4", "no": "123", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "All the participants _______ this year's architecture competition submitted truly outstanding and innovative designs.", "o": ["(A) on", "(B) from", "(C) in", "(D) by"], "a": "C", "e": "【題目中文翻譯】\n今年建築競賽的所有參賽者都提交了非常優秀且富有創意的設計。\n\n【選項中文語義與詞性】\n(A) 「on」（介系詞/介系詞片語）\n(B) 「from」（介系詞/介系詞片語）\n(C) 「in」（介系詞/介系詞片語）\n(D) 「by」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (C) in。\nparticipants in the competition 表示「競賽的參賽者/參與者」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_124_4", "no": "124", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "There will be a temporary _______ of gas service next Friday, November 12 between noon and 4:00 P.M.", "o": ["(A) suspend", "(B) suspended", "(C) suspension", "(D) suspending"], "a": "C", "e": "【題目中文翻譯】\n下週五（11 月 12 日）中午 12:00 至下午 4:00 期間，天然氣服務將暫時中斷。\n\n【選項中文語義與詞性】\n(A) 為字根「suspend」之詞性變化形\n(B) 為字根「suspended」之詞性變化形\n(C) 為字根「suspension」之詞性變化形\n(D) 為字根「suspending」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) suspension。\n冠詞 a 與形容詞 temporary 後面接名詞 suspension（中斷/暫停）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_125_4", "no": "125", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The assembly line in the Hartford plant has been _______ automated over the past two decades.", "o": ["(A) finely", "(B) formerly", "(C) fully", "(D) frequently"], "a": "C", "e": "【題目中文翻譯】\n哈特福德工廠的裝配線在過去二十年中已實現完全自動化。\n\n【選項中文語義與詞性】\n(A) 「finely」（單字字義對照）\n(B) 「formerly」（單字字義對照）\n(C) 「fully」（單字字義對照）\n(D) 「frequently」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (C) fully。\nfully automated 表示「完全自動化的」。4個選項為不同副詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_126_4", "no": "126", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "_______ sales of the new product have picked up, the quarterly forecast will be met.", "o": ["(A) Because of", "(B) In case of", "(C) Now that", "(D) Unless"], "a": "C", "e": "【題目中文翻譯】\n既然新產品的銷售額有所好轉，季度預測目標將會實現。\n\n【選項中文語義與詞性】\n(A) 「Because of」（連接詞/關係詞）\n(B) 「In case of」（連接詞/關係詞）\n(C) 「Now that」（連接詞/關係詞）\n(D) 「Unless」（連接詞/關係詞）\n\n【文法與解題解析】\n本題考點分類為「連結詞」。正確答案為 (C) Now that。\n引導原因副詞子句（因為/既然...），且後接完整句子，應選屬連接詞的 Now that。分類為「連結詞」。"},
    {"id": "TOEIC_Part5_127_4", "no": "127", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "As he was a _______ technician, Mark Smith could easily figure out the problem with the network.", "o": ["(A) comprehensive", "(B) competent", "(C) formal", "(D) supplemental"], "a": "B", "e": "【題目中文翻譯】\n由於馬克·史密斯是一位勝任的技術人員，他可以輕鬆找出網路問題。\n\n【選項中文語義與詞性】\n(A) 「comprehensive」（單字字義對照）\n(B) 「competent」（單字字義對照）\n(C) 「formal」（單字字義對照）\n(D) 「supplemental」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (B) competent。\na competent technician 表示「一名勝任的/技術過硬的技術人員」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_128_4", "no": "128", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Emercy Corporation received many thanks from some local charities who will divide the donated clothes _______ themselves.", "o": ["(A) among", "(B) inside", "(C) through", "(D) without"], "a": "A", "e": "【題目中文翻譯】\n埃默西公司收到了當地一些慈善機構的許多感謝，這些機構將在他們之間分配捐贈的衣服。\n\n【選項中文語義與詞性】\n(A) 「among」（介系詞/介系詞片語）\n(B) 「inside」（介系詞/介系詞片語）\n(C) 「through」（介系詞/介系詞片語）\n(D) 「without」（介系詞/介系詞片語）\n\n【文法與解題解析】\n本題考點分類為「介系詞」。正確答案為 (A) among。\ndivide... among themselves 表示「在他們（多個慈善機構）之間分配...」。選項皆為介系詞，分類為「介系詞」。"},
    {"id": "TOEIC_Part5_129_4", "no": "129", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Our insurance underwriter has decided to cancel our policy so we will have to select an _______ insurance carrier.", "o": ["(A) alternated", "(B) alternating", "(C) alternative", "(D) alternator"], "a": "C", "e": "【題目中文翻譯】\n我們的保險承保人決定取消我們的保單，因此我們將不得不選擇另一家替代的保險公司。\n\n【選項中文語義與詞性】\n(A) 為字根「alternated」之詞性變化形\n(B) 為字根「alternating」之詞性變化形\n(C) 為字根「alternative」之詞性變化形\n(D) 為字根「alternator」之詞性變化形\n\n【文法與解題解析】\n本題考點分類為「詞性」。正確答案為 (C) alternative。\n修飾名詞片語 insurance carrier，需填入形容詞 alternative（替代的）。選項為同字根詞性變化，分類為「詞性」。"},
    {"id": "TOEIC_Part5_130_4", "no": "130", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The software designers thought their instructions were _______ enough, and they received almost no questions from users.", "o": ["(A) decreased", "(B) depressed", "(C) determined", "(D) detailed"], "a": "D", "e": "【題目中文翻譯】\n軟體設計師認為他們的說明足夠詳細，幾乎沒有收到使用者的疑問。\n\n【選項中文語義與詞性】\n(A) 「decreased」（單字字義對照）\n(B) 「depressed」（單字字義對照）\n(C) 「determined」（單字字義對照）\n(D) 「detailed」（單字字義對照）\n\n【文法與解題解析】\n本題考點分類為「字彙」。正確答案為 (D) detailed。\ndetailed enough 表示「足夠詳細」。4個選項為不同形容詞單字，分類為「字彙」。"},
    {"id": "TOEIC_Part5_101_5", "no": "101", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Duray Airlines offers delicious food and beverage _______.", "o": ["(A) fees", "(B) answers", "(C) options", "(D) tasks"], "a": "C", "e": "【題目中文翻譯】\n杜瑞航空提供美味的餐點與飲料選擇。\n\n【答案選項中文說明與詞性】\n選項為: (A) fees, (B) answers, (C) options, (D) tasks\n正確解答為: (C) options\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) options\n解析說明：本題屬於「字彙」題型。正確選項為 (C) options。"},
    {"id": "TOEIC_Part5_102_5", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The Oakshore region _______ large numbers of young professionals.", "o": ["(A) was attracted", "(B) has been attracted", "(C) attracting", "(D) attracts"], "a": "D", "e": "【題目中文翻譯】\n橡岸地區吸引了大量的年輕專業人士。\n\n【答案選項中文說明與詞性】\n選項為: (A) was attracted, (B) has been attracted, (C) attracting, (D) attracts\n正確解答為: (D) attracts\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) attracts\n解析說明：本題屬於「詞性」題型。正確選項為 (D) attracts。"},
    {"id": "TOEIC_Part5_103_5", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The sales report is due tomorrow, so please finish it _______.", "o": ["(A) easily", "(B) quickly", "(C) certainly", "(D) truly"], "a": "B", "e": "【題目中文翻譯】\n銷售報告明天到期，所以請儘快完成。\n\n【答案選項中文說明與詞性】\n選項為: (A) easily, (B) quickly, (C) certainly, (D) truly\n正確解答為: (B) quickly\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) quickly\n解析說明：本題屬於「詞性」題型。正確選項為 (B) quickly。"},
    {"id": "TOEIC_Part5_104_5", "no": "104", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Referring to the _______ in the user's manual will help you to identify the parts of the workbench.", "o": ["(A) illustrate", "(B) illustrator", "(C) illustration", "(D) illustrated"], "a": "C", "e": "【題目中文翻譯】\n參考使用手冊中的插圖將有助於您識別工作台的零件。\n\n【答案選項中文說明與詞性】\n選項為: (A) illustrate, (B) illustrator, (C) illustration, (D) illustrated\n正確解答為: (C) illustration\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) illustration\n解析說明：本題屬於「詞性」題型。正確選項為 (C) illustration。"},
    {"id": "TOEIC_Part5_105_5", "no": "105", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "No more than four passengers are permitted in _______ taxi operated by the Halligan Company.", "o": ["(A) any", "(B) all", "(C) some", "(D) such"], "a": "A", "e": "【題目中文翻譯】\n哈利根公司運營的任何計程車內最多只允許乘坐四名乘客。\n\n【答案選項中文說明與詞性】\n選項為: (A) any, (B) all, (C) some, (D) such\n正確解答為: (A) any\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) any\n解析說明：本題屬於「詞性」題型。正確選項為 (A) any。"},
    {"id": "TOEIC_Part5_106_5", "no": "106", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Sales of the Moro Camera dropped by 3 percent _______ the last quarter.", "o": ["(A) down", "(B) well", "(C) and", "(D) during"], "a": "D", "e": "【題目中文翻譯】\n莫羅相機的銷售額在上個季度下降了 3%。\n\n【答案選項中文說明與詞性】\n選項為: (A) down, (B) well, (C) and, (D) during\n正確解答為: (D) during\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) during\n解析說明：本題屬於「介系詞」題型。正確選項為 (D) during。"},
    {"id": "TOEIC_Part5_107_5", "no": "107", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The newest branch of the library is located _______ Pine Street, directly across from the post office.", "o": ["(A) into", "(B) among", "(C) until", "(D) on"], "a": "D", "e": "【題目中文翻譯】\n圖書館最新成立的分館位於松樹街，就在郵局正對面。\n\n【答案選項中文說明與詞性】\n選項為: (A) into, (B) among, (C) until, (D) on\n正確解答為: (D) on\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) on\n解析說明：本題屬於「介系詞」題型。正確選項為 (D) on。"},
    {"id": "TOEIC_Part5_108_5", "no": "108", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The property manager must ensure that renters understand _______ rental agreement.", "o": ["(A) their", "(B) they", "(C) theirs", "(D) them"], "a": "A", "e": "【題目中文翻譯】\n物業經理必須確保租客瞭解他們的租賃協議。\n\n【答案選項中文說明與詞性】\n選項為: (A) their, (B) they, (C) theirs, (D) them\n正確解答為: (A) their\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) their\n解析說明：本題屬於「詞性」題型。正確選項為 (A) their。"},
    {"id": "TOEIC_Part5_109_5", "no": "109", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "_______ Ms. Bai was not available to lead the board meeting, she was able to find a replacement.", "o": ["(A) Although", "(B) Whether", "(C) Instead", "(D) Accordingly"], "a": "A", "e": "【題目中文翻譯】\n雖然白女士無法主持董事會會議，但她找到了一位替補人選。\n\n【答案選項中文說明與詞性】\n選項為: (A) Although, (B) Whether, (C) Instead, (D) Accordingly\n正確解答為: (A) Although\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) Although\n解析說明：本題屬於「連結詞」題型。正確選項為 (A) Although。"},
    {"id": "TOEIC_Part5_110_5", "no": "110", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Once staff has had training in the new accounting software, they will be prepared to work _______.", "o": ["(A) independent", "(B) independently", "(C) independency", "(D) independence"], "a": "B", "e": "【題目中文翻譯】\n一旦員工接受了新會計軟體的培訓，他們將準備好獨立工作。\n\n【答案選項中文說明與詞性】\n選項為: (A) independent, (B) independently, (C) independency, (D) independence\n正確解答為: (B) independently\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) independently\n解析說明：本題屬於「詞性」題型。正確選項為 (B) independently。"},
    {"id": "TOEIC_Part5_111_5", "no": "111", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Nuts from Quintana Orchards can be a _______ source of vitamins and minerals for a nutritious diet.", "o": ["(A) long", "(B) various", "(C) rich", "(D) careful"], "a": "C", "e": "【題目中文翻譯】\n昆塔納果園的堅果可作為營養飲食中維生素和礦物質的豐富來源。\n\n【答案選項中文說明與詞性】\n選項為: (A) long, (B) various, (C) rich, (D) careful\n正確解答為: (C) rich\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) rich\n解析說明：本題屬於「字彙」題型。正確選項為 (C) rich。"},
    {"id": "TOEIC_Part5_112_5", "no": "112", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "To maintain the Cheerbrew coffeemaker properly, wipe it with a _______ sponge after each use.", "o": ["(A) moist", "(B) moistens", "(C) moistly", "(D) moisten"], "a": "A", "e": "【題目中文翻譯】\n為妥善維護 Cheerbrew 咖啡機，每次使用後請用濕海綿擦拭。\n\n【答案選項中文說明與詞性】\n選項為: (A) moist, (B) moistens, (C) moistly, (D) moisten\n正確解答為: (A) moist\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) moist\n解析說明：本題屬於「詞性」題型。正確選項為 (A) moist。"},
    {"id": "TOEIC_Part5_113_5", "no": "113", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Research shows that an online marketing strategy is vital for survival in the _______ competitive athletic shoe market.", "o": ["(A) skillfully", "(B) increasingly", "(C) accidentally", "(D) meaningfully"], "a": "B", "e": "【題目中文翻譯】\n研究表明，網路行銷策略對於在競爭日益激烈的運動鞋市場中生存至關重要。\n\n【答案選項中文說明與詞性】\n選項為: (A) skillfully, (B) increasingly, (C) accidentally, (D) meaningfully\n正確解答為: (B) increasingly\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) increasingly\n解析說明：本題屬於「詞性」題型。正確選項為 (B) increasingly。"},
    {"id": "TOEIC_Part5_114_5", "no": "114", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Tomorrow's session will train participants on _______ to prepare containers for overseas shipments.", "o": ["(A) what", "(B) how", "(C) that", "(D) then"], "a": "B", "e": "【題目中文翻譯】\n明天的課程將培訓學員如何為海外運輸準備貨櫃。\n\n【答案選項中文說明與詞性】\n選項為: (A) what, (B) how, (C) that, (D) then\n正確解答為: (B) how\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(B) how\n解析說明：本題屬於「連結詞」題型。正確選項為 (B) how。"},
    {"id": "TOEIC_Part5_115_5", "no": "115", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Applications received _______ the October 15 deadline will not be processed.", "o": ["(A) after", "(B) already", "(C) while", "(D) often"], "a": "A", "e": "【題目中文翻譯】\n在 10 月 15 日截止日期之後收到的申請將不予處理。\n\n【答案選項中文說明與詞性】\n選項為: (A) after, (B) already, (C) while, (D) often\n正確解答為: (A) after\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) after\n解析說明：本題屬於「介系詞」題型。正確選項為 (A) after。"},
    {"id": "TOEIC_Part5_116_5", "no": "116", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Customers expressed dissatisfaction with the cost of the phone, but complaints about the user interface were relatively _______.", "o": ["(A) rarest", "(B) rare", "(C) rarity", "(D) rarely"], "a": "B", "e": "【題目中文翻譯】\n顧客對手機的費用表示不滿，但對使用者介面的抱怨相對較少。\n\n【答案選項中文說明與詞性】\n選項為: (A) rarest, (B) rare, (C) rarity, (D) rarely\n正確解答為: (B) rare\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) rare\n解析說明：本題屬於「詞性」題型。正確選項為 (B) rare。"},
    {"id": "TOEIC_Part5_117_5", "no": "117", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Tickets to the museum's special exhibit may be ordered in advance on the Web site _______ purchased upon arrival.", "o": ["(A) or", "(B) for", "(C) where", "(D) since"], "a": "A", "e": "【題目中文翻譯】\n博物館特展門票可在網站預訂，或在到達時購買。\n\n【答案選項中文說明與詞性】\n選項為: (A) or, (B) for, (C) where, (D) since\n正確解答為: (A) or\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) or\n解析說明：本題屬於「連結詞」題型。正確選項為 (A) or。"},
    {"id": "TOEIC_Part5_118_4", "no": "118", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Two water-quality studies, which _______ last week, reflect the hard work of the Water Resource Council to keep local water clean.", "o": ["(A) were released", "(B) were being released", "(C) had released", "(D) had been releasing"], "a": "A", "e": "【題目中文翻譯】\n上週發布的兩項水質研究反映了水資源委員會為保持當地水質清潔所做的努力。\n\n【答案選項中文說明與詞性】\n選項為: (A) were released, (B) were being released, (C) had released, (D) had been releasing\n正確解答為: (A) were released\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) were released\n解析說明：本題屬於「詞性」題型。正確選項為 (A) were released。"},
    {"id": "TOEIC_Part5_119_5", "no": "119", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "_______ the efforts of cycling enthusiasts, the proposal to resurface bicycle paths in County Kildare was defeated yesterday.", "o": ["(A) Throughout", "(B) Besides", "(C) Despite", "(D) Versus"], "a": "C", "e": "【題目中文翻譯】\n儘管自行車愛好者做出了努力，基爾代爾郡自行車道鋪平提案昨天仍遭否決。\n\n【答案選項中文說明與詞性】\n選項為: (A) Throughout, (B) Besides, (C) Despite, (D) Versus\n正確解答為: (C) Despite\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) Despite\n解析說明：本題屬於「介系詞」題型。正確選項為 (C) Despite。"},
    {"id": "TOEIC_Part5_120_5", "no": "120", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Crum Carpetings's profits have risen _______ since the company introduced a new environmentally friendly carpet line.", "o": ["(A) steadiness", "(B) steadying", "(C) steadily", "(D) steadied"], "a": "C", "e": "【題目中文翻譯】\n自該公司推出新的環保地毯系列以來，Crum 地毯的利潤持續穩定上升。\n\n【答案選項中文說明與詞性】\n選項為: (A) steadiness, (B) steadying, (C) steadily, (D) steadied\n正確解答為: (C) steadily\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) steadily\n解析說明：本題屬於「詞性」題型。正確選項為 (C) steadily。"},
    {"id": "TOEIC_Part5_121_5", "no": "121", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Guideline Technologies _______ in archiving records and retrieving lost data.", "o": ["(A) consists", "(B) interests", "(C) inspects", "(D) specializes"], "a": "D", "e": "【題目中文翻譯】\nGuideline 科技專門從事檔案記錄歸檔與遺失資料檢索。\n\n【答案選項中文說明與詞性】\n選項為: (A) consists, (B) interests, (C) inspects, (D) specializes\n正確解答為: (D) specializes\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) specializes\n解析說明：本題屬於「字彙」題型。正確選項為 (D) specializes。"},
    {"id": "TOEIC_Part5_122_5", "no": "122", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The mayoral candidates are competing for television _______.", "o": ["(A) having exposed", "(B) exposed", "(C) expose", "(D) exposure"], "a": "D", "e": "【題目中文翻譯】\n市長候選人正在爭取電視曝光率。\n\n【答案選項中文說明與詞性】\n選項為: (A) having exposed, (B) exposed, (C) expose, (D) exposure\n正確解答為: (D) exposure\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) exposure\n解析說明：本題屬於「詞性」題型。正確選項為 (D) exposure。"},
    {"id": "TOEIC_Part5_123_5", "no": "123", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Employees should submit time sheets by noon today _______ the payroll office can distribute paychecks on schedule.", "o": ["(A) so that", "(B) in order to", "(C) that is", "(D) in case of"], "a": "A", "e": "【題目中文翻譯】\n員工應在今天中午之前提交工時表，以便薪酬辦公室能按時發放薪水。\n\n【答案選項中文說明與詞性】\n選項為: (A) so that, (B) in order to, (C) that is, (D) in case of\n正確解答為: (A) so that\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) so that\n解析說明：本題屬於「連結詞」題型。正確選項為 (A) so that。"},
    {"id": "TOEIC_Part5_124_5", "no": "124", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Suburban residents are _______ in favor of expanding Highway 589 to relieve traffic congestion.", "o": ["(A) overwhelm", "(B) overwhelmingly", "(C) overwhelming", "(D) overwhelms"], "a": "B", "e": "【題目中文翻譯】\n郊區居民壓倒性地支持擴建 589 號公路以緩解交通擁堵。\n\n【答案選項中文說明與詞性】\n選項為: (A) overwhelm, (B) overwhelmingly, (C) overwhelming, (D) overwhelms\n正確解答為: (B) overwhelmingly\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) overwhelmingly\n解析說明：本題屬於「詞性」題型。正確選項為 (B) overwhelmingly。"},
    {"id": "TOEIC_Part5_125_5", "no": "125", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Business travel is _______ for Shawton Associates by Young-Pyo Kim at Wright Air Transit.", "o": ["(A) equipped", "(B) attributed", "(C) coordinated", "(D) concurred"], "a": "C", "e": "【題目中文翻譯】\nShawton Associates 的商務差旅由 Wright Air Transit 的 金永標 負責協調。\n\n【答案選項中文說明與詞性】\n選項為: (A) equipped, (B) attributed, (C) coordinated, (D) concurred\n正確解答為: (C) coordinated\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) coordinated\n解析說明：本題屬於「字彙」題型。正確選項為 (C) coordinated。"},
    {"id": "TOEIC_Part5_126_5", "no": "126", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Most models of the Remagine laptop computer now come with a _______ keyboard.", "o": ["(A) removability", "(B) remove", "(C) removable", "(D) remover"], "a": "C", "e": "【題目中文翻譯】\nRemagine 筆記型電腦的大多數機型現在都配有可拆卸式鍵盤。\n\n【答案選項中文說明與詞性】\n選項為: (A) removability, (B) remove, (C) removable, (D) remover\n正確解答為: (C) removable\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) removable\n解析說明：本題屬於「詞性」題型。正確選項為 (C) removable。"},
    {"id": "TOEIC_Part5_127_5", "no": "127", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "With the recent surge in electronic sales, industry analysts are anticipating that the device-to-person _______ will soon surpass earlier predictions.", "o": ["(A) division", "(B) fraction", "(C) part", "(D) ratio"], "a": "D", "e": "【題目中文翻譯】\n隨著近期電子產品銷量的急劇增加，產業分析師預計人均設備比例很快將超出之前的預測。\n\n【答案選項中文說明與詞性】\n選項為: (A) division, (B) fraction, (C) part, (D) ratio\n正確解答為: (D) ratio\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) ratio\n解析說明：本題屬於「字彙」題型。正確選項為 (D) ratio。"},
    {"id": "TOEIC_Part5_128_5", "no": "128", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "In response to consumer complaints, assembly instructions for the model 481 bookshelf have been _______.", "o": ["(A) acknowledged", "(B) estimated", "(C) controlled", "(D) simplified"], "a": "D", "e": "【題目中文翻譯】\n為了回應消費者的抱怨，481 型書架的組裝說明已經過簡化。\n\n【答案選項中文說明與詞性】\n選項為: (A) acknowledged, (B) estimated, (C) controlled, (D) simplified\n正確解答為: (D) simplified\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) simplified\n解析說明：本題屬於「字彙」題型。正確選項為 (D) simplified。"},
    {"id": "TOEIC_Part5_129_5", "no": "129", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Choose an _______ sized air conditioner for your company's needs, as larger models use more energy.", "o": ["(A) affirmatively", "(B) appropriately", "(C) unexpectedly", "(D) extensively"], "a": "B", "e": "【題目中文翻譯】\n為您公司的需求選擇適當大小的冷氣機，因為較大的機型消耗更多能源。\n\n【答案選項中文說明與詞性】\n選項為: (A) affirmatively, (B) appropriately, (C) unexpectedly, (D) extensively\n正確解答為: (B) appropriately\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) appropriately\n解析說明：本題屬於「詞性」題型。正確選項為 (B) appropriately。"},
    {"id": "TOEIC_Part5_130_5", "no": "130", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Owing to his knowledge of historic buildings, Luis Harmon was _______ to lead the Main Street Restoration Project.", "o": ["(A) persuasion", "(B) persuasively", "(C) persuaded", "(D) persuading"], "a": "C", "e": "【題目中文翻譯】\n由於對歷史建築的了解，路易斯·哈蒙被說服主持主街修復專案。\n\n【答案選項中文說明與詞性】\n選項為: (A) persuasion, (B) persuasively, (C) persuaded, (D) persuading\n正確解答為: (C) persuaded\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) persuaded\n解析說明：本題屬於「詞性」題型。正確選項為 (C) persuaded。"},
    {"id": "TOEIC_Part5_101_6", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Most of our clients are _______ about the prospect of our showroom moving to a larger space.", "o": ["(A) exciting", "(B) to excite", "(C) excites", "(D) excited"], "a": "D", "e": "【題目中文翻譯】\n我們的大多數客戶對我們展示廳搬遷到更大空間的前景感到興奮。\n\n【答案選項中文說明與詞性】\n選項為: (A) exciting, (B) to excite, (C) excites, (D) excited\n正確解答為: (D) excited\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) excited\n解析說明：本題屬於「詞性」題型。正確選項為 (D) excited。"},
    {"id": "TOEIC_Part5_102_6", "no": "102", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "_______ their review of the documents, Ms. Oliveira will make changes to the paperwork.", "o": ["(A) After", "(B) Now", "(C) Soon", "(D) Next"], "a": "A", "e": "【題目中文翻譯】\n在審閱文件之後，奧利維拉女士將對文書工作進行修改。\n\n【答案選項中文說明與詞性】\n選項為: (A) After, (B) Now, (C) Soon, (D) Next\n正確解答為: (A) After\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) After\n解析說明：本題屬於「介系詞」題型。正確選項為 (A) After。"},
    {"id": "TOEIC_Part5_103_6", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Contact technical support for any needed _______ with software issues.", "o": ["(A) assist", "(B) assistant", "(C) assisted", "(D) assistance"], "a": "D", "e": "【題目中文翻譯】\n如果軟體問題需要任何協助，請聯繫技術支援。\n\n【答案選項中文說明與詞性】\n選項為: (A) assist, (B) assistant, (C) assisted, (D) assistance\n正確解答為: (D) assistance\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) assistance\n解析說明：本題屬於「詞性」題型。正確選項為 (D) assistance。"},
    {"id": "TOEIC_Part5_104_6", "no": "104", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Willington Hair Salon will be open _______ weekend starting in May.", "o": ["(A) every", "(B) from", "(C) enough", "(D) since"], "a": "A", "e": "【題目中文翻譯】\n韋靈頓髮型沙龍將從 5 月開始每個週末都營業。\n\n【答案選項中文說明與詞性】\n選項為: (A) every, (B) from, (C) enough, (D) since\n正確解答為: (A) every\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) every\n解析說明：本題屬於「字彙」題型。正確選項為 (A) every。"},
    {"id": "TOEIC_Part5_105_6", "no": "105", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "When accessing _______ billing statement online, be sure to look for new discount offers.", "o": ["(A) yourselves", "(B) yours", "(C) your", "(D) you"], "a": "C", "e": "【題目中文翻譯】\n線上查看您的帳單時，請務必留意最新的折扣優惠。\n\n【答案選項中文說明與詞性】\n選項為: (A) yourselves, (B) yours, (C) your, (D) you\n正確解答為: (C) your\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) your\n解析說明：本題屬於「詞性」題型。正確選項為 (C) your。"},
    {"id": "TOEIC_Part5_106_6", "no": "106", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The work shifts at Stella's Confectionary are eight hours long and _______ a 30-minute break for lunch.", "o": ["(A) prepare", "(B) release", "(C) assemble", "(D) include"], "a": "D", "e": "【題目中文翻譯】\n史黛拉糖果店的班次為 8 小時，包含 30 分鐘的中午休息時間。\n\n【答案選項中文說明與詞性】\n選項為: (A) prepare, (B) release, (C) assemble, (D) include\n正確解答為: (D) include\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) include\n解析說明：本題屬於「字彙」題型。正確選項為 (D) include。"},
    {"id": "TOEIC_Part5_107_6", "no": "107", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The timer on the lamp is designed to turn it off _______ to reduce energy use.", "o": ["(A) automatic", "(B) automatically", "(C) automated", "(D) automate"], "a": "B", "e": "【題目中文翻譯】\n燈上的定時器旨在自動關閉燈以減少能源使用。\n\n【答案選項中文說明與詞性】\n選項為: (A) automatic, (B) automatically, (C) automated, (D) automate\n正確解答為: (B) automatically\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) automatically\n解析說明：本題屬於「詞性」題型。正確選項為 (B) automatically。"},
    {"id": "TOEIC_Part5_108_6", "no": "108", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Employees who will be commuting to the Foster Street facility should request parking permits _______ the end of the month.", "o": ["(A) under", "(B) against", "(C) along", "(D) before"], "a": "D", "e": "【題目中文翻譯】\n將通往福斯特街設施通勤的員工應在月底前申請停車許可證。\n\n【答案選項中文說明與詞性】\n選項為: (A) under, (B) against, (C) along, (D) before\n正確解答為: (D) before\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) before\n解析說明：本題屬於「介系詞」題型。正確選項為 (D) before。"},
    {"id": "TOEIC_Part5_109_6", "no": "109", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Our Italian wool jackets are _______ for many occasions, from a formal dinner to a casual evening with friends.", "o": ["(A) to suit", "(B) suitably", "(C) suitable", "(D) suit"], "a": "C", "e": "【題目中文翻譯】\n我們的義大利羊毛夾克適合多種場合，從正式晚宴到與朋友的休閒聚會。\n\n【答案選項中文說明與詞性】\n選項為: (A) to suit, (B) suitably, (C) suitable, (D) suit\n正確解答為: (C) suitable\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) suitable\n解析說明：本題屬於「詞性」題型。正確選項為 (C) suitable。"},
    {"id": "TOEIC_Part5_110_6", "no": "110", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Dale Department Store will have a special sale on jewelry _______ before the holidays.", "o": ["(A) sensitively", "(B) extremely", "(C) immediately", "(D) figuratively"], "a": "C", "e": "【題目中文翻譯】\n戴爾百貨公司將在假期前立即舉行珠寶特別特賣。\n\n【答案選項中文說明與詞性】\n選項為: (A) sensitively, (B) extremely, (C) immediately, (D) figuratively\n正確解答為: (C) immediately\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) immediately\n解析說明：本題屬於「字彙」題型。正確選項為 (C) immediately。"},
    {"id": "TOEIC_Part5_111_6", "no": "111", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Mr. Hobbes _______ a sincere interest in a long-term career at Lassen Bank.", "o": ["(A) expressed", "(B) pointed", "(C) arranged", "(D) studied"], "a": "A", "e": "【題目中文翻譯】\n霍布斯先生表達了對在拉森銀行長期發展職涯的誠摯興趣。\n\n【答案選項中文說明與詞性】\n選項為: (A) expressed, (B) pointed, (C) arranged, (D) studied\n正確解答為: (A) expressed\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) expressed\n解析說明：本題屬於「字彙」題型。正確選項為 (A) expressed。"},
    {"id": "TOEIC_Part5_112_6", "no": "112", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The carpet in the lobby of the Chiang Mai Opera House will be replaced with material _______ is easier to maintain.", "o": ["(A) what", "(B) where", "(C) that", "(D) this"], "a": "C", "e": "【題目中文翻譯】\n清邁歌劇院大廳的地毯將更換為更容易維護的材質。\n\n【答案選項中文說明與詞性】\n選項為: (A) what, (B) where, (C) that, (D) this\n正確解答為: (C) that\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) that\n解析說明：本題屬於「連結詞」題型。正確選項為 (C) that。"},
    {"id": "TOEIC_Part5_113_6", "no": "113", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Hunt's Gift Shop carries a wide selection of _______, including the Swinnville Daily News and West Bay Monthly.", "o": ["(A) publication", "(B) publications", "(C) publish", "(D) published"], "a": "B", "e": "【題目中文翻譯】\nHunt 禮品店提供豐富的出版品選擇，包括斯溫威爾日報和西灣月刊。\n\n【答案選項中文說明與詞性】\n選項為: (A) publication, (B) publications, (C) publish, (D) published\n正確解答為: (B) publications\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) publications\n解析說明：本題屬於「詞性」題型。正確選項為 (B) publications。"},
    {"id": "TOEIC_Part5_114_6", "no": "114", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Engineers in the Welber Machine Factory in Cologne work to correct minor flaws in the designs of _______ drilling systems.", "o": ["(A) confused", "(B) complex", "(C) informative", "(D) cautious"], "a": "B", "e": "【題目中文翻譯】\n科隆 Welber 機器工廠的工程師致力於修正複雜鑽井系統設計中的微小缺陷。\n\n【答案選項中文說明與詞性】\n選項為: (A) confused, (B) complex, (C) informative, (D) cautious\n正確解答為: (B) complex\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) complex\n解析說明：本題屬於「字彙」題型。正確選項為 (B) complex。"},
    {"id": "TOEIC_Part5_115_6", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "If the plumbing problem _______, we recommend that you contact the product manufacturer.", "o": ["(A) to persist", "(B) was persisting", "(C) persists", "(D) persistence"], "a": "C", "e": "【題目中文翻譯】\n如果管道問題持續存在，我們建議您聯繫產品製造商。\n\n【答案選項中文說明與詞性】\n選項為: (A) to persist, (B) was persisting, (C) persists, (D) persistence\n正確解答為: (C) persists\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) persists\n解析說明：本題屬於「詞性」題型。正確選項為 (C) persists。"},
    {"id": "TOEIC_Part5_116_6", "no": "116", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "You will receive a _______ e-mail from the Nicoya Hotel verifying your travel plans within two hours of making your reservation.", "o": ["(A) sponsor", "(B) confirmation", "(C) margin", "(D) permit"], "a": "B", "e": "【題目中文翻譯】\n預訂後兩小時內，您將收到來自 Nicoya 飯店的確認電子郵件，核實您的行程計畫。\n\n【答案選項中文說明與詞性】\n選項為: (A) sponsor, (B) confirmation, (C) margin, (D) permit\n正確解答為: (B) confirmation\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) confirmation\n解析說明：本題屬於「字彙」題型。正確選項為 (B) confirmation。"},
    {"id": "TOEIC_Part5_117_6", "no": "117", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Move-It Storage provides a variety of container sizes to help store belongings _______.", "o": ["(A) compact", "(B) compactly", "(C) compacted", "(D) compacting"], "a": "A", "e": "【題目中文翻譯】\nMove-It 儲物公司提供多種大小的收納箱，幫助緊湊地存放物品。\n\n【答案選項中文說明與詞性】\n選項為: (A) compact, (B) compactly, (C) compacted, (D) compacting\n正確解答為: (A) compact\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) compact\n解析說明：本題屬於「詞性」題型。正確選項為 (A) compact。"},
    {"id": "TOEIC_Part5_118_5", "no": "118", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The new plant director, Ha-Jae Cheon, will be _______ for reducing the maintenance costs at the Tamarindo facility.", "o": ["(A) fortunate", "(B) possible", "(C) senseless", "(D) responsible"], "a": "D", "e": "【題目中文翻譯】\n新任廠長 Ha-Jae Cheon 將負責降低 Tamarindo 設施的維護成本。\n\n【答案選項中文說明與詞性】\n選項為: (A) fortunate, (B) possible, (C) senseless, (D) responsible\n正確解答為: (D) responsible\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) responsible\n解析說明：本題屬於「字彙」題型。正確選項為 (D) responsible。"},
    {"id": "TOEIC_Part5_119_6", "no": "119", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Lefert's Market will close two hours earlier _______ usual next Tuesday.", "o": ["(A) than", "(B) but", "(C) above", "(D) when"], "a": "A", "e": "【題目中文翻譯】\n萊費特超市下週二將比平常提早兩小時關門。\n\n【答案選項中文說明與詞性】\n選項為: (A) than, (B) but, (C) above, (D) when\n正確解答為: (A) than\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) than\n解析說明：本題屬於「介系詞」題型。正確選項為 (A) than。"},
    {"id": "TOEIC_Part5_120_6", "no": "120", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Caldwell Computers accepts returns _______ products have not been removed from the packaging.", "o": ["(A) in order that", "(B) such as", "(C) in case", "(D) as long as"], "a": "D", "e": "【題目中文翻譯】\n只要產品未拆封，Caldwell 電腦公司接受退貨。\n\n【答案選項中文說明與詞性】\n選項為: (A) in order that, (B) such as, (C) in case, (D) as long as\n正確解答為: (D) as long as\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) as long as\n解析說明：本題屬於「連結詞」題型。正確選項為 (D) as long as。"},
    {"id": "TOEIC_Part5_121_6", "no": "121", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Until last month Kanyan, Inc., _______ farming equipment for CEK Agriculture.", "o": ["(A) manufacturing", "(B) manufactured", "(C) is manufacturing", "(D) was manufactured"], "a": "B", "e": "【題目中文翻譯】\n直到上個月，Kanyan 公司一直為 CEK 農業生產農用設備。\n\n【答案選項中文說明與詞性】\n選項為: (A) manufacturing, (B) manufactured, (C) is manufacturing, (D) was manufactured\n正確解答為: (B) manufactured\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) manufactured\n解析說明：本題屬於「詞性」題型。正確選項為 (B) manufactured。"},
    {"id": "TOEIC_Part5_122_6", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Sign up now for deals available _______ Platinum members of the Bordner Gym Club.", "o": ["(A) exclusively", "(B) financially", "(C) relatively", "(D) productively"], "a": "A", "e": "【題目中文翻譯】\n立即報名享受專為 Bordner 健身俱樂部白金會員提供的獨家優惠。\n\n【答案選項中文說明與詞性】\n選項為: (A) exclusively, (B) financially, (C) relatively, (D) productively\n正確解答為: (A) exclusively\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) exclusively\n解析說明：本題屬於「字彙」題型。正確選項為 (A) exclusively。"},
    {"id": "TOEIC_Part5_123_6", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The printers sold by Mitaka Innovations at a discounted price are of _______ quality to those sold elsewhere.", "o": ["(A) equivalencies", "(B) equivalent", "(C) equivalently", "(D) equivalence"], "a": "B", "e": "【題目中文翻譯】\nMitaka Innovations 以折扣價售出的印表機品質與其他地方售出的相當。\n\n【答案選項中文說明與詞性】\n選項為: (A) equivalencies, (B) equivalent, (C) equivalently, (D) equivalence\n正確解答為: (B) equivalent\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) equivalent\n解析說明：本題屬於「詞性」題型。正確選項為 (B) equivalent。"},
    {"id": "TOEIC_Part5_124_6", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "In addition to a salary, Inquell Insurance associates are paid a _______ based on a percentage of sales.", "o": ["(A) commission", "(B) promotion", "(C) donation", "(D) permission"], "a": "A", "e": "【題目中文翻譯】\n除了固定薪水外，Inquell 保險公司的專員還可獲得按銷售額百分比計算的佣金。\n\n【答案選項中文說明與詞性】\n選項為: (A) commission, (B) promotion, (C) donation, (D) permission\n正確解答為: (A) commission\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) commission\n解析說明：本題屬於「字彙」題型。正確選項為 (A) commission。"},
    {"id": "TOEIC_Part5_125_6", "no": "125", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Aeronomatic Footwear guarantees delivery within ten business days, _______ merchandise may arrive even more quickly.", "o": ["(A) beside", "(B) if", "(C) although", "(D) whenever"], "a": "C", "e": "【題目中文翻譯】\nAeronomatic 鞋業保證在十個工作天內送達，儘管商品可能會更快送達。\n\n【答案選項中文說明與詞性】\n選項為: (A) beside, (B) if, (C) although, (D) whenever\n正確解答為: (C) although\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) although\n解析說明：本題屬於「連結詞」題型。正確選項為 (C) although。"},
    {"id": "TOEIC_Part5_126_6", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "At the meeting on June 4, Ms. Srisati will _______ all misunderstandings surrounding the new phone system.", "o": ["(A) look out", "(B) check in", "(C) clear up", "(D) take off"], "a": "C", "e": "【題目中文翻譯】\n在 6 月 4 日的會議上，Srisati 女士將澄清圍繞新電話系統的所有誤解。\n\n【答案選項中文說明與詞性】\n選項為: (A) look out, (B) check in, (C) clear up, (D) take off\n正確解答為: (C) clear up\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) clear up\n解析說明：本題屬於「字彙」題型。正確選項為 (C) clear up。"},
    {"id": "TOEIC_Part5_127_6", "no": "127", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "With the new Web site enhancements, Hill Street Design customers will be able to view a _______ of recent purchases.", "o": ["(A) voucher", "(B) coupon", "(C) summary", "(D) payment"], "a": "C", "e": "【題目中文翻譯】\n憑藉新網站的功能增強，Hill Street Design 的客戶將能夠查看最近購買的摘要。\n\n【答案選項中文說明與詞性】\n選項為: (A) voucher, (B) coupon, (C) summary, (D) payment\n正確解答為: (C) summary\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) summary\n解析說明：本題屬於「字彙」題型。正確選項為 (C) summary。"},
    {"id": "TOEIC_Part5_128_6", "no": "128", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The executive team of Tranmelin Industries is determining _______ divisions will transfer to the West Coast next year.", "o": ["(A) any", "(B) none", "(C) each", "(D) which"], "a": "D", "e": "【題目中文翻譯】\nTranmelin 工業的高層管理團隊正在決定明年哪些部門將轉移到西海岸。\n\n【答案選項中文說明與詞性】\n選項為: (A) any, (B) none, (C) each, (D) which\n正確解答為: (D) which\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) which\n解析說明：本題屬於「連結詞」題型。正確選項為 (D) which。"},
    {"id": "TOEIC_Part5_129_6", "no": "129", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The Fitzon Gallery has been the _______ promoter of the arts in Worthington, sponsoring numerous public events.", "o": ["(A) precise", "(B) separate", "(C) certain", "(D) primary"], "a": "D", "e": "【題目中文翻譯】\nFitzon 畫廊一直沃辛頓藝術活動的主要推廣者，贊助了許多公開活動。\n\n【答案選項中文說明與詞性】\n選項為: (A) precise, (B) separate, (C) certain, (D) primary\n正確解答為: (D) primary\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) primary\n解析說明：本題屬於「字彙」題型。正確選項為 (D) primary。"},
    {"id": "TOEIC_Part5_130_6", "no": "130", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The travel agent was able to obtain flights for the conference speakers _______ the last-minute request.", "o": ["(A) aboard", "(B) despite", "(C) aside", "(D) beyond"], "a": "B", "e": "【題目中文翻譯】\n儘管是最後一刻提出的要求，旅行社經案仍能為會議講者訂到航班。\n\n【答案選項中文說明與詞性】\n選項為: (A) aboard, (B) despite, (C) aside, (D) beyond\n正確解答為: (B) despite\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) despite\n解析說明：本題屬於「介系詞」題型。正確選項為 (B) despite。"},
    {"id": "TOEIC_Part5_101_7", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "This discounted train ticket is _______ only at certain times of the day.", "o": ["(A) valid", "(B) validate", "(C) validating", "(D) validation"], "a": "A", "e": "【題目中文翻譯】\n這張折扣火車票僅在一天中的特定時間有效。\n\n【答案選項中文說明與詞性】\n選項為: (A) valid, (B) validate, (C) validating, (D) validation\n正確解答為: (A) valid\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) valid\n解析說明：本題屬於「詞性」題型。正確選項為 (A) valid。"},
    {"id": "TOEIC_Part5_102_7", "no": "102", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "To participate in the Advantage Discount program, _______ the registration form on our Web site.", "o": ["(A) reply", "(B) inquire", "(C) complete", "(D) apply"], "a": "C", "e": "【題目中文翻譯】\n要參與 Advantage 折扣計劃，請填妥我們網站上的註冊表單。\n\n【答案選項中文說明與詞性】\n選項為: (A) reply, (B) inquire, (C) complete, (D) apply\n正確解答為: (C) complete\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) complete\n解析說明：本題屬於「字彙」題型。正確選項為 (C) complete。"},
    {"id": "TOEIC_Part5_103_7", "no": "103", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Ms. Srisati is unavailable today _______ she is flying to Mumbai.", "o": ["(A) because", "(B) how", "(C) regarding", "(D) sooner"], "a": "A", "e": "【題目中文翻譯】\nSrisati 女士今天抽不出空，因為她要飛往孟買。\n\n【答案選項中文說明與詞性】\n選項為: (A) because, (B) how, (C) regarding, (D) sooner\n正確解答為: (A) because\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) because\n解析說明：本題屬於「連結詞」題型。正確選項為 (A) because。"},
    {"id": "TOEIC_Part5_104_7", "no": "104", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The contract _______ states that the tenants must renew their rental-property agreement by March 1.", "o": ["(A) clear", "(B) clearly", "(C) clearer", "(D) cleared"], "a": "B", "e": "【題目中文翻譯】\n合約中明確規定，租客必須在 3 月 1 日前續簽租賃協議。\n\n【答案選項中文說明與詞性】\n選項為: (A) clear, (B) clearly, (C) clearer, (D) cleared\n正確解答為: (B) clearly\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) clearly\n解析說明：本題屬於「詞性」題型。正確選項為 (B) clearly。"},
    {"id": "TOEIC_Part5_105_7", "no": "105", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Aiko Arts plans to host a reception _______ the artist, Remco Koeman.", "o": ["(A) except", "(B) for", "(C) off", "(D) into"], "a": "B", "e": "【題目中文翻譯】\nAiko 藝術中心計畫為藝術家 Remco Koeman 舉辦招待會。\n\n【答案選項中文說明與詞性】\n選項為: (A) except, (B) for, (C) off, (D) into\n正確解答為: (B) for\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) for\n解析說明：本題屬於「介系詞」題型。正確選項為 (B) for。"},
    {"id": "TOEIC_Part5_106_7", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Unfortunately, replacing the copy machine will cost more than _______ had anticipated.", "o": ["(A) we", "(B) us", "(C) our", "(D) ours"], "a": "A", "e": "【題目中文翻譯】\n不幸的是，更換影印機的費用超出了我們的預期。\n\n【答案選項中文說明與詞性】\n選項為: (A) we, (B) us, (C) our, (D) ours\n正確解答為: (A) we\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) we\n解析說明：本題屬於「詞性」題型。正確選項為 (A) we。"},
    {"id": "TOEIC_Part5_107_7", "no": "107", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Your Polytonics e-mail account will be set up _______ you arrive on your first day.", "o": ["(A) at", "(B) around", "(C) until", "(D) before"], "a": "D", "e": "【題目中文翻譯】\n您的 Polytonics 電子郵件帳號將在您第一天報到前設定完成。\n\n【答案選項中文說明與詞性】\n選項為: (A) at, (B) around, (C) until, (D) before\n正確解答為: (D) before\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) before\n解析說明：本題屬於「介系詞」題型。正確選項為 (D) before。"},
    {"id": "TOEIC_Part5_108_7", "no": "108", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Oaza Electronics worked _______ with our team to facilitate the development of the computerized training system.", "o": ["(A) hardly", "(B) nearly", "(C) closely", "(D) relatively"], "a": "C", "e": "【題目中文翻譯】\nOaza 電子與我們的團隊緊密合作，促進電腦化培訓系統的開發。\n\n【答案選項中文說明與詞性】\n選項為: (A) hardly, (B) nearly, (C) closely, (D) relatively\n正確解答為: (C) closely\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) closely\n解析說明：本題屬於「字彙」題型。正確選項為 (C) closely。"},
    {"id": "TOEIC_Part5_109_7", "no": "109", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Financial adviser Jenna Sotulo helps professionals devise a _______ for managing their finances.", "o": ["(A) prediction", "(B) gesture", "(C) strategy", "(D) request"], "a": "C", "e": "【題目中文翻譯】\n財務顧問 Jenna Sotulo 協助專業人士制定管理個人財務的策略。\n\n【答案選項中文說明與詞性】\n選項為: (A) prediction, (B) gesture, (C) strategy, (D) request\n正確解答為: (C) strategy\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) strategy\n解析說明：本題屬於「字彙」題型。正確選項為 (C) strategy。"},
    {"id": "TOEIC_Part5_110_7", "no": "110", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Each employee must coordinate with management so that _______ time off can be properly scheduled.", "o": ["(A) alone", "(B) individual", "(C) isolating", "(D) separated"], "a": "B", "e": "【題目中文翻譯】\n每位員工必須與管理層協調，以便妥善安排個人休假。\n\n【答案選項中文說明與詞性】\n選項為: (A) alone, (B) individual, (C) isolating, (D) separated\n正確解答為: (B) individual\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) individual\n解析說明：本題屬於「字彙」題型。正確選項為 (B) individual。"},
    {"id": "TOEIC_Part5_111_7", "no": "111", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The cost of building Juniper High Towers exceeded the contractor's original _______ by over £5,000.00.", "o": ["(A) estimating", "(B) estimate", "(C) estimated", "(D) estimator"], "a": "B", "e": "【題目中文翻譯】\n建造杜松高塔的成本超出了承包商最初估計的 5,000 英鎊以上。\n\n【答案選項中文說明與詞性】\n選項為: (A) estimating, (B) estimate, (C) estimated, (D) estimator\n正確解答為: (B) estimate\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) estimate\n解析說明：本題屬於「詞性」題型。正確選項為 (B) estimate。"},
    {"id": "TOEIC_Part5_112_7", "no": "112", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "At Links Fine Meats, we pride _______ on providing the highest-quality products on the market.", "o": ["(A) oneself", "(B) yourselves", "(C) itself", "(D) ourselves"], "a": "D", "e": "【題目中文翻譯】\n在 Links 精選肉品，我們以提供市場上最高品質的產品為榮。\n\n【答案選項中文說明與詞性】\n選項為: (A) oneself, (B) yourselves, (C) itself, (D) ourselves\n正確解答為: (D) ourselves\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) ourselves\n解析說明：本題屬於「詞性」題型。正確選項為 (D) ourselves。"},
    {"id": "TOEIC_Part5_113_7", "no": "113", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "_______ he is usually quiet around the office, Mr. Heineman is known for his witty and engaging public speeches.", "o": ["(A) Although", "(B) Otherwise", "(C) Despite", "(D) Instead"], "a": "A", "e": "【題目中文翻譯】\n儘管在辦公室裡平時比較安靜，Heineman 先生仍以風趣且吸引人的公開演講而聞名。\n\n【答案選項中文說明與詞性】\n選項為: (A) Although, (B) Otherwise, (C) Despite, (D) Instead\n正確解答為: (A) Although\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) Although\n解析說明：本題屬於「連結詞」題型。正確選項為 (A) Although。"},
    {"id": "TOEIC_Part5_114_7", "no": "114", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ancient Chitimacha baskets are _______ featured in the Louisiana Museum of Archeology.", "o": ["(A) prominent", "(B) prominently", "(C) prominence", "(D) prominences"], "a": "B", "e": "【題目中文翻譯】\n古代奇蒂馬查竹籃在路易斯安那考古博物館中被顯著展出。\n\n【答案選項中文說明與詞性】\n選項為: (A) prominent, (B) prominently, (C) prominence, (D) prominences\n正確解答為: (B) prominently\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) prominently\n解析說明：本題屬於「詞性」題型。正確選項為 (B) prominently。"},
    {"id": "TOEIC_Part5_115_7", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "_______ tea and coffee are available in the lobby for all guests of the Farrison Hotel.", "o": ["(A) Compliment", "(B) To compliment", "(C) Complimented", "(D) Complimentary"], "a": "D", "e": "【題目中文翻譯】\nFarrison 飯店大廳為所有住客免費提供茶和咖啡。\n\n【答案選項中文說明與詞性】\n選項為: (A) Compliment, (B) To compliment, (C) Complimented, (D) Complimentary\n正確解答為: (D) Complimentary\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) Complimentary\n解析說明：本題屬於「詞性」題型。正確選項為 (D) Complimentary。"},
    {"id": "TOEIC_Part5_116_7", "no": "116", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "_______ representatives of Light Cloud Airlines, flights are rarely overbooked.", "o": ["(A) As opposed to", "(B) In addition to", "(C) According to", "(D) Prior to"], "a": "C", "e": "【題目中文翻譯】\n根據輕雲航空代表的說法，航班極少發生超訂現象。\n\n【答案選項中文說明與詞性】\n選項為: (A) As opposed to, (B) In addition to, (C) According to, (D) Prior to\n正確解答為: (C) According to\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) According to\n解析說明：本題屬於「介系詞」題型。正確選項為 (C) According to。"},
    {"id": "TOEIC_Part5_117_7", "no": "117", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Mr. Krause will reorganize the supply room _______ the cabinets are delivered.", "o": ["(A) overall", "(B) due to", "(C) once", "(D) soon"], "a": "C", "e": "【題目中文翻譯】\nKrause 先生將在櫃子送達後重新整理供應室。\n\n【答案選項中文說明與詞性】\n選項為: (A) overall, (B) due to, (C) once, (D) soon\n正確解答為: (C) once\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) once\n解析說明：本題屬於「連結詞」題型。正確選項為 (C) once。"},
    {"id": "TOEIC_Part5_118_6", "no": "118", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "By completing employee-satisfaction surveys anonymously, workers can more _______ state their concerns about the workplace.", "o": ["(A) wholly", "(B) openly", "(C) favorably", "(D) laboriously"], "a": "B", "e": "【題目中文翻譯】\n透過匿名完成員工滿意度調查，員工可以更坦率地說明他們對職場的疑慮。\n\n【答案選項中文說明與詞性】\n選項為: (A) wholly, (B) openly, (C) favorably, (D) laboriously\n正確解答為: (B) openly\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) openly\n解析說明：本題屬於「字彙」題型。正確選項為 (B) openly。"},
    {"id": "TOEIC_Part5_119_7", "no": "119", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The final blueprints must _______ by Ms. Ito after the final draft is produced.", "o": ["(A) approve", "(B) be approved", "(C) approving", "(D) to approve"], "a": "B", "e": "【題目中文翻譯】\n最終草圖產出後，必須由伊藤女士核准。\n\n【答案選項中文說明與詞性】\n選項為: (A) approve, (B) be approved, (C) approving, (D) to approve\n正確解答為: (B) be approved\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) be approved\n解析說明：本題屬於「詞性」題型。正確選項為 (B) be approved。"},
    {"id": "TOEIC_Part5_120_7", "no": "120", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "This sewing workshop is ideal for beginner tailors _______ professionals who would like to refresh their knowledge.", "o": ["(A) but", "(B) either", "(C) as well as", "(D) additionally"], "a": "C", "e": "【題目中文翻譯】\n這個裁縫工作坊非常適合初學者裁縫以及想溫習知識的專業人士。\n\n【答案選項中文說明與詞性】\n選項為: (A) but, (B) either, (C) as well as, (D) additionally\n正確解答為: (C) as well as\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) as well as\n解析說明：本題屬於「連結詞」題型。正確選項為 (C) as well as。"},
    {"id": "TOEIC_Part5_121_7", "no": "121", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "All posters and flyers must be removed from the bulletin board _______ 48 hours after the event has occurred.", "o": ["(A) within", "(B) among", "(C) unless", "(D) while"], "a": "A", "e": "【題目中文翻譯】\n所有海報和傳單必須在活動發生後 48 小時內從公告欄撤下。\n\n【答案選項中文說明與詞性】\n選項為: (A) within, (B) among, (C) unless, (D) while\n正確解答為: (A) within\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) within\n解析說明：本題屬於「介系詞」題型。正確選項為 (A) within。"},
    {"id": "TOEIC_Part5_122_7", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The _______ technology used in pots by Claypol Housewares keeps the handles from getting too hot to touch.", "o": ["(A) warm", "(B) frequent", "(C) unattached", "(D) innovative"], "a": "D", "e": "【題目中文翻譯】\nClaypol 家品在鍋具中使用的創新技術可防止手把過熱無法觸摸。\n\n【答案選項中文說明與詞性】\n選項為: (A) warm, (B) frequent, (C) unattached, (D) innovative\n正確解答為: (D) innovative\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) innovative\n解析說明：本題屬於「字彙」題型。正確選項為 (D) innovative。"},
    {"id": "TOEIC_Part5_123_7", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "There are a number of free Web-based _______ that provide tips for locating information in historical databases.", "o": ["(A) tutorials", "(B) tutoring", "(C) tutored", "(D) tutor"], "a": "A", "e": "【題目中文翻譯】\n有許多免費的網路教學課程，提供在歷史資料庫中尋找資訊的技巧。\n\n【答案選項中文說明與詞性】\n選項為: (A) tutorials, (B) tutoring, (C) tutored, (D) tutor\n正確解答為: (A) tutorials\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) tutorials\n解析說明：本題屬於「詞性」題型。正確選項為 (A) tutorials。"},
    {"id": "TOEIC_Part5_124_7", "no": "124", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The person hired must be able to adapt _______ to changes in work assignments and schedules.", "o": ["(A) readies", "(B) readily", "(C) readiness", "(D) ready"], "a": "B", "e": "【題目中文翻譯】\n應聘者必須能夠迅速適應工作分配和日程安排的變化。\n\n【答案選項中文說明與詞性】\n選項為: (A) readies, (B) readily, (C) readiness, (D) ready\n正確解答為: (B) readily\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) readily\n解析說明：本題屬於「詞性」題型。正確選項為 (B) readily。"},
    {"id": "TOEIC_Part5_125_7", "no": "125", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Organizational behavior specialist Ray Majory believes a good sense of humor in a leader can increase the quality of _______ in the team.", "o": ["(A) declaration", "(B) statement", "(C) message", "(D) communication"], "a": "D", "e": "【題目中文翻譯】\n組織行為專家 Ray Majory 認為領導者的良好幽默感可以提高團隊溝通的品質。\n\n【答案選項中文說明與詞性】\n選項為: (A) declaration, (B) statement, (C) message, (D) communication\n正確解答為: (D) communication\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) communication\n解析說明：本題屬於「字彙」題型。正確選項為 (D) communication。"},
    {"id": "TOEIC_Part5_126_7", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Portsmouth's agricultural industry has always found ways to _______ itself by growing different crops and finding new markets.", "o": ["(A) reinvest", "(B) reuse", "(C) reassess", "(D) reinvent"], "a": "D", "e": "【題目中文翻譯】\n波特斯茅斯的農業一直透過種植不同作物和尋找新市場來重新重塑自我。\n\n【答案選項中文說明與詞性】\n選項為: (A) reinvest, (B) reuse, (C) reassess, (D) reinvent\n正確解答為: (D) reinvent\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) reinvent\n解析說明：本題屬於「字彙」題型。正確選項為 (D) reinvent。"},
    {"id": "TOEIC_Part5_127_7", "no": "127", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "While some countries have made huge investments in the Caribbean lately, others have reduced _______.", "o": ["(A) themselves", "(B) theirs", "(C) their", "(D) they"], "a": "B", "e": "【題目中文翻譯】\n雖然最近有一些國家在加勒比地區進行了巨額投資，但其他國家減少了投資。\n\n【答案選項中文說明與詞性】\n選項為: (A) themselves, (B) theirs, (C) their, (D) they\n正確解答為: (B) theirs\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) theirs\n解析說明：本題屬於「詞性」題型。正確選項為 (B) theirs。"},
    {"id": "TOEIC_Part5_128_7", "no": "128", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The ethics committee cited the potential benefits of the research project while _______ its high cost.", "o": ["(A) acknowledging", "(B) to acknowledge", "(C) has acknowledged", "(D) acknowledge"], "a": "A", "e": "【題目中文翻譯】\n倫理委員會在承認研究專案成本高昂的同時，也列舉了該專案的潛在利益。\n\n【答案選項中文說明與詞性】\n選項為: (A) acknowledging, (B) to acknowledge, (C) has acknowledged, (D) acknowledge\n正確解答為: (A) acknowledging\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) acknowledging\n解析說明：本題屬於「詞性」題型。正確選項為 (A) acknowledging。"},
    {"id": "TOEIC_Part5_129_7", "no": "129", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The report describes the environmental impact on lakes and rivers of using _______ energy sources.", "o": ["(A) together", "(B) hopeful", "(C) regulatory", "(D) renewable"], "a": "D", "e": "【題目中文翻譯】\n該報告描述了使用可再生能源對湖泊和河流造成的環境影響。\n\n【答案選項中文說明與詞性】\n選項為: (A) together, (B) hopeful, (C) regulatory, (D) renewable\n正確解答為: (D) renewable\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) renewable\n解析說明：本題屬於「字彙」題型。正確選項為 (D) renewable。"},
    {"id": "TOEIC_Part5_130_7", "no": "130", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Any decorations on the ceilings or walls must be fully removed, including any material used to _______ them to the surfaces.", "o": ["(A) adhere", "(B) attract", "(C) construct", "(D) sustain"], "a": "A", "e": "【題目中文翻譯】\n天花板或牆壁上的任何裝飾物必須完全拆除，包括將其黏附於表面上的任何材料。\n\n【答案選項中文說明與詞性】\n選項為: (A) adhere, (B) attract, (C) construct, (D) sustain\n正確解答為: (A) adhere\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) adhere\n解析說明：本題屬於「字彙」題型。正確選項為 (A) adhere。"},
    {"id": "TOEIC_Part5_101_8", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The Tetra Corporation complies with all local and national _______.", "o": ["(A) regulate", "(B) regulated", "(C) regulatory", "(D) regulations"], "a": "D", "e": "【題目中文翻譯】\nTetra 公司遵守所有地方與國家法規。\n\n【答案選項中文說明與詞性】\n選項為: (A) regulate, (B) regulated, (C) regulatory, (D) regulations\n正確解答為: (D) regulations\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) regulations\n解析說明：本題屬於「詞性」題型。正確選項為 (D) regulations。"},
    {"id": "TOEIC_Part5_102_8", "no": "102", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "If you are not satisfied with your purchase _______ CXT Electronics, return it within 30 days for a full refund.", "o": ["(A) to", "(B) out", "(C) from", "(D) along"], "a": "C", "e": "【題目中文翻譯】\n如果您對從 CXT 電子購買的產品不滿意，請在 30 天內退回以獲得全額退款。\n\n【答案選項中文說明與詞性】\n選項為: (A) to, (B) out, (C) from, (D) along\n正確解答為: (C) from\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) from\n解析說明：本題屬於「介系詞」題型。正確選項為 (C) from。"},
    {"id": "TOEIC_Part5_103_8", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ms. Anderson has just received her invitation, so we cannot yet confirm whether _______ will attend the end-of-year banquet.", "o": ["(A) she", "(B) her", "(C) hers", "(D) herself"], "a": "A", "e": "【題目中文翻譯】\n安德森女士剛收到邀請函，因此我們尚無法確認她是否會出席年底宴會。\n\n【答案選項中文說明與詞性】\n選項為: (A) she, (B) her, (C) hers, (D) herself\n正確解答為: (A) she\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) she\n解析說明：本題屬於「詞性」題型。正確選項為 (A) she。"},
    {"id": "TOEIC_Part5_104_8", "no": "104", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "As part of the writing workshop, participants will read their compositions _______ to the group.", "o": ["(A) throughout", "(B) aloud", "(C) meanwhile", "(D) significantly"], "a": "B", "e": "【題目中文翻譯】\n作為寫作工作坊的一部分，參與者將向小組大聲朗讀他們的作文。\n\n【答案選項中文說明與詞性】\n選項為: (A) throughout, (B) aloud, (C) meanwhile, (D) significantly\n正確解答為: (B) aloud\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) aloud\n解析說明：本題屬於「字彙」題型。正確選項為 (B) aloud。"},
    {"id": "TOEIC_Part5_105_8", "no": "105", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Our programmers have benefited from the rigorous _______ required by the company.", "o": ["(A) trainee", "(B) trains", "(C) training", "(D) trained"], "a": "C", "e": "【題目中文翻譯】\n我們的程式設計師受益於公司要求的嚴格培訓。\n\n【答案選項中文說明與詞性】\n選項為: (A) trainee, (B) trains, (C) training, (D) trained\n正確解答為: (C) training\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) training\n解析說明：本題屬於「詞性」題型。正確選項為 (C) training。"},
    {"id": "TOEIC_Part5_106_8", "no": "106", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "A recent _______ of restaurants across the nation suggests that people are dining out much more frequently.", "o": ["(A) collection", "(B) cuisine", "(C) survey", "(D) supply"], "a": "C", "e": "【題目中文翻譯】\n最近一項全國餐廳調查顯示人們外出就餐的頻率大幅增加。\n\n【答案選項中文說明與詞性】\n選項為: (A) collection, (B) cuisine, (C) survey, (D) supply\n正確解答為: (C) survey\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) survey\n解析說明：本題屬於「字彙」題型。正確選項為 (C) survey。"},
    {"id": "TOEIC_Part5_107_8", "no": "107", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "During the summer, the Clayborough Museum _______ its hours until 10:00 P.M. on the weekend.", "o": ["(A) extends", "(B) extending", "(C) extensions", "(D) extendable"], "a": "A", "e": "【題目中文翻譯】\n夏季期間，Clayborough 博物館週末開放時間延長至晚上 10:00。\n\n【答案選項中文說明與詞性】\n選項為: (A) extends, (B) extending, (C) extensions, (D) extendable\n正確解答為: (A) extends\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) extends\n解析說明：本題屬於「詞性」題型。正確選項為 (A) extends。"},
    {"id": "TOEIC_Part5_108_8", "no": "108", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "After reviewing the latest real-estate reports, Ms. González _______ the sale of the property.", "o": ["(A) replaced", "(B) invested", "(C) commented", "(D) authorized"], "a": "D", "e": "【題目中文翻譯】\n審閱最新的不動產報告後，González 女士批准授權出售該房產。\n\n【答案選項中文說明與詞性】\n選項為: (A) replaced, (B) invested, (C) commented, (D) authorized\n正確解答為: (D) authorized\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) authorized\n解析說明：本題屬於「字彙」題型。正確選項為 (D) authorized。"},
    {"id": "TOEIC_Part5_109_8", "no": "109", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Atlas Printing _______ can accommodate large orders within 24 hours.", "o": ["(A) general", "(B) generalize", "(C) generalized", "(D) generally"], "a": "D", "e": "【題目中文翻譯】\nAtlas 印刷公司通常可以在 24 小時內承接大型訂單。\n\n【答案選項中文說明與詞性】\n選項為: (A) general, (B) generalize, (C) generalized, (D) generally\n正確解答為: (D) generally\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) generally\n解析說明：本題屬於「詞性」題型。正確選項為 (D) generally。"},
    {"id": "TOEIC_Part5_110_8", "no": "110", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The Kwon Group employee handbook contains _______ information about payroll, benefits, and terms of employment.", "o": ["(A) every", "(B) entire", "(C) whole", "(D) complete"], "a": "D", "e": "【題目中文翻譯】\n權氏集團員工手冊包含有關薪資、福利和聘用條款的完整資訊。\n\n【答案選項中文說明與詞性】\n選項為: (A) every, (B) entire, (C) whole, (D) complete\n正確解答為: (D) complete\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) complete\n解析說明：本題屬於「字彙」題型。正確選項為 (D) complete。"},
    {"id": "TOEIC_Part5_111_8", "no": "111", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Shim has decided that he will present the figures to the board of trustees _______ rather than appoint someone else to do it.", "o": ["(A) his", "(B) himself", "(C) him", "(D) he"], "a": "B", "e": "【題目中文翻譯】\n沈先生決定親自向董事會展示數據，而不是指定其他人來做。\n\n【答案選項中文說明與詞性】\n選項為: (A) his, (B) himself, (C) him, (D) he\n正確解答為: (B) himself\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) himself\n解析說明：本題屬於「詞性」題型。正確選項為 (B) himself。"},
    {"id": "TOEIC_Part5_112_8", "no": "112", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "_______ he arrived in Indonesia, risk analyst Hoi-Tung Lai has been assessing the spending of Jakarta's middle class.", "o": ["(A) While", "(B) During", "(C) Since", "(D) For"], "a": "C", "e": "【題目中文翻譯】\n自從抵達印尼以來，風險分析師黎海通一直在評估雅加達中產階級的支出。\n\n【答案選項中文說明與詞性】\n選項為: (A) While, (B) During, (C) Since, (D) For\n正確解答為: (C) Since\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) Since\n解析說明：本題屬於「連結詞」題型。正確選項為 (C) Since。"},
    {"id": "TOEIC_Part5_113_8", "no": "113", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Robert Lum is one of the most _______ leaders in the import-export business.", "o": ["(A) persuasive", "(B) persuade", "(C) persuasively", "(D) persuades"], "a": "A", "e": "【題目中文翻譯】\nRobert Lum 是進出口業務中最具說服力的領導者之一。\n\n【答案選項中文說明與詞性】\n選項為: (A) persuasive, (B) persuade, (C) persuasively, (D) persuades\n正確解答為: (A) persuasive\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) persuasive\n解析說明：本題屬於「詞性」題型。正確選項為 (A) persuasive。"},
    {"id": "TOEIC_Part5_114_8", "no": "114", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Compared with other dairy products, yogurt has remained _______ inexpensive.", "o": ["(A) thoroughly", "(B) relatively", "(C) early", "(D) minimally"], "a": "B", "e": "【題目中文翻譯】\n與其他乳製品相比，優格的價格相對便宜。\n\n【答案選項中文說明與詞性】\n選項為: (A) thoroughly, (B) relatively, (C) early, (D) minimally\n正確解答為: (B) relatively\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) relatively\n解析說明：本題屬於「字彙」題型。正確選項為 (B) relatively。"},
    {"id": "TOEIC_Part5_115_8", "no": "115", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Please place all orders for new office furniture _______ February 17.", "o": ["(A) despite", "(B) before", "(C) inside", "(D) when"], "a": "B", "e": "【題目中文翻譯】\n請在 2 月 17 日之前下所有新辦公家具的訂單。\n\n【答案選項中文說明與詞性】\n選項為: (A) despite, (B) before, (C) inside, (D) when\n正確解答為: (B) before\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) before\n解析說明：本題屬於「介系詞」題型。正確選項為 (B) before。"},
    {"id": "TOEIC_Part5_116_8", "no": "116", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The Oit Institute designs successful training videos, but the process _______ to take longer than expected.", "o": ["(A) finds", "(B) shows", "(C) works", "(D) tends"], "a": "D", "e": "【題目中文翻譯】\nOit 研究所設計了成功的培訓影片，但該過程往往比預期的時間更長。\n\n【答案選項中文說明與詞性】\n選項為: (A) finds, (B) shows, (C) works, (D) tends\n正確解答為: (D) tends\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) tends\n解析說明：本題屬於「字彙」題型。正確選項為 (D) tends。"},
    {"id": "TOEIC_Part5_117_8", "no": "117", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Two candidates were recently interviewed for the marketing position, and _______ were impressive.", "o": ["(A) some", "(B) both", "(C) any", "(D) either"], "a": "B", "e": "【題目中文翻譯】\n最近有兩名候選人接受了行銷職位的面試，兩人都讓人印象深刻。\n\n【答案選項中文說明與詞性】\n選項為: (A) some, (B) both, (C) any, (D) either\n正確解答為: (B) both\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) both\n解析說明：本題屬於「字彙」題型。正確選項為 (B) both。"},
    {"id": "TOEIC_Part5_118_7", "no": "118", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "If Mr. Itoh is unable to attend the conference in Brasilia, then Ms. Gruber will speak in his _______.", "o": ["(A) place", "(B) purpose", "(C) concern", "(D) permission"], "a": "A", "e": "【題目中文翻譯】\n如果伊藤先生無法出席在巴西利亞舉行的會議，格魯伯女士將代替他發言。\n\n【答案選項中文說明與詞性】\n選項為: (A) place, (B) purpose, (C) concern, (D) permission\n正確解答為: (A) place\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) place\n解析說明：本題屬於「字彙」題型。正確選項為 (A) place。"},
    {"id": "TOEIC_Part5_119_8", "no": "119", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "We have simplified the bill-paying feature on our secure Web site _______ convenience.", "o": ["(A) above all", "(B) with some", "(C) for your", "(D) by its"], "a": "C", "e": "【題目中文翻譯】\n為了您的方便，我們簡化了安全網站上的帳單支付功能。\n\n【答案選項中文說明與詞性】\n選項為: (A) above all, (B) with some, (C) for your, (D) by its\n正確解答為: (C) for your\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) for your\n解析說明：本題屬於「介系詞」題型。正確選項為 (C) for your。"},
    {"id": "TOEIC_Part5_120_8", "no": "120", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The rebate offered by Genton Vitamins will expire _______ six months.", "o": ["(A) among", "(B) within", "(C) except", "(D) besides"], "a": "B", "e": "【題目中文翻譯】\nGenton 維他命提供的折扣將在六個月內到期。\n\n【答案選項中文說明與詞性】\n選項為: (A) among, (B) within, (C) except, (D) besides\n正確解答為: (B) within\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) within\n解析說明：本題屬於「介系詞」題型。正確選項為 (B) within。"},
    {"id": "TOEIC_Part5_121_8", "no": "121", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The results of the test are only as meaningful as the quality of the specimen _______ for analysis.", "o": ["(A) submitted", "(B) submittal", "(C) submits", "(D) submitting"], "a": "A", "e": "【題目中文翻譯】\n測試結果的意義僅取決於提交分析的樣本品質。\n\n【答案選項中文說明與詞性】\n選項為: (A) submitted, (B) submittal, (C) submits, (D) submitting\n正確解答為: (A) submitted\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) submitted\n解析說明：本題屬於「詞性」題型。正確選項為 (A) submitted。"},
    {"id": "TOEIC_Part5_122_8", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Ms. Nguyen is assigned to oversee television advertising campaigns _______.", "o": ["(A) indefinite", "(B) deliberate", "(C) compound", "(D) multiple"], "a": "A", "e": "【題目中文翻譯】\n阮女士被指派無限期負責監督電視廣告活動。\n\n【答案選項中文說明與詞性】\n選項為: (A) indefinite, (B) deliberate, (C) compound, (D) multiple\n正確解答為: (A) indefinite\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) indefinite\n解析說明：本題屬於「字彙」題型。正確選項為 (A) indefinite。"},
    {"id": "TOEIC_Part5_123_8", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Sales from the Plainlee Organics juice line _______ for less than 25 percent of the company's total revenue.", "o": ["(A) account", "(B) accounts", "(C) accounting", "(D) accountant"], "a": "A", "e": "【題目中文翻譯】\nPlainlee 有機果汁系列的銷售額佔公司總收入的比例不到 25%。\n\n【答案選項中文說明與詞性】\n選項為: (A) account, (B) accounts, (C) accounting, (D) accountant\n正確解答為: (A) account\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) account\n解析說明：本題屬於「詞性」題型。正確選項為 (A) account。"},
    {"id": "TOEIC_Part5_124_8", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Since Alfonso Bastian is such a great _______ to the company, he was promoted to division manager.", "o": ["(A) asset", "(B) order", "(C) application", "(D) opportunity"], "a": "A", "e": "【題目中文翻譯】\n由於阿方索·巴斯蒂安是公司的寶貴資產，他被晉升為部門經理。\n\n【答案選項中文說明與詞性】\n選項為: (A) asset, (B) order, (C) application, (D) opportunity\n正確解答為: (A) asset\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) asset\n解析說明：本題屬於「字彙」題型。正確選項為 (A) asset。"},
    {"id": "TOEIC_Part5_125_8", "no": "125", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The city _______ that all buildings pass an inspection does not apply to historic landmarks.", "o": ["(A) require", "(B) requires", "(C) required", "(D) requirement"], "a": "D", "e": "【題目中文翻譯】\n城市規定所有建築物必須通過檢查的硬性要求不適用於歷史地標。\n\n【答案選項中文說明與詞性】\n選項為: (A) require, (B) requires, (C) required, (D) requirement\n正確解答為: (D) requirement\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) requirement\n解析說明：本題屬於「詞性」題型。正確選項為 (D) requirement。"},
    {"id": "TOEIC_Part5_126_8", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "To keep an independent contracting license, Ms. Ato must _______ the correct paperwork annually.", "o": ["(A) file", "(B) conduct", "(C) announce", "(D) transform"], "a": "A", "e": "【題目中文翻譯】\n為了保持獨立承包商許可證，Ato 女士必須每年提交正確的文件。\n\n【答案選項中文說明與詞性】\n選項為: (A) file, (B) conduct, (C) announce, (D) transform\n正確解答為: (A) file\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) file\n解析說明：本題屬於「字彙」題型。正確選項為 (A) file。"},
    {"id": "TOEIC_Part5_127_8", "no": "127", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The price quoted by the movers is only an _______ cost and is subject to change.", "o": ["(A) approximately", "(B) approximate", "(C) approximating", "(D) approximation"], "a": "B", "e": "【題目中文翻譯】\n搬家公司報出的價格只是估算成本，隨時可能發生變化。\n\n【答案選項中文說明與詞性】\n選項為: (A) approximately, (B) approximate, (C) approximating, (D) approximation\n正確解答為: (B) approximate\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) approximate\n解析說明：本題屬於「詞性」題型。正確選項為 (B) approximate。"},
    {"id": "TOEIC_Part5_128_8", "no": "128", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Through the years, Ontario Housewares has _______ its commitment to sell only the highest-quality kitchen appliances.", "o": ["(A) linked", "(B) relieved", "(C) honored", "(D) attracted"], "a": "C", "e": "【題目中文翻譯】\n多年來，安大略家品履行了僅銷售最高品質廚房用具的承諾。\n\n【答案選項中文說明與詞性】\n選項為: (A) linked, (B) relieved, (C) honored, (D) attracted\n正確解答為: (C) honored\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) honored\n解析說明：本題屬於「字彙」題型。正確選項為 (C) honored。"},
    {"id": "TOEIC_Part5_129_8", "no": "129", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Mehretu will discuss the _______ of the new payroll policy at the company meeting tomorrow.", "o": ["(A) specifics", "(B) specifically", "(C) specifies", "(D) specific"], "a": "A", "e": "【題目中文翻譯】\nMehretu 先生將在明天的公司會議上討論新薪資政策的細節。\n\n【答案選項中文說明與詞性】\n選項為: (A) specifics, (B) specifically, (C) specifies, (D) specific\n正確解答為: (A) specifics\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) specifics\n解析說明：本題屬於「詞性」題型。正確選項為 (A) specifics。"},
    {"id": "TOEIC_Part5_130_8", "no": "130", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The contract must be signed _______ the opening of formal discussions.", "o": ["(A) in order to", "(B) prior to", "(C) except for", "(D) on top of"], "a": "B", "e": "【題目中文翻譯】\n合約必須在正式討論開始前簽署。\n\n【答案選項中文說明與詞性】\n選項為: (A) in order to, (B) prior to, (C) except for, (D) on top of\n正確解答為: (B) prior to\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) prior to\n解析說明：本題屬於「介系詞」題型。正確選項為 (B) prior to。"},
    {"id": "TOEIC_Part5_101_9", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Visit our travel section for ------- information about local hotel discounts.", "o": ["(A) helps", "(B) helpfully", "(C) helpful", "(D) helped"], "a": "C", "e": "【題目中文翻譯】\n請造訪我們的旅遊專區，以取得關於當地飯店折扣的有用的資訊。\n\n【答案選項中文說明與詞性】\n(A) helps (動詞單數)：幫助\n(B) helpfully (副詞)：有幫助地\n(C) helpful (形容詞)：有幫助的、有用的\n(D) helped (動詞過去式/分詞)：幫助\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) helpful\n解析說明：空格用於修飾後方的名詞 information，應填入形容詞 helpful。"},
    {"id": "TOEIC_Part5_102_9", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ms. Linde congratulated her team for ------- work on the Glenovas campaign.", "o": ["(A) they", "(B) theirs", "(C) their", "(D) those"], "a": "C", "e": "【題目中文翻譯】\n林德女士祝賀她的團隊在 Glenovas 宣量活動中的優秀工作。\n\n【答案選項中文說明與詞性】\n(A) they (主格代名詞)：他們\n(B) theirs (所有格代名詞)：他們的（東西）\n(C) their (所有格形容詞)：他們的\n(D) those (指示代名詞)：那些\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) their\n解析說明：修飾名詞 work，需填入所有格形容詞 their。"},
    {"id": "TOEIC_Part5_103_9", "no": "103", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Pedro's Printing was started as a family business 32 years -------.", "o": ["(A) last", "(B) ago", "(C) along", "(D) former"], "a": "B", "e": "【題目中文翻譯】\nPedro 印刷廠在 32 年前作為一家家族企業成立。\n\n【答案選項中文說明與詞性】\n(A) last (形容詞)：上一個、最後的\n(B) ago (副詞)：...之前\n(C) along (介系詞)：沿著\n(D) former (形容詞)：前任的、以前的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) ago\n解析說明：「一段時間 + ago」表示「在...時間之前」，符合句意。"},
    {"id": "TOEIC_Part5_104_9", "no": "104", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Applicants for our technical writing position should include a brief writing -------.", "o": ["(A) style", "(B) procedure", "(C) sample", "(D) approach"], "a": "C", "e": "【題目中文翻譯】\n應徵我們技術寫作職位的人員應隨附一份簡短的寫作範例。\n\n【答案選項中文說明與詞性】\n(A) style (名詞)：風格\n(B) procedure (名詞)：程序\n(C) sample (名詞)：樣本、範例\n(D) approach (名詞)：方法\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) sample\n解析說明：writing sample 指「寫作作品範例/樣稿」，符合求職語境。"},
    {"id": "TOEIC_Part5_105_9", "no": "105", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Doctors state that it is important to drink water ------- the day.", "o": ["(A) after", "(B) toward", "(C) around", "(D) throughout"], "a": "D", "e": "【題目中文翻譯】\n醫生指出，一整天隨時補充水分是非常重要的。\n\n【答案選項中文說明與詞性】\n(A) after (介系詞)：在...之後\n(B) toward (介系詞)：朝向\n(C) around (介系詞)：圍繞、大約\n(D) throughout (介系詞)：貫穿、整整（一段時間）\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) throughout\n解析說明：throughout the day 表示「整天期間、一整天貫穿」，符合語意。"},
    {"id": "TOEIC_Part5_106_9", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "For senior-level positions, Trimdeco Limited prefers ------- staff from within rather than externally.", "o": ["(A) to recruit", "(B) to be recruited", "(C) recruit", "(D) recruits"], "a": "A", "e": "【題目中文翻譯】\n對於高階職位，Trimdeco 有限公司傾向於從內部招募員工，而非向外聘用。\n\n【答案選項中文說明與詞性】\n(A) to recruit (不定詞主動形)：招募\n(B) to be recruited (不定詞被動形)：被招募\n(C) recruit (動詞原形)：招募\n(D) recruits (動詞單數)：招募\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) to recruit\n解析說明：prefer 後接不定詞 to recruit 作受詞，後接受詞 staff，使用主動語態。"},
    {"id": "TOEIC_Part5_107_9", "no": "107", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "It is recommended to charge the drill's battery fully ------- using it for the first time.", "o": ["(A) except", "(B) before", "(C) within", "(D) against"], "a": "B", "e": "【題目中文翻譯】\n建議在首次使用電鑽之前，先將電池充滿電。\n\n【答案選項中文說明與詞性】\n(A) except (介系詞)：除了...之外\n(B) before (介系詞/連接詞)：在...之前\n(C) within (介系詞)：在...之內\n(D) against (介系詞)：反對、緊靠著\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) before\n解析說明：before using it ... 表示「在使用它之前」，符合使用習慣。"},
    {"id": "TOEIC_Part5_108_9", "no": "108", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Mr. Takahashi was recognized for his ------- achievement in quality control this past year.", "o": ["(A) outstanding", "(B) interested", "(C) accepting", "(D) ready"], "a": "A", "e": "【題目中文翻譯】\n高橋先生因過去一年在品質管制方面的傑出成就而獲得表揚。\n\n【答案選項中文說明與詞性】\n(A) outstanding (形容詞)：傑出的、卓越的\n(B) interested (形容詞)：感興趣的\n(C) accepting (形容詞/分詞)：接受的\n(D) ready (形容詞)：準備好的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) outstanding\n解析說明：outstanding achievement 表示「傑出成就」，用語道地。"},
    {"id": "TOEIC_Part5_109_9", "no": "109", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Since Jakan Technology ended production of microprocessors, its customers have searched for ------- alternatives.", "o": ["(A) suited", "(B) suitable", "(C) suitably", "(D) suits"], "a": "B", "e": "【題目中文翻譯】\n自從 Jakan 科技停止生產微處理器以來，其客戶一直在尋找合適的替代方案。\n\n【答案選項中文說明與詞性】\n(A) suited (形容詞)：適合的\n(B) suitable (形容詞)：合適的、適當的\n(C) suitably (副詞)：適當地\n(D) suits (動詞單數/名詞複數)：適合\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) suitable\n解析說明：修飾名詞 alternatives，應使用形容詞 suitable。"},
    {"id": "TOEIC_Part5_110_9", "no": "110", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "See page 30 of the manual ------- a comparison of the recommended wood stains.", "o": ["(A) for", "(B) off", "(C) by", "(D) at"], "a": "A", "e": "【題目中文翻譯】\n請參閱手冊第 30 頁，以了解推薦木材著色劑的比較。\n\n【答案選項中文說明與詞性】\n(A) for (介系詞)：為了、關於\n(B) off (介系詞)：離開\n(C) by (介系詞)：經由、由\n(D) at (介系詞)：在...地點/時間\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) for\n解析說明：「See page X for + 名詞」為常見用法，表示參閱某頁以獲取某內容。"},
    {"id": "TOEIC_Part5_111_9", "no": "111", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Diners seeking a quick and ------- lunch should find Kimchi Quick a delicious option.", "o": ["(A) economist", "(B) economical", "(C) economics", "(D) economize"], "a": "B", "e": "【題目中文翻譯】\n尋求快速且經濟實惠午餐的饕客，會發現 Kimchi Quick 是一個美味的選擇。\n\n【答案選項中文說明與詞性】\n(A) economist (名詞)：經濟學者\n(B) economical (形容詞)：經濟實惠的、節省的\n(C) economics (名詞)：經濟學\n(D) economize (動詞)：節省\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) economical\n解析說明：and 連接兩個同等形容詞修飾 lunch (quick and economical)。"},
    {"id": "TOEIC_Part5_112_9", "no": "112", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The editors of Computer Roundup ------- recognized Fallway Computers for having the best customer service in the area.", "o": ["(A) lightly", "(B) closely", "(C) recently", "(D) moderately"], "a": "C", "e": "【題目中文翻譯】\n《Computer Roundup》的編輯們近期表揚了 Fallway 電腦公司擁有該地區最佳的客戶服務。\n\n【答案選項中文說明與詞性】\n(A) lightly (副詞)：輕微地\n(B) closely (副詞)：緊密地\n(C) recently (副詞)：最近、近期\n(D) moderately (副詞)：適度地\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) recently\n解析說明：recently + 過去式動詞 recognized，表示最近發生的動作。"},
    {"id": "TOEIC_Part5_113_9", "no": "113", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "When the customer complained about the cold soup, the server ------- and offered to bring a new bowl.", "o": ["(A) behaved", "(B) asserted", "(C) apologized", "(D) excused"], "a": "C", "e": "【題目中文翻譯】\n當顧客抱怨湯是冷的時候，服務生道歉並主動表示要端上一碗新的湯。\n\n【答案選項中文說明與詞性】\n(A) behaved (動詞)：表現\n(B) asserted (動詞)：斷言、主張\n(C) apologized (動詞)：道歉\n(D) excused (動詞)：原諒、免除\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) apologized\n解析說明：語意為服務生致歉並提供新品替換，選擇 apologized。"},
    {"id": "TOEIC_Part5_114_9", "no": "114", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "------- the month of September, all online donations will be matched by an anonymous donor.", "o": ["(A) When", "(B) During", "(C) While", "(D) Once"], "a": "B", "e": "【題目中文翻譯】\n在整個九月期間，所有網路捐款都將由一位匿名捐款者提供等額對等捐款。\n\n【答案選項中文說明與詞性】\n(A) When (連接詞)：當...時\n(B) During (介系詞)：在...期間\n(C) While (連接詞)：當...時、然而\n(D) Once (連接詞/副詞)：一旦\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) During\n解析說明：後接名詞片語 the month of September，需使用介系詞 During。"},
    {"id": "TOEIC_Part5_115_9", "no": "115", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Martin Slyeptsov is an ------- guitarist, having won several national awards for his many albums.", "o": ["(A) accomplished", "(B) efficient", "(C) unqualified", "(D) arranged"], "a": "A", "e": "【題目中文翻譯】\nMartin Slyeptsov 是一位造詣深厚的吉他手，憑藉眾多專輯獲得了數項國家級獎項。\n\n【答案選項中文說明與詞性】\n(A) accomplished (形容詞)：才華洋溢的、造詣深厚的\n(B) efficient (形容詞)：有效率的\n(C) unqualified (形容詞)：不合資格的\n(D) arranged (形容詞/分詞)：安排好的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) accomplished\n解析說明：accomplished 常用於形容音樂家或藝術家「造詣深厚的/有成就的」。"},
    {"id": "TOEIC_Part5_116_9", "no": "116", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Many internal staff have expressed interest in the position, but ------- have the required experience.", "o": ["(A) any", "(B) few", "(C) each", "(D) many"], "a": "B", "e": "【題目中文翻譯】\n許多內部員工對該職位表達了興趣，但極少數人具備所需的經驗。\n\n【答案選項中文說明與詞性】\n(A) any (代名詞)：任何\n(B) few (代名詞)：很少數人/物（表示否定轉折）\n(C) each (代名詞)：每一個\n(D) many (代名詞)：許多\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) few\n解析說明：but 轉折前後對比「雖然很多人感興趣，但極少數人有經驗」，few + 複數動詞 have。"},
    {"id": "TOEIC_Part5_117_9", "no": "117", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "------- many of the attendees were late because of traffic, the president's presentation began on time.", "o": ["(A) As soon as", "(B) So that", "(C) Rather than", "(D) Although"], "a": "D", "e": "【題目中文翻譯】\n雖然許多與會者因交通堵塞而遲到，總裁的簡報仍準時開始。\n\n【答案選項中文說明與詞性】\n(A) As soon as (連接詞)：一...就\n(B) So that (連接詞)：以便\n(C) Rather than (介系詞/連接詞)：而不是\n(D) Although (連接詞)：雖然、儘管\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) Although\n解析說明：引導表示讓步轉折的副詞子句，選擇 Although。"},
    {"id": "TOEIC_Part5_118_8", "no": "118", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Over the next three years, Lang Biotech ------- to acquire an additional manufacturing site.", "o": ["(A) to plan", "(B) planning", "(C) having planned", "(D) plans"], "a": "D", "e": "【題目中文翻譯】\n在未來三年內，Lang 生技計劃收購額外的製造基地。\n\n【答案選項中文說明與詞性】\n(A) to plan (不定詞)\n(B) planning (現在分詞)\n(C) having planned (完成分詞)\n(D) plans (動詞單數現在式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) plans\n解析說明：主詞為 Lang Biotech，句子需要主要動詞，選擇單數動詞 plans。"},
    {"id": "TOEIC_Part5_119_9", "no": "119", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "To be considered for the position, applicants must submit a résumé ------- a list of references.", "o": ["(A) even if", "(B) along with", "(C) whereas", "(D) consequently"], "a": "B", "e": "【題目中文翻譯】\n為獲得該職位考量，應徵者必須提交履歷以及推薦人清單。\n\n【答案選項中文說明與詞性】\n(A) even if (連接詞)：即使\n(B) along with (介系詞片語)：連同、以及\n(C) whereas (連接詞)：然而\n(D) consequently (副詞)：因此\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) along with\n解析說明：along with 後接名詞 list of references，表示「連同...一起」。"},
    {"id": "TOEIC_Part5_120_9", "no": "120", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Reza Realty will provide a full ------- of the commercial properties for sale in Delta City.", "o": ["(A) analyzed", "(B) analytics", "(C) analysis", "(D) analyst"], "a": "C", "e": "【題目中文翻譯】\nReza 不動產將提供 Delta 市待售商業地產的完整分析報告。\n\n【答案選項中文說明與詞性】\n(A) analyzed (動詞過去式)\n(B) analytics (名詞)：分析學/數據\n(C) analysis (名詞)：分析/分析報告\n(D) analyst (名詞)：分析師\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) analysis\n解析說明：a full analysis 表示「一份完整的分析報告」，符合商業語境。"},
    {"id": "TOEIC_Part5_121_9", "no": "121", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The main speaker, Ms. Kelli Sun, ------- to conclude her speech at 8:00 P.M. tonight.", "o": ["(A) expect", "(B) expecting", "(C) to expect", "(D) is expected"], "a": "D", "e": "【題目中文翻譯】\n主講人 Kelli Sun 女士預計將於今晚 8 點結束她的演講。\n\n【答案選項中文說明與詞性】\n(A) expect (動詞原形)\n(B) expecting (分詞)\n(C) to expect (不定詞)\n(D) is expected (被動動詞形)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) is expected\n解析說明：be expected to ... 為固定被動結構，表示「被預期/預計將...」。"},
    {"id": "TOEIC_Part5_122_9", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "There has been a significant ------- in traffic in the center of town since the opening of the David Bridge.", "o": ["(A) reduction", "(B) admission", "(C) election", "(D) placement"], "a": "A", "e": "【題目中文翻譯】\n自大衛大橋通車以來，市中心的交通量顯著減少。\n\n【答案選項中文說明與詞性】\n(A) reduction (名詞)：減少、降低\n(B) admission (名詞)：入學/入場許可\n(C) election (名詞)：選舉\n(D) placement (名詞)：放置/安置\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) reduction\n解析說明：a significant reduction in traffic 指「交通量顯著減少」。"},
    {"id": "TOEIC_Part5_123_9", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Routine maintenance of equipment ------- improves workplace safety and efficiency.", "o": ["(A) measure", "(B) measurement", "(C) measurable", "(D) measurably"], "a": "D", "e": "【題目中文翻譯】\n設備的例行維護能顯著且可測量地提升工作場所的安全與效率。\n\n【答案選項中文說明與詞性】\n(A) measure (動詞/名詞)\n(B) measurement (名詞)\n(C) measurable (形容詞)\n(D) measurably (副詞)：可顯著地/可測量地\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) measurably\n解析說明：修飾動詞 improves，應使用副詞 measurably。"},
    {"id": "TOEIC_Part5_124_9", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "When we get ------- from the Stades Group, we will inform the management team about the schedule change.", "o": ["(A) allowance", "(B) construction", "(C) confirmation", "(D) substance"], "a": "C", "e": "【題目中文翻譯】\n當我們收到 Stades 集團的確認時，我們會通知管理團隊關於時程的變更。\n\n【答案選項中文說明與詞性】\n(A) allowance (名詞)：津貼/允許\n(B) construction (名詞)：建造\n(C) confirmation (名詞)：確認\n(D) substance (名詞)：物質/實質\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) confirmation\n解析說明：get confirmation 表示「獲得確認」，符合句意。"},
    {"id": "TOEIC_Part5_125_9", "no": "125", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ms. Singh remembers her days as a sales assistant at Tyron Labs very -------.", "o": ["(A) fonder", "(B) fond", "(C) fondly", "(D) fondness"], "a": "C", "e": "【題目中文翻譯】\nSingh 女士非常深情地懷念她在 Tyron 實驗室擔任銷售助理的日子。\n\n【答案選項中文說明與詞性】\n(A) fonder (比較級)\n(B) fond (形容詞)：喜愛的\n(C) fondly (副詞)：深情地、懷念地\n(D) fondness (名詞)：喜愛\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) fondly\n解析說明：修飾動詞 remembers，需填入副詞 fondly。"},
    {"id": "TOEIC_Part5_126_9", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "A potential merger with Porter-Renwick Enterprises is currently being ------- by the board of directors.", "o": ["(A) considered", "(B) supposed", "(C) reflected", "(D) assumed"], "a": "A", "e": "【題目中文翻譯】\n與 Porter-Renwick 企業潛在的合併案目前正在由董事會審議中。\n\n【答案選項中文說明與詞性】\n(A) considered (動詞分詞)：考慮、審議\n(B) supposed (動詞分詞)：假設/認為\n(C) reflected (動詞分詞)：反映\n(D) assumed (動詞分詞)：假設/承擔\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) considered\n解析說明：being considered by ... 表示「正由...考慮研議中」。"},
    {"id": "TOEIC_Part5_127_9", "no": "127", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Tengku Data Security ensures a company's ------- with all established regulations.", "o": ["(A) compliance", "(B) compliantly", "(C) complies", "(D) comply"], "a": "A", "e": "【題目中文翻譯】\nTengku 數據安全公司確保企業符合所有既定的法規。\n\n【答案選項中文說明與詞性】\n(A) compliance (名詞)：遵從、符合\n(B) compliantly (副詞)：順從地\n(C) complies (動詞單數)\n(D) comply (動詞原形)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) compliance\n解析說明：ensure a company's compliance with ... 為固定搭配列「確保符合...」。"},
    {"id": "TOEIC_Part5_128_9", "no": "128", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The respondents to the passenger satisfaction survey are ------- of the total passenger population.", "o": ["(A) creative", "(B) current", "(C) intermediate", "(D) representative"], "a": "D", "e": "【題目中文翻譯】\n乘客滿意度調查的受訪者具有全體乘客總體的代表性。\n\n【答案選項中文說明與詞性】\n(A) creative (形容詞)：有創意的\n(B) current (形容詞)：目前的\n(C) intermediate (形容詞)：中級的\n(D) representative (形容詞)：具代表性的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) representative\n解析說明：be representative of ... 表示「具備...的代表性」。"},
    {"id": "TOEIC_Part5_129_9", "no": "129", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "------- the plastic packaging arrives today, we cannot make the delivery on time.", "o": ["(A) Mostly", "(B) At least", "(C) No more", "(D) Unless"], "a": "D", "e": "【題目中文翻譯】\n除非塑膠包裝今天送達，否則我們無法按時送貨。\n\n【答案選項中文說明與詞性】\n(A) Mostly (副詞)：主要地\n(B) At least (副詞片語)：至少\n(C) No more (副詞片語)：不再\n(D) Unless (連接詞)：除非\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) Unless\n解析說明：Unless 引導條件副詞子句，表示「除非...否則...」。"},
    {"id": "TOEIC_Part5_130_9", "no": "130", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Heper Industry employees are ------- for expenses when using their personal cars for business purposes.", "o": ["(A) reimbursed", "(B) restored", "(C) recovered", "(D) reassigned"], "a": "A", "e": "【題目中文翻譯】\nHeper 工業的員工因公使用私人車輛時可獲得費用核銷補助。\n\n【答案選項中文說明與詞性】\n(A) reimbursed (動詞分詞)：報銷、補償費用\n(B) restored (動詞分詞)：修復\n(C) recovered (動詞分詞)：恢復\n(D) reassigned (動詞分詞)：重新指派\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) reimbursed\n解析說明：be reimbursed for expenses 表示「費用獲得報銷補助」。"},
    {"id": "TOEIC_Part5_101_10", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The number of flights to the South Pacific offered by Eastal Air is -------.", "o": ["(A) growing", "(B) grown", "(C) growth", "(D) grow"], "a": "A", "e": "【題目中文翻譯】\n東亞航空提供的南太平洋航班數量正在增加。\n\n【答案選項中文說明與詞性】\n(A) growing (現在分詞/進行式)：正在增加\n(B) grown (過去分詞)：已成長\n(C) growth (名詞)：成長\n(D) grow (動詞原形)：成長\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) growing\n解析說明：is + V-ing 構成現在進行式，表示航班數量持續增長中。"},
    {"id": "TOEIC_Part5_102_10", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Wilsen University has a ------- ranked medical school with state-of-the-art facilities.", "o": ["(A) lightly", "(B) rapidly", "(C) highly", "(D) shortly"], "a": "C", "e": "【題目中文翻譯】\n威爾森大學擁有排名極高的醫學院，並配備最先進的設施。\n\n【答案選項中文說明與詞性】\n(A) lightly (副詞)：輕微地\n(B) rapidly (副詞)：快速地\n(C) highly (副詞)：高度地、極為\n(D) shortly (副詞)：不久、即刻\n\n【文法觀點與解析】\n考點類型：字彙/副詞\n正確答案：(C) highly\n解析說明：「highly ranked」為固定搭配，表示「獲得高度評價的/排名極高的」。"},
    {"id": "TOEIC_Part5_103_10", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Rather than asking an assistant for help, Ms. Pham responded to the director's request -------.", "o": ["(A) her", "(B) herself", "(C) hers", "(D) her own"], "a": "B", "e": "【題目中文翻譯】\n范女士沒有向助理求助，而是親自回覆了主管的要求。\n\n【答案選項中文說明與詞性】\n(A) her (受格/所有格)：她/她的\n(B) herself (反身代名詞)：她自己、親自\n(C) hers (所有格代名詞)：她的東西\n(D) her own (片語)：她自己的\n\n【文法觀點與解析】\n考點類型：詞性/代名詞\n正確答案：(B) herself\n解析說明：反身代名詞在此作為同位語加強語氣，表示「親自」。"},
    {"id": "TOEIC_Part5_104_10", "no": "104", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Camilla Lowenson ------- all marketing accounts for Akembe Fashion's Paris office.", "o": ["(A) handles", "(B) trains", "(C) reflects", "(D) concerns"], "a": "A", "e": "【題目中文翻譯】\n卡蜜拉·羅溫森負責處理阿坎貝時尚巴黎辦事處的所有行銷帳戶。\n\n【答案選項中文說明與詞性】\n(A) handles (動詞)：處理、負責\n(B) trains (動詞)：訓練\n(C) reflects (動詞)：反映\n(D) concerns (動詞)：關心、涉及\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) handles\n解析說明：根據句意「負責處理所有行銷帳戶」，應選擇動詞 handles。"},
    {"id": "TOEIC_Part5_105_10", "no": "105", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Risley credited his team for the ------- of the popular software program.", "o": ["(A) develop", "(B) developer", "(C) developed", "(D) development"], "a": "D", "e": "【題目中文翻譯】\n雷斯利先生將這套受歡迎軟體程式的開發歸功於他的團隊。\n\n【答案選項中文說明與詞性】\n(A) develop (動詞)：開發\n(B) developer (名詞/人)：開發者\n(C) developed (過去分詞/形容詞)：已開發的\n(D) development (名詞/事)：開發、研發\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) development\n解析說明：介系詞 for 與冠詞 the 之後應接名詞 development。"},
    {"id": "TOEIC_Part5_106_10", "no": "106", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The ------- candidate is someone with strong communication skills.", "o": ["(A) ideal", "(B) deep", "(C) constant", "(D) intensive"], "a": "A", "e": "【題目中文翻譯】\n理想的求職者是具備強大溝通技巧的人。\n\n【答案選項中文說明與詞性】\n(A) ideal (形容詞)：理想的\n(B) deep (形容詞)：深的\n(C) constant (形容詞)：持續的\n(D) intensive (形容詞)：密集的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) ideal\n解析說明：修飾 candidate（候選人/求職者），符合句意「理想的人選」。"},
    {"id": "TOEIC_Part5_107_10", "no": "107", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Thorsten Electronics' sales figures have risen ------- every month this year.", "o": ["(A) progress", "(B) progressive", "(C) progressing", "(D) progressively"], "a": "D", "e": "【題目中文翻譯】\n托爾斯騰電子的銷售數字今年每個月都在持續穩定成長。\n\n【答案選項中文說明與詞性】\n(A) progress (名詞/動詞)：進步\n(B) progressive (形容詞)：漸進的\n(C) progressing (動名詞/分詞)：正在進展\n(D) progressively (副詞)：漸進地、持續地\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) progressively\n解析說明：修飾不及物動詞 have risen，應填入副詞 progressively。"},
    {"id": "TOEIC_Part5_108_10", "no": "108", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "While Dr. Merino is away ------- vacation, her patients will be seen by Dr. Wolf.", "o": ["(A) in", "(B) of", "(C) on", "(D) from"], "a": "C", "e": "【題目中文翻譯】\n當梅里諾醫生休假期間，她的病人將由沃爾夫醫生代診。\n\n【答案選項中文說明與詞性】\n(A) in (介系詞)：在...裡面\n(B) of (介系詞)：...的\n(C) on (介系詞)：在...\n(D) from (介系詞)：來自\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(C) on\n解析說明：「on vacation」為固定度假/休假介系詞搭配。"},
    {"id": "TOEIC_Part5_109_10", "no": "109", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The J & S Foundation is honoring three individuals ------- have implemented successful community programs.", "o": ["(A) whichever", "(B) whose", "(C) whoever", "(D) who"], "a": "D", "e": "【題目中文翻譯】\nJ & S 基金會正在表彰三位實施成功社區計畫的個人。\n\n【答案選項中文說明與詞性】\n(A) whichever (關係代名詞)：無論哪個\n(B) whose (所有格關係代名詞)：誰的\n(C) whoever (複合關係代名詞)：無論是誰\n(D) who (主格關係代名詞)：...的人\n\n【文法觀點與解析】\n考點類型：連結詞/關係代名詞\n正確答案：(D) who\n解析說明：先行詞為 three individuals（人），後方接動詞 have，需填入主格關係代名詞 who。"},
    {"id": "TOEIC_Part5_110_10", "no": "110", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Katib Boulos has over 30 years of experience in event planning and is particularly skilled at ------- banquets.", "o": ["(A) considering", "(B) managing", "(C) treating", "(D) answering"], "a": "B", "e": "【題目中文翻譯】\n卡蒂布·布洛斯在活動策劃方面擁有超過 30 年的經驗，尤其擅長管理宴會。\n\n【答案選項中文說明與詞性】\n(A) considering (動詞/動名詞)：考慮\n(B) managing (動詞/動名詞)：管理、經營\n(C) treating (動詞/動名詞)：對待、治療\n(D) answering (動詞/動名詞)：回答\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) managing\n解析說明：搭配 banquets（宴會），符合句意「管理/籌辦宴會」。"},
    {"id": "TOEIC_Part5_111_10", "no": "111", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Pinckney tools are ------- well made that they are guaranteed to last for decades.", "o": ["(A) so", "(B) such", "(C) as", "(D) just"], "a": "A", "e": "【題目中文翻譯】\nPinckney 工具製作得非常精良，保證可以使用數十年。\n\n【答案選項中文說明與詞性】\n(A) so (副詞)：如此\n(B) such (限定詞)：如此的\n(C) as (副詞/介系詞)：如同\n(D) just (副詞)：僅僅\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) so\n解析說明：「so + 形容詞/副詞 + that ...」句型表示「如此...以至於...」。修飾副詞 well 應使用 so。"},
    {"id": "TOEIC_Part5_112_10", "no": "112", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "If you should decide to discontinue your mobile-phone plan with PQ Wireless, please ------- us in writing.", "o": ["(A) declare", "(B) notify", "(C) qualify", "(D) state"], "a": "B", "e": "【題目中文翻譯】\n如果您決定終止與 PQ 無線的電信方案，請以書面形式通知我們。\n\n【答案選項中文說明與詞性】\n(A) declare (動詞)：宣佈\n(B) notify (動詞)：通知\n(C) qualify (動詞)：使具資格\n(D) state (動詞)：陳述\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) notify\n解析說明：notify sb in writing 為常用商業語彙，意為「以書面通知某人」。"},
    {"id": "TOEIC_Part5_113_10", "no": "113", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The survey shows that most customers find Lundy Sweets' packaging -------.", "o": ["(A) appealed", "(B) appealing", "(C) appeal", "(D) appealingly"], "a": "B", "e": "【題目中文翻譯】\n調查顯示，大多數顧客認為 Lundy 糖果的包裝很有吸引力。\n\n【答案選項中文說明與詞性】\n(A) appealed (分詞)\n(B) appealing (形容詞)：有吸引力的\n(C) appeal (動詞/名詞)\n(D) appealingly (副詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) appealing\n解析說明：find + 受詞 + 受詞補語（形容詞），修飾物用 -ing 形容詞 appealing。"},
    {"id": "TOEIC_Part5_114_10", "no": "114", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Today Mr. Lo verbally agreed to rent the property, ------- he will not sign the lease until next week.", "o": ["(A) despite", "(B) or", "(C) but", "(D) either"], "a": "C", "e": "【題目中文翻譯】\n羅先生今天口頭同意承租該房產，但他要到下週才會簽署租約。\n\n【答案選項中文說明與詞性】\n(A) despite (介系詞)：儘管\n(B) or (對等連接詞)：或者\n(C) but (對等連接詞)：但是\n(D) either (代名詞/副詞)：兩者之一\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) but\n解析說明：連接兩個語意相反的獨立子句（口頭同意 vs 還沒簽約），選擇對等連接詞 but。"},
    {"id": "TOEIC_Part5_115_10", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The new bus line is scheduled to travel ------- to the coast, bypassing several villages along its route.", "o": ["(A) directions", "(B) director", "(C) directing", "(D) directly"], "a": "D", "e": "【題目中文翻譯】\n新公車路線計畫直達海岸，沿途將繞過數個村莊。\n\n【答案選項中文說明與詞性】\n(A) directions (名詞複數)：方向/說明\n(B) director (名詞)：主管/導演\n(C) directing (分詞)\n(D) directly (副詞)：直接地、直達地\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) directly\n解析說明：修飾動詞 travel，應填入副詞 directly。"},
    {"id": "TOEIC_Part5_116_10", "no": "116", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Please fill out the customer satisfaction survey and leave it at the reception desk at any time ------- your stay.", "o": ["(A) during", "(B) onto", "(C) against", "(D) about"], "a": "A", "e": "【題目中文翻譯】\n請填寫顧客滿意度調查表，並在您住宿期間的任何時間交至櫃檯。\n\n【答案選項中文說明與詞性】\n(A) during (介系詞)：在...期間\n(B) onto (介系詞)：到...之上\n(C) against (介系詞)：緊靠/反對\n(D) about (介系詞)：關於\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) during\n解析說明：後接名詞 your stay (您的住宿期間)，應選擇介系詞 during。"},
    {"id": "TOEIC_Part5_117_10", "no": "117", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "When Gollnick Architects presents the two housing construction plans, community members will be invited to express their -------.", "o": ["(A) prefers", "(B) preferring", "(C) preferential", "(D) preferences"], "a": "D", "e": "【題目中文翻譯】\n當 Gollnick 建築師事務所提出兩項住宅興建計畫時，將邀請社區居民表達他們的偏好與意願。\n\n【答案選項中文說明與詞性】\n(A) prefers (動詞單數)\n(B) preferring (現在分詞)\n(C) preferential (形容詞)：優先的\n(D) preferences (名詞複數)：偏好、選擇\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) preferences\n解析說明：所有格形容詞 their 後接名詞，選擇 preferences。"},
    {"id": "TOEIC_Part5_118_9", "no": "118", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Barett Printing produces high-quality posters with colors that stand -------.", "o": ["(A) for", "(B) by", "(C) up", "(D) out"], "a": "D", "e": "【題目中文翻譯】\nBarett 印刷公司生產色彩極為突出的高品質海報。\n\n【答案選項中文說明與詞性】\n(A) for (介系詞)\n(B) by (介系詞)\n(C) up (副詞/介系詞)\n(D) out (副詞/介系詞)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) out\n解析說明：stand out 為固定動詞片語，表示「突出、顯眼」。"},
    {"id": "TOEIC_Part5_119_10", "no": "119", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Many of the dishes at Conrad's Bistro tend ------- of varying quality.", "o": ["(A) are", "(B) to be", "(C) are being", "(D) having been"], "a": "B", "e": "【題目中文翻譯】\nConrad 小館的許多菜餚品質往往參差不齊。\n\n【答案選項中文說明與詞性】\n(A) are (現在式動詞)\n(B) to be (不定詞)\n(C) are being (進行式)\n(D) having been (完成式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) to be\n解析說明：tend 後接不定詞 to be (tend to be ... 傾向於/往往是)。"},
    {"id": "TOEIC_Part5_120_10", "no": "120", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The metal used by XRRM Co. to manufacture beverage cans weighs ------- less than it did a few years ago.", "o": ["(A) tightly", "(B) enough", "(C) substantially", "(D) only"], "a": "C", "e": "【題目中文翻譯】\nXRRM 公司用於製造飲料罐的金屬重量比幾年前大幅減輕。\n\n【答案選項中文說明與詞性】\n(A) tightly (副詞)：緊密地\n(B) enough (副詞)：足夠地\n(C) substantially (副詞)：相當地、大幅度地\n(D) only (副詞)：僅僅\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) substantially\n解析說明：substantially less 表示「大幅度地減少/減輕」。"},
    {"id": "TOEIC_Part5_121_10", "no": "121", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Due to a decline in viewership, it is ------- whether the Jim Fuji Show will return next season.", "o": ["(A) doubt", "(B) doubtful", "(C) doubtfully", "(D) doubting"], "a": "B", "e": "【題目中文翻譯】\n由於收視率下降，《Jim Fuji 秀》下一季是否回歸令人存疑。\n\n【答案選項中文說明與詞性】\n(A) doubt (名詞/動詞)\n(B) doubtful (形容詞)：令人存疑的\n(C) doubtfully (副詞)\n(D) doubting (分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) doubtful\n解析說明：It is doubtful whether ... 為固定句型，意為「...是否令人存疑」。"},
    {"id": "TOEIC_Part5_122_10", "no": "122", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The publisher had to print a revised edition of the cookbook ------- the author found mistakes in several recipes.", "o": ["(A) which", "(B) besides", "(C) after", "(D) until"], "a": "C", "e": "【題目中文翻譯】\n在作者發現數個食譜中的錯誤之後，出版商不得不印製食譜的修訂版。\n\n【答案選項中文說明與詞性】\n(A) which (關係代名詞)\n(B) besides (介系詞/副詞)：此外\n(C) after (從屬連接詞)：在...之後\n(D) until (從屬連接詞)：直到\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) after\n解析說明：引導時間副詞子句，表示「在發現錯誤之後」，選擇 after。"},
    {"id": "TOEIC_Part5_123_10", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "At DiFazio Entertainment, executives must be consulted before any ------- decisions are made.", "o": ["(A) consequence", "(B) consequently", "(C) consequential", "(D) consequences"], "a": "C", "e": "【題目中文翻譯】\n在 DiFazio 娛樂公司，做出任何重大決定之前必須諮詢高階主管。\n\n【答案選項中文說明與詞性】\n(A) consequence (名詞)：結果\n(B) consequently (副詞)：因此\n(C) consequential (形容詞)：重大的、有重要結果的\n(D) consequences (名詞複數)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) consequential\n解析說明：修飾名詞 decisions，應使用形容詞 consequential。"},
    {"id": "TOEIC_Part5_124_10", "no": "124", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Having the air-conditioning unit fixed by tomorrow is not ------- necessary, since the fan can keep the office cool enough.", "o": ["(A) absolutely", "(B) already", "(C) eventually", "(D) closely"], "a": "A", "e": "【題目中文翻譯】\n明天前修好空調設備並非絕對必要，因為電風扇就能讓辦公室保持足夠涼爽。\n\n【答案選項中文說明與詞性】\n(A) absolutely (副詞)：絕對地、完全地\n(B) already (副詞)：已經\n(C) eventually (副詞)：最終\n(D) closely (副詞)：緊密地\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) absolutely\n解析說明：not absolutely necessary 表示「並非絕對必要」。"},
    {"id": "TOEIC_Part5_125_10", "no": "125", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The new Wyatt Medical Center was designed with environmental ------- in mind.", "o": ["(A) sustainability", "(B) sustainable", "(C) sustaining", "(D) sustain"], "a": "A", "e": "【題目中文翻譯】\n全新的 Wyatt 醫療中心在設計時考量了環境永續性。\n\n【答案選項中文說明與詞性】\n(A) sustainability (名詞)：永續性\n(B) sustainable (形容詞)：可持續的\n(C) sustaining (分詞)\n(D) sustain (動詞)：維持\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) sustainability\n解析說明：environmental sustainability 表示「環境永續性」，為複合名詞結構。"},
    {"id": "TOEIC_Part5_126_10", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The house looks like a ------- residence on the outside, yet inside there are many unusual features.", "o": ["(A) dominant", "(B) typical", "(C) relevant", "(D) potential"], "a": "B", "e": "【題目中文翻譯】\n這棟房子外觀看起來像一般的典型住宅，但內部卻有許多不尋常的特色。\n\n【答案選項中文說明與詞性】\n(A) dominant (形容詞)：主導的\n(B) typical (形容詞)：典型的、一般的\n(C) relevant (形容詞)：相關的\n(D) potential (形容詞)：潛在的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) typical\n解析說明：a typical residence 表示「典型/一般的住宅」，與後方的 unusual 形成強烈對比。"},
    {"id": "TOEIC_Part5_127_10", "no": "127", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ms. Theroux has asked that last month's expenses be ------- in more detail on the budget report.", "o": ["(A) clarify", "(B) clarifies", "(C) clarified", "(D) clarification"], "a": "C", "e": "【題目中文翻譯】\nTheroux 女士要求在上個月的預算報告中將各項支出澄清解釋得更詳細。\n\n【答案選項中文說明與詞性】\n(A) clarify (動詞原形)\n(B) clarifies (動詞單數)\n(C) clarified (被動分詞)\n(D) clarification (名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) clarified\n解析說明：ask that + 主詞 + (should) be + V-ed，被動語態填入過去分詞 clarified。"},
    {"id": "TOEIC_Part5_128_10", "no": "128", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The writing conference in Austin has received a lot of ------- for its lineup of acclaimed authors.", "o": ["(A) publicity", "(B) campaign", "(C) association", "(D) authorization"], "a": "A", "e": "【題目中文翻譯】\n在奧斯汀舉行的寫作研討會因其備受讚譽的作者陣容獲得了大眾廣泛關注與宣傳關注。\n\n【答案選項中文說明與詞性】\n(A) publicity (名詞)：宣傳、大眾關注\n(B) campaign (名詞)：活動\n(C) association (名詞)：協會/關聯\n(D) authorization (名詞)：授權\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) publicity\n解析說明：receive a lot of publicity 表示「獲得大量媒體報導/大眾關注」。"},
    {"id": "TOEIC_Part5_129_10", "no": "129", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Skillman Manufacturing has been specializing in ------- plastic parts since 1987.", "o": ["(A) fabrication", "(B) fabricating", "(C) fabricates", "(D) fabricate"], "a": "B", "e": "【題目中文翻譯】\nSkillman 製造公司自 1987 年以來一直專門從事塑膠零件的製造。\n\n【答案選項中文說明與詞性】\n(A) fabrication (名詞)：製造/製造品\n(B) fabricating (動名詞/分詞)\n(C) fabricates (動詞單數)\n(D) fabricate (動詞原形)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) fabricating\n解析說明：specialize in + V-ing，介系詞 in 後接動名詞 fabricating 及受詞 plastic parts。"},
    {"id": "TOEIC_Part5_130_10", "no": "130", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The hiring committee may recommend candidates for positions ------- they have only limited professional experience.", "o": ["(A) even if", "(B) except for", "(C) along with", "(D) in spite of"], "a": "A", "e": "【題目中文翻譯】\n招聘委員會可能會推薦候選人任職，即使他們僅具備有限的專業經驗。\n\n【答案選項中文說明與詞性】\n(A) even if (從屬連接詞)：即使\n(B) except for (介系詞)：除了...之外\n(C) along with (介系詞)：連同\n(D) in spite of (介系詞)：儘管\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(A) even if\n解析說明：後方接完整子句 they have only limited ...，應選擇從屬連接詞 even if。"},
    {"id": "TOEIC_Part5_101_11", "no": "101", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Ms. Iwata handed out copies of the agenda that ------- had printed for the meeting.", "o": ["(A) hers", "(B) her", "(C) she", "(D) herself"], "a": "C", "e": "【題目中文翻譯】\n岩田女士發放了她為會議列印的議程副本。\n\n【答案選項中文說明與詞性】\n(A) hers (所有格代名詞)\n(B) her (所有格/受格代名詞)\n(C) she (主格代名詞)\n(D) herself (反身代名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) she\n解析說明：that 引導的關係子句中缺少主詞，應填入主格代名詞 she。"},
    {"id": "TOEIC_Part5_102_11", "no": "102", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The food ------- for the conference must be sent to the caterer by Friday at 5:00 P.M.", "o": ["(A) order", "(B) group", "(C) profit", "(D) lesson"], "a": "A", "e": "【題目中文翻譯】\n會議的餐點訂單必須在週五下午 5:00 前發送給餐飲外辦商。\n\n【答案選項中文說明與詞性】\n(A) order (名詞)：訂單\n(B) group (名詞)：團體\n(C) profit (名詞)：利潤\n(D) lesson (名詞)：課程\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) order\n解析說明：food order 指「餐點訂單」，符合語意。"},
    {"id": "TOEIC_Part5_103_11", "no": "103", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The product review says that the Cozy Days space heater is ------- to warm up than similar products.", "o": ["(A) slowest", "(B) slower", "(C) slowed", "(D) slowing"], "a": "B", "e": "【題目中文翻譯】\n產品評論指出，Cozy Days 電暖器比同類產品加熱速度更慢。\n\n【答案選項中文說明與詞性】\n(A) slowest (最高級)\n(B) slower (比較級)\n(C) slowed (過去式/分詞)\n(D) slowing (現在分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) slower\n解析說明：句中有比較詞 than，形容詞應使用比較級 slower。"},
    {"id": "TOEIC_Part5_104_11", "no": "104", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Employees from San Jose International will arrive in Alajuela tomorrow for ------- first training session.", "o": ["(A) they", "(B) their", "(C) them", "(D) theirs"], "a": "B", "e": "【題目中文翻譯】\n來自聖荷西國際公司的員工將於明天抵達阿拉胡埃拉，參加他們的第一場培訓課程。\n\n【答案選項中文說明與詞性】\n(A) they (主格代名詞)\n(B) their (所有格形容詞)\n(C) them (受格代名詞)\n(D) theirs (所有格代名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) their\n解析說明：修飾後方名詞片語 first training session，填入所有格形容詞 their。"},
    {"id": "TOEIC_Part5_105_11", "no": "105", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "To apply for a driving permit, you must ------- two forms of identification.", "o": ["(A) meet", "(B) work", "(C) show", "(D) ride"], "a": "C", "e": "【題目中文翻譯】\n要申請學習駕照，您必須出示兩種身分證明文件。\n\n【答案選項中文說明與詞性】\n(A) meet (動詞)：遇見/符合\n(B) work (動詞)：工作\n(C) show (動詞)：出示/展示\n(D) ride (動詞)：騎乘\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) show\n解析說明：show forms of identification 為常用表達，意為「出示身分證明」。"},
    {"id": "TOEIC_Part5_106_11", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Sales of Seviana Cosmetics have ------- improved since the new marketing campaign began last quarter.", "o": ["(A) steady", "(B) steadily", "(C) meadiest", "(D) steadied"], "a": "B", "e": "【題目中文翻譯】\n自從上一季度展開新的行銷活動以來，Seviana 化妝品的銷售額持續穩定增長。\n\n【答案選項中文說明與詞性】\n(A) steady (形容詞)\n(B) steadily (副詞)：穩定地、持續地\n(C) meadiest (拼寫錯誤/最高級形)\n(D) steadied (過去式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) steadily\n解析說明：修飾動詞 improved，應填入副詞 steadily。"},
    {"id": "TOEIC_Part5_107_11", "no": "107", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Most applicants to Shim Accounting Services have completed a ------- internship at the company headquarters.", "o": ["(A) clear", "(B) present", "(C) taken", "(D) paid"], "a": "D", "e": "【題目中文翻譯】\n申請 Shim 會計事務所的大多數應徵者均已在公司總部完成有薪實習。\n\n【答案選項中文說明與詞性】\n(A) clear (形容詞)：清楚的\n(B) present (形容詞)：出席的/目前的\n(C) taken (分詞)\n(D) paid (形容詞/分詞)：有薪資的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(D) paid\n解析說明：a paid internship 指「有給薪的實習機會」。"},
    {"id": "TOEIC_Part5_108_11", "no": "108", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Each Beehive Crafts Supply customer may redeem ------- coupon per visit.", "o": ["(A) alone", "(B) one", "(C) first", "(D) once"], "a": "B", "e": "【題目中文翻譯】\n每位 Beehive 手工藝品供應店的顧客每次光臨可兌換一張折價券。\n\n【答案選項中文說明與詞性】\n(A) alone (副詞/形容詞)：單獨地\n(B) one (限定詞/數量詞)：一張/一個\n(C) first (序數詞)：第一\n(D) once (副詞)：一次\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) one\n解析說明：redeem one coupon per visit 表示「每次光臨兌換一張折價券」。"},
    {"id": "TOEIC_Part5_109_11", "no": "109", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Dietrich Dentistry asks patients to provide 24-hour notice to cancel a scheduled -------.", "o": ["(A) appointment", "(B) involvement", "(C) requirement", "(D) investment"], "a": "A", "e": "【題目中文翻譯】\nDietrich 牙醫診所要求患者如需取消已預約的門診，須提前 24 小時通知。\n\n【答案選項中文說明與詞性】\n(A) appointment (名詞)：預約/門診\n(B) involvement (名詞)：參與\n(C) requirement (名詞)：要求\n(D) investment (名詞)：投資\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) appointment\n解析說明：cancel a scheduled appointment 指「取消已排定的預約/診段」。"},
    {"id": "TOEIC_Part5_110_11", "no": "110", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The building inspection has been postponed until next week ------- that the electrical work can be completed.", "o": ["(A) also", "(B) when", "(C) than", "(D) so"], "a": "D", "e": "【題目中文翻譯】\n建築物檢查已延至下週，以便配電工程能夠完工。\n\n【答案選項中文說明與詞性】\n(A) also (副詞)：也\n(B) when (連接詞)：當...時\n(C) than (介系詞/連接詞)：比\n(D) so (連接詞)：以便 (so that)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) so\n解析說明：「so that ...」句型表示「以便/為了...」，引導目的副詞子句。"},
    {"id": "TOEIC_Part5_111_11", "no": "111", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Carson ------- all the arrangements for the company retreat next month.", "o": ["(A) having made", "(B) to make", "(C) making", "(D) will make"], "a": "D", "e": "【題目中文翻譯】\n卡森先生將負責安排下個月公司員工自強活動的所有事宜。\n\n【答案選項中文說明與詞性】\n(A) having made (完成分詞)\n(B) to make (不定詞)\n(C) making (現在分詞)\n(D) will make (未來式主要動詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) will make\n解析說明：主要子句缺少主要動詞，時間標記為 next month，填入未來式動詞 will make。"},
    {"id": "TOEIC_Part5_112_11", "no": "112", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The cafeteria in Morris Hall offers ------- breakfast and lunch for Arai and Ramos associates.", "o": ["(A) complimentary", "(B) accountable", "(C) replaced", "(D) secured"], "a": "A", "e": "【題目中文翻譯】\nMorris 廳的自助餐廳為 Arai 與 Ramos 的同仁提供免費的早餐與午餐。\n\n【答案選項中文說明與詞性】\n(A) complimentary (形容詞)：免費贈送的\n(B) accountable (形容詞)：負有責任的\n(C) replaced (形容詞/分詞)：被替換的\n(D) secured (形容詞/分詞)：安全的/獲得保障的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) complimentary\n解析說明：complimentary breakfast and lunch 表示「免費招待的早午餐」。"},
    {"id": "TOEIC_Part5_113_11", "no": "113", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Visitors to Kensington Corporation must obtain guest passes ------- the security office prior to entering the facility.", "o": ["(A) upon", "(B) from", "(C) toward", "(D) between"], "a": "B", "e": "【題目中文翻譯】\nKensington 公司的訪客在進入設施前，必須先向警衛室取得訪客通行證。\n\n【答案選項中文說明與詞性】\n(A) upon (介系詞)：在...之上/一...就\n(B) from (介系詞)：從/向...\n(C) toward (介系詞)：向、朝著\n(D) between (介系詞)：在...之間\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) from\n解析說明：obtain sth from somewhere 為固定語法，表示「從某處取得某物」。"},
    {"id": "TOEIC_Part5_114_11", "no": "114", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Tachibana Pharmaceuticals' new method of ------- chemical solutions will increase efficiency in the laboratory.", "o": ["(A) combine", "(B) combinations", "(C) combining", "(D) combines"], "a": "C", "e": "【題目中文翻譯】\nTachibana 製藥混合化學溶液的新方法將提升實驗室的效率。\n\n【答案選項中文說明與詞性】\n(A) combine (動詞原形)\n(B) combinations (名詞複數)\n(C) combining (動名詞)\n(D) combines (動詞單數)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) combining\n解析說明：介系詞 of 後接動名詞 combining 及受詞 chemical solutions。"},
    {"id": "TOEIC_Part5_115_11", "no": "115", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Lexino Publisher's dictionary database allows users to search for entries in ------- languages.", "o": ["(A) multiplied", "(B) multiplying", "(C) multiplies", "(D) multiple"], "a": "D", "e": "【題目中文翻譯】\nLexino 出版社的詞典資料庫允許使用者以多種語言搜尋詞條。\n\n【答案選項中文說明與詞性】\n(A) multiplied (分詞)\n(B) multiplying (現在分詞)\n(C) multiplies (動詞)\n(D) multiple (形容詞)：多樣的、多種的\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) multiple\n解析說明：multiple languages 表示「多種語言」，形容詞修飾名詞。"},
    {"id": "TOEIC_Part5_116_11", "no": "116", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "No one is permitted on the factory floor ------- proper safety gear.", "o": ["(A) following", "(B) regarding", "(C) unless", "(D) without"], "a": "D", "e": "【題目中文翻譯】\n未配戴適當安全裝備者，一律不得進入工廠作業區。\n\n【答案選項中文說明與詞性】\n(A) following (介系詞)：在...之後\n(B) regarding (介系詞)：關於\n(C) unless (從屬連接詞)：除非\n(D) without (介系詞)：沒有、未帶\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) without\n解析說明：without proper safety gear 表示「沒有配戴適當安全裝備」，後接名詞片語。"},
    {"id": "TOEIC_Part5_117_11", "no": "117", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Heidt Used Appliance Store guarantees that your purchase will arrive in working -------.", "o": ["(A) condition", "(B) conditional", "(C) conditionally", "(D) conditioned"], "a": "A", "e": "【題目中文翻譯】\nHeidt 二手家電行保證您購買的商品送達時皆具備良好的可運作狀態。\n\n【答案選項中文說明與詞性】\n(A) condition (名詞)：狀況、條件\n(B) conditional (形容詞)：有條件的\n(C) conditionally (副詞)\n(D) conditioned (形容詞/分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) condition\n解析說明：in working condition 為固定商業習慣用語，意為「運作良好/狀況完好」。"},
    {"id": "TOEIC_Part5_118_10", "no": "118", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "------- Ms. Park appreciated the job offer from Seon Advisory Group, she declined the opportunity because she would have to relocate.", "o": ["(A) Now that", "(B) Only if", "(C) While", "(D) Whether"], "a": "C", "e": "【題目中文翻譯】\n雖然朴女士感謝 Seon 顧問集團提供的工作機會，但因為必須搬家，她還是婉拒了這個機會。\n\n【答案選項中文說明與詞性】\n(A) Now that (連接詞)：既然\n(B) Only if (連接詞)：唯有在...\n(C) While (連接詞)：雖然、儘管\n(D) Whether (連接詞)：是否\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) While\n解析說明：While 在此引導讓步子句，相當於 Although/Even though (雖然/儘管)。"},
    {"id": "TOEIC_Part5_119_11", "no": "119", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The convention center is located on Market Street, directly ------- Glenview Shopping Center.", "o": ["(A) opposite", "(B) among", "(C) apart", "(D) nearby"], "a": "A", "e": "【題目中文翻譯】\n會議中心位於市場街，就在 Glenview 購物中心的正對面。\n\n【答案選項中文說明與詞性】\n(A) opposite (介系詞)：在...對面\n(B) among (介系詞)：在...之中\n(C) apart (副詞)：相隔\n(D) nearby (形容詞/副詞)：在附近\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(A) opposite\n解析說明：directly opposite + 場所名詞，表示「就在...正對面」。"},
    {"id": "TOEIC_Part5_120_11", "no": "120", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "------- a small festival celebrating the town's heritage, the Clarytown Celebration has become one of the biggest annual events in the area.", "o": ["(A) Origin", "(B) Originate", "(C) Originated", "(D) Originally"], "a": "D", "e": "【題目中文翻譯】\nClarytown 慶典最初只是一個慶祝小鎮傳統的小型節慶，如今已成為該地區最大的年度盛事之一。\n\n【答案選項中文說明與詞性】\n(A) Origin (名詞)：起源\n(B) Originate (動詞)：起源於\n(C) Originated (分詞)\n(D) Originally (副詞)：起初、原本\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) Originally\n解析說明：修飾名詞片語 a small festival 或同位語結構，應填入副詞 Originally (起初/原本)。"},
    {"id": "TOEIC_Part5_121_11", "no": "121", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "------- of the management team include improving productivity and reducing annual expenditures.", "o": ["(A) Priority", "(B) Prioritizing", "(C) Priorities", "(D) Prioritized"], "a": "C", "e": "【題目中文翻譯】\n管理團隊的首要任務包括提升生產力與減少年度支出。\n\n【答案選項中文說明與詞性】\n(A) Priority (單數名詞)\n(B) Prioritizing (動名詞)\n(C) Priorities (複數名詞)\n(D) Prioritized (分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) Priorities\n解析說明：句子主要動詞為複數動詞 include，主詞需使用複數名詞 Priorities。"},
    {"id": "TOEIC_Part5_122_11", "no": "122", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "------- employees affected by changes to Linerex Corporation's health plan should watch the online presentation.", "o": ["(A) Every", "(B) Much", "(C) Those", "(D) Which"], "a": "C", "e": "【題目中文翻譯】\n受 Linerex 公司醫療計畫變更影響的員工，應觀看線上說明會。\n\n【答案選項中文說明與詞性】\n(A) Every (限定詞，後接單數名詞)\n(B) Much (限定詞，後接不可數名詞)\n(C) Those (限定詞/代名詞，後接複數名詞)\n(D) Which (關係詞/疑問詞)\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) Those\n解析說明：employees 為複數名詞，Those + 複數名詞 + 分詞，表示「那些...的人/員工」。"},
    {"id": "TOEIC_Part5_123_11", "no": "123", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Senior human resources personnel need to ------- at least two training events this year to be eligible for a bonus.", "o": ["(A) have hosted", "(B) be hosted", "(C) have been hosted", "(D) hosting"], "a": "A", "e": "【題目中文翻譯】\n資深人力資源人員今年需要主辦至少兩場培訓活動，方有資格獲得獎金。\n\n【答案選項中文說明與詞性】\n(A) have hosted (不定詞主動完成式)\n(B) be hosted (不定詞被動式)\n(C) have been hosted (不定詞被動完成式)\n(D) hosting (動名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) have hosted\n解析說明：need to + 原形動詞，主動接受詞 training events，選擇 have hosted。"},
    {"id": "TOEIC_Part5_124_11", "no": "124", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Aomori Agriculture Solutions specializes in increasing crop yields ------- the development of better farming techniques.", "o": ["(A) because", "(B) through", "(C) previous", "(D) although"], "a": "B", "e": "【題目中文翻譯】\nAomori 農業解決方案公司專門透過開發更好的耕作技術來提高作物產量。\n\n【答案選項中文說明與詞性】\n(A) because (從屬連接詞)\n(B) through (介系詞)：透過\n(C) previous (形容詞)：之前的\n(D) although (從屬連接詞)\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(B) through\n解析說明：後接名詞片語 the development of ...，表示「藉由/透過...手段」，選擇介系詞 through。"},
    {"id": "TOEIC_Part5_125_11", "no": "125", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Chae Media, Inc., plans to ------- the renovation of its publishing house in Seoul.", "o": ["(A) send away for", "(B) move forward with", "(C) take back from", "(D) watch out for"], "a": "B", "e": "【題目中文翻譯】\nChae 傳媒公司計畫推進其位於首爾的出版社翻修工程。\n\n【答案選項中文說明與詞性】\n(A) send away for (片語)：郵購/函索\n(B) move forward with (片語)：推進/繼續進行\n(C) take back from (片語)：從...收回\n(D) watch out for (片語)：小心/提防\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) move forward with\n解析說明：move forward with the renovation 表示「推進/展開翻修計畫」。"},
    {"id": "TOEIC_Part5_126_11", "no": "126", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The marketing team at Bescura Cars has created a series of ------- humorous commercials, designed to appeal to younger consumers.", "o": ["(A) economically", "(B) exactly", "(C) deliberately", "(D) patiently"], "a": "C", "e": "【題目中文翻譯】\nBescura 汽車的行銷團隊製作了一系列刻意營造幽默風格的廣告，旨在吸引年輕消費者。\n\n【答案選項中文說明與詞性】\n(A) economically (副詞)：經濟地\n(B) exactly (副詞)：精確地\n(C) deliberately (副詞)：刻意地、故意地\n(D) patiently (副詞)：耐心地\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) deliberately\n解析說明：deliberately humorous 指「刻意塑造的幽默效果」。"},
    {"id": "TOEIC_Part5_127_11", "no": "127", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Programmers at Ulrich-Ahn Company are responsible for ensuring that software conforms to the ------- system standards.", "o": ["(A) establish", "(B) established", "(C) establishing", "(D) establishes"], "a": "B", "e": "【題目中文翻譯】\nUlrich-Ahn 公司的程式設計師負責確保軟體符合既定的系統標準。\n\n【答案選項中文說明與詞性】\n(A) establish (動詞)\n(B) established (形容詞/分詞)：既定的、確立的\n(C) establishing (分詞)\n(D) establishes (動詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) established\n解析說明：established system standards 表示「既定/已確立的系統標準」。"},
    {"id": "TOEIC_Part5_128_11", "no": "128", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Pour the cake batter into the pan and shake gently if the batter is ------- distributed.", "o": ["(A) unevenly", "(B) undeniably", "(C) unwillingly", "(D) unknowingly"], "a": "A", "e": "【題目中文翻譯】\n將蛋糕麵糊倒入烤盤中，如果麵糊分佈不均勻，請輕輕搖晃烤盤。\n\n【答案選項中文說明與詞性】\n(A) unevenly (副詞)：不均勻地\n(B) undeniably (副詞)：不可否認地\n(C) unwillingly (副詞)：不情願地\n(D) unknowingly (副詞)：不知情地\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) unevenly\n解析說明：unevenly distributed 指「分佈不平均/不平整」。"},
    {"id": "TOEIC_Part5_129_11", "no": "129", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Geneto Technology uses three ------- of laboratory accuracy to ensure consistent results.", "o": ["(A) indicators", "(B) indicate", "(C) indicating", "(D) indicated"], "a": "A", "e": "【題目中文翻譯】\nGeneto 科技採用三項實驗室精準度指標，以確保結果一致。\n\n【答案選項中文說明與詞性】\n(A) indicators (名詞複數)：指標\n(B) indicate (動詞)\n(C) indicating (分詞)\n(D) indicated (分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) indicators\n解析說明：three 後接可數複數名詞，選擇 indicators。"},
    {"id": "TOEIC_Part5_130_11", "no": "130", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The financial figures released by Tsai and Wu International ------- only to expenses from the month of July.", "o": ["(A) organize", "(B) ponder", "(C) correspond", "(D) subscribe"], "a": "C", "e": "【題目中文翻譯】\n蔡與吳國際公司公布的財務數據僅對應七月份的支出。\n\n【答案選項中文說明與詞性】\n(A) organize (動詞)：組織\n(B) ponder (動詞)：深思\n(C) correspond (動詞)：相符、對應\n(D) subscribe (動詞)：訂閱\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) correspond\n解析說明：correspond to ... 表示「相當於/與...相符對應」。"},
    {"id": "TOEIC_Part5_101_12", "no": "101", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "------- the Chiba office nor the Nagoya office is hiring.", "o": ["(A) Both", "(B) But", "(C) Either", "(D) Neither"], "a": "D", "e": "【題目中文翻譯】\n千葉辦事處和名古屋辦事處都沒有在招聘。\n\n【答案選項中文說明與詞性】\n(A) Both (與 and 連用)\n(B) But (連接詞)\n(C) Either (與 or 連用)\n(D) Neither (與 nor 連用)\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(D) Neither\n解析說明：「Neither A nor B」句型表示「既不A也不B」，後接否定片語。"},
    {"id": "TOEIC_Part5_102_12", "no": "102", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Aromdee will prepare a dish from ------- hometown of Bangkok.", "o": ["(A) he", "(B) his", "(C) him", "(D) himself"], "a": "B", "e": "【題目中文翻譯】\nAromdee 先生將準備一道來自他家鄉曼谷的名菜。\n\n【答案選項中文說明與詞性】\n(A) he (主格代名詞)\n(B) his (所有格形容詞)\n(C) him (受格代名詞)\n(D) himself (反身代名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) his\n解析說明：修飾名詞 hometown，應填入所有格形容詞 his。"},
    {"id": "TOEIC_Part5_103_12", "no": "103", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Korean Star Airlines offers daily nonstop flights ------- London and Busan.", "o": ["(A) aboard", "(B) onto", "(C) up", "(D) between"], "a": "D", "e": "【題目中文翻譯】\n韓國之星航空提供每日往返倫敦與釜山之間的直飛航班。\n\n【答案選項中文說明與詞性】\n(A) aboard (介系詞)：在船/機上\n(B) onto (介系詞)：到...之上\n(C) up (介系詞/副詞)：向上\n(D) between (介系詞)：在...之間\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) between\n解析說明：「between A and B」結構表示「在 A 與 B 之間」。"},
    {"id": "TOEIC_Part5_104_12", "no": "104", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Mr. Hirose ------- at Seventh Street Financial five years ago.", "o": ["(A) works", "(B) worked", "(C) working", "(D) will work"], "a": "B", "e": "【題目中文翻譯】\n廣瀨先生五年前曾在第七街金融公司工作。\n\n【答案選項中文說明與詞性】\n(A) works (現在式)\n(B) worked (過去式)\n(C) working (現在分詞)\n(D) will work (未來式)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) worked\n解析說明：時間標示為五年前 (five years ago)，動詞需使用過去式 worked。"},
    {"id": "TOEIC_Part5_105_12", "no": "105", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "------- of the new employees were able to attend the orientation.", "o": ["(A) Most", "(B) Other", "(C) Else", "(D) Another"], "a": "A", "e": "【題目中文翻譯】\n大多數新員工都得以參加迎新說明會。\n\n【答案選項中文說明與詞性】\n(A) Most (代名詞/限定詞)：大多數\n(B) Other (限定詞)：其他的\n(C) Else (副詞)：其他\n(D) Another (限定詞)：另一個\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) Most\n解析說明：「Most of + 定冠詞/所有格 + 複數名詞」為固定表達，意為「...中的大多數」。"},
    {"id": "TOEIC_Part5_106_12", "no": "106", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "A loud beeping ------- indicates that the copy machine has not been closed securely.", "o": ["(A) sound", "(B) sounds", "(C) sounding", "(D) sounded"], "a": "A", "e": "【題目中文翻譯】\n巨大的嗶嗶聲響代表影印機蓋子沒有蓋緊。\n\n【答案選項中文說明與詞性】\n(A) sound (單數名詞)：聲音\n(B) sounds (複數名詞/動詞)\n(C) sounding (分詞)\n(D) sounded (過去式動詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) sound\n解析說明：A loud beeping sound 作為句子的單數主詞，搭配單數動詞 indicates。"},
    {"id": "TOEIC_Part5_107_12", "no": "107", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Please ------- our Web site to find unique recipes made with Hahm food products.", "o": ["(A) come", "(B) go", "(C) visit", "(D) take"], "a": "C", "e": "【題目中文翻譯】\n請造訪我們的網站，尋找使用 Hahm 食品製作的獨特食譜。\n\n【答案選項中文說明與詞性】\n(A) come (動詞)：來\n(B) go (動詞)：去\n(C) visit (動詞)：造訪/瀏覽\n(D) take (動詞)：拿取\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) visit\n解析說明：visit our Web site 表示「瀏覽/造訪我們的網站」，直接加受詞。"},
    {"id": "TOEIC_Part5_108_12", "no": "108", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Due to construction delays on Maplewood Avenue, employees will ------- need to find alternate routes.", "o": ["(A) probable", "(B) probably", "(C) probability", "(D) probabilities"], "a": "B", "e": "【題目中文翻譯】\n由於 Maplewood 大道上的施工延誤，員工可能需要改走替代路線。\n\n【答案選項中文說明與詞性】\n(A) probable (形容詞)\n(B) probably (副詞)：可能地\n(C) probability (名詞)\n(D) probabilities (名詞複數)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) probably\n解析說明：位於助動詞 will 與主要動詞 need 之間，應填入副詞 probably。"},
    {"id": "TOEIC_Part5_109_12", "no": "109", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Bilto miniature model planes contain hundreds of small parts and must be assembled with -------.", "o": ["(A) contact", "(B) level", "(C) care", "(D) amount"], "a": "C", "e": "【題目中文翻譯】\nBilto 微型模型飛機包含數百個小零件，組裝時必須非常小心。\n\n【答案選項中文說明與詞性】\n(A) contact (名詞)：接觸/聯絡\n(B) level (名詞)：水準/層級\n(C) care (名詞)：小心、謹慎\n(D) amount (名詞)：數量\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) care\n解析說明：assemble with care 表示「小心翼翼地組裝」。"},
    {"id": "TOEIC_Part5_110_12", "no": "110", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The ------- image on this month's magazine cover is credited to Marlot Images.", "o": ["(A) creative", "(B) creatively", "(C) creating", "(D) creativity"], "a": "A", "e": "【題目中文翻譯】\n本月雜誌封面上的創意圖片歸功於 Marlot Images。\n\n【答案選項中文說明與詞性】\n(A) creative (形容詞)：有創意的\n(B) creatively (副詞)\n(C) creating (現在分詞)\n(D) creativity (名詞)：創意\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) creative\n解析說明：修飾名詞 image，應填入形容詞 creative。"},
    {"id": "TOEIC_Part5_111_12", "no": "111", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Participation this year was the largest ------- in the history of the Securitas conference.", "o": ["(A) totally", "(B) ever", "(C) soon", "(D) hardly"], "a": "B", "e": "【題目中文翻譯】\n今年是 Securitas 會議歷史上參與人數最多的一次。\n\n【答案選項中文說明與詞性】\n(A) totally (副詞)：完全地\n(B) ever (副詞)：有史以來、曾經\n(C) soon (副詞)：很快\n(D) hardly (副詞)：幾乎不\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) ever\n解析說明：最高級 (the largest) + ever，表示「有史以來最...的」。"},
    {"id": "TOEIC_Part5_112_12", "no": "112", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "Ms. Fields is not able to travel from New York to Buenos Aires ------- sufficient notice.", "o": ["(A) inside", "(B) except", "(C) about", "(D) without"], "a": "D", "e": "【題目中文翻譯】\n如果沒有足夠提前通知，Fields 女士無法從紐約前往布宜諾斯艾利斯。\n\n【答案選項中文說明與詞性】\n(A) inside (介系詞)：在...裡面\n(B) except (介系詞)：除了...之外\n(C) about (介系詞)：關於\n(D) without (介系詞)：沒有、未經\n\n【文法觀點與解析】\n考點類型：介系詞\n正確答案：(D) without\n解析說明：without sufficient notice 為常見商業用語，指「在沒有足夠事前通知的情況下」。"},
    {"id": "TOEIC_Part5_113_12", "no": "113", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Yuvaves Transit Company drivers should have their vehicles inspected -------.", "o": ["(A) rather", "(B) annually", "(C) quite", "(D) highly"], "a": "B", "e": "【題目中文翻譯】\nYuvaves 客運公司的司機應每年對其車輛進行檢驗。\n\n【答案選項中文說明與詞性】\n(A) rather (副詞)：相當\n(B) annually (副詞)：每年地\n(C) quite (副詞)：相當\n(D) highly (副詞)：高度地\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(B) annually\n解析說明：inspected annually 表示「每年進行車輛檢驗」。"},
    {"id": "TOEIC_Part5_114_12", "no": "114", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Cell Choice marketers are ------- to become familiar with competitors' products and advertising.", "o": ["(A) encourage", "(B) encourages", "(C) encouraged", "(D) encouraging"], "a": "C", "e": "【題目中文翻譯】\nCell Choice 的行銷人員被鼓勵熟悉競爭對手的產品與廣告。\n\n【答案選項中文說明與詞性】\n(A) encourage (動詞原形)\n(B) encourages (動詞單數)\n(C) encouraged (被動過去分詞)\n(D) encouraging (現在分詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(C) encouraged\n解析說明：be encouraged to do sth 表示被動語態「被鼓勵去...」。"},
    {"id": "TOEIC_Part5_115_12", "no": "115", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The customer service department has seen a ------- decrease in the number of complaints over the past year.", "o": ["(A) dramatic", "(B) polite", "(C) frequent", "(D) different"], "a": "A", "e": "【題目中文翻譯】\n客戶服務部門在過去一年中看到投訴數量大幅下降。\n\n【答案選項中文說明與詞性】\n(A) dramatic (形容詞)：顯著的、急劇的\n(B) polite (形容詞)：有禮貌的\n(C) frequent (形容詞)：頻繁的\n(D) different (形容詞)：不同的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) dramatic\n解析說明：a dramatic decrease 表示「急劇/顯著的下降」。"},
    {"id": "TOEIC_Part5_116_12", "no": "116", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The financial review board has stated that no budget proposal may ------- ten pages.", "o": ["(A) excessive", "(B) excess", "(C) exceeding", "(D) exceed"], "a": "D", "e": "【題目中文翻譯】\n財務審查委員會已聲明，任何預算提案均不得超過十頁。\n\n【答案選項中文說明與詞性】\n(A) excessive (形容詞)：過度的\n(B) excess (名詞/形容詞)：過量\n(C) exceeding (分詞)\n(D) exceed (動詞原形)：超過\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) exceed\n解析說明：助動詞 may 後面接原形動詞 exceed。"},
    {"id": "TOEIC_Part5_117_12", "no": "117", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "As president, Ms. Min made great efforts to ------- a productive environment at Chae Investment Corporation.", "o": ["(A) process", "(B) estimate", "(C) establish", "(D) participate"], "a": "C", "e": "【題目中文翻譯】\n作為總裁，閔女士付出了巨大的努力在 Chae 投資公司建立一個高效的工作環境。\n\n【答案選項中文說明與詞性】\n(A) process (動詞)：處理\n(B) estimate (動詞)：估計\n(C) establish (動詞)：建立、創立\n(D) participate (動詞)：參加\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) establish\n解析說明：establish an environment 表示「建立...環境」。"},
    {"id": "TOEIC_Part5_118_11", "no": "118", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The city council will meet tomorrow to field questions from ------- concerning the new water tower.", "o": ["(A) resident", "(B) residents", "(C) residences", "(D) residential"], "a": "B", "e": "【題目中文翻譯】\n市議會明天將開會解答居民關於新水塔的疑問。\n\n【答案選項中文說明與詞性】\n(A) resident (單數名詞)\n(B) residents (複數名詞)：居民\n(C) residences (名詞複數)：住宅\n(D) residential (形容詞)：住宅區的\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) residents\n解析說明：field questions from residents 表示「回答居民們提出的問題」。"},
    {"id": "TOEIC_Part5_119_12", "no": "119", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Cruz-Alva Oil provides ------- priced solutions for all your energy needs.", "o": ["(A) competing", "(B) competition", "(C) competitive", "(D) competitively"], "a": "D", "e": "【題目中文翻譯】\nCruz-Alva 石油公司為您的所有能源需求提供具價格競爭力的解決方案。\n\n【答案選項中文說明與詞性】\n(A) competing (分詞)\n(B) competition (名詞)\n(C) competitive (形容詞)\n(D) competitively (副詞)：具競爭力地\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) competitively\n解析說明：修飾形容詞 priced (competitively priced 表示「定價具競爭力的」)，應填入副詞 competitively。"},
    {"id": "TOEIC_Part5_120_12", "no": "120", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Southenic Electronics' technicians are on hand 24 hours a day ------- you can be at ease knowing help is always available.", "o": ["(A) because of", "(B) so", "(C) everything", "(D) until"], "a": "B", "e": "【題目中文翻譯】\nSouthenic 電子的技術人員 24 小時隨時待命，因此您可以放心知道隨時能獲得協助。\n\n【答案選項中文說明與詞性】\n(A) because of (介系詞)：因為\n(B) so (對等連接詞)：所以、以便\n(C) everything (代名詞)\n(D) until (介系詞/連接詞)：直到\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(B) so\n解析說明：引導結果/目的副詞子句，相當於 so that (以便/所以)。"},
    {"id": "TOEIC_Part5_121_12", "no": "121", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Strong strategic-thinking ------- and sharp marketing instincts are important qualities for a successful product manager.", "o": ["(A) skills", "(B) findings", "(C) realities", "(D) approximations"], "a": "A", "e": "【題目中文翻譯】\n強大的戰略思考能力與敏銳的行銷直覺是成功產品經理的重要特質。\n\n【答案選項中文說明與詞性】\n(A) skills (名詞複數)：技能、能力\n(B) findings (名詞複數)：調查結果\n(C) realities (名詞複數)：現實\n(D) approximations (名詞複數)：估算\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) skills\n解析說明：strategic-thinking skills 指「戰略思考能力/技巧」。"},
    {"id": "TOEIC_Part5_122_12", "no": "122", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "------- of city buses will attend a training session on new vehicles in the coming months.", "o": ["(A) Operations", "(B) Operators", "(C) Operate", "(D) Operating"], "a": "B", "e": "【題目中文翻譯】\n公車司機們將在未來幾個月內參加關於新車輛的培訓課程。\n\n【答案選項中文說明與詞性】\n(A) Operations (名詞複數)：營運/操作\n(B) Operators (名詞複數)：駕駛員、操作員\n(C) Operate (動詞)\n(D) Operating (分詞/動名詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) Operators\n解析說明：bus operators 指「公車司機/駕駛員」，作句子的複數主詞。"},
    {"id": "TOEIC_Part5_123_12", "no": "123", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Renovations on the top floor of the Melaka Building are set to ------- after the elevators are installed in early August.", "o": ["(A) expire", "(B) construct", "(C) commence", "(D) arrange"], "a": "C", "e": "【題目中文翻譯】\n馬六甲大樓頂樓的翻修工程預計在 8 月初電梯安裝完成後動工開始。\n\n【答案選項中文說明與詞性】\n(A) expire (動詞)：到期\n(B) construct (動詞)：建造\n(C) commence (動詞)：開始、動工\n(D) arrange (動詞)：安排\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) commence\n解析說明：be set to commence 表示「預計將開始/展開」。"},
    {"id": "TOEIC_Part5_124_12", "no": "124", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "At Ben Flores Blinds, first-time customers can benefit from ------- rates of 30 percent off.", "o": ["(A) introducing", "(B) introductions", "(C) introduced", "(D) introductory"], "a": "D", "e": "【題目中文翻譯】\n在 Ben Flores 百葉窗，首次光臨的顧客可享受七折的優惠體驗價。\n\n【答案選項中文說明與詞性】\n(A) introducing (分詞)\n(B) introductions (名詞複數)\n(C) introduced (分詞)\n(D) introductory (形容詞)：引介的、體驗/優惠的\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(D) introductory\n解析說明：introductory rates 表示「體驗價/首購優惠價格」。"},
    {"id": "TOEIC_Part5_125_12", "no": "125", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "------- your return has been received, a refund will be issued to your account within three business days.", "o": ["(A) In order that", "(B) Instead", "(C) Now that", "(D) Meanwhile"], "a": "C", "e": "【題目中文翻譯】\n既然您的退貨已經收到，退款將在三個工作天內發放至您的帳戶。\n\n【答案選項中文說明與詞性】\n(A) In order that (從屬連接詞)：以便\n(B) Instead (副詞)：反而\n(C) Now that (從屬連接詞)：既然\n(D) Meanwhile (副詞)：同時\n\n【文法觀點與解析】\n考點類型：連結詞\n正確答案：(C) Now that\n解析說明：Now that 引導表示原因的副詞子句（既成事實的原因，意為「既然」）。"},
    {"id": "TOEIC_Part5_126_12", "no": "126", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Last year, Entertainment Azusa, Inc., and Sohn Multimedia decided that ------- their expertise and resources would increase profits for both organizations.", "o": ["(A) combining", "(B) combined", "(C) combines", "(D) combine"], "a": "A", "e": "【題目中文翻譯】\n去年，Azusa 娛樂公司與 Sohn 多媒體公司認為，結合雙方的專業知識與資源將能增加兩家機構的利潤。\n\n【答案選項中文說明與詞性】\n(A) combining (動名詞)\n(B) combined (分詞)\n(C) combines (動詞單數)\n(D) combine (動詞原形)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) combining\n解析說明：that 引導的子句中，需要動名詞 combining 作為名詞子句的主詞。"},
    {"id": "TOEIC_Part5_127_12", "no": "127", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Before the laboratory carts can be used to transport ------- materials, technicians must wipe all exposed surfaces with a disinfectant cloth.", "o": ["(A) vague", "(B) passive", "(C) sensitive", "(D) demonstrative"], "a": "C", "e": "【題目中文翻譯】\n在實驗室手推車用於運送敏感材料之前，技術人員必須用消毒布擦拭所有暴露的表面。\n\n【答案選項中文說明與詞性】\n(A) vague (形容詞)：模糊的\n(B) passive (形容詞)：被動的\n(C) sensitive (形容詞)：敏感的、機密的\n(D) demonstrative (形容詞)：示範的\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(C) sensitive\n解析說明：sensitive materials 表示「敏感/易受干擾的化學/實驗材料」。"},
    {"id": "TOEIC_Part5_128_12", "no": "128", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "As the publication date of the sequel to the controversial novel approaches, public ------- is growing exponentially.", "o": ["(A) anticipation", "(B) anticipatory", "(C) anticipated", "(D) anticipate"], "a": "A", "e": "【題目中文翻譯】\n隨著這部爭議小說續集的出版日期臨近，大眾的期盼正以指數級成長。\n\n【答案選項中文說明與詞性】\n(A) anticipation (名詞)：期盼、預期\n(B) anticipatory (形容詞)\n(C) anticipated (分詞)\n(D) anticipate (動詞)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(A) anticipation\n解析說明：public anticipation 表示「大眾的期盼/期待」，作子句主詞。"},
    {"id": "TOEIC_Part5_129_12", "no": "129", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "For the duration of Ms. Dernal's leave, her corporate and private accounts will be overseen by Jian Wu and David Dembo, -------.", "o": ["(A) respectively", "(B) almost", "(C) likewise", "(D) even"], "a": "A", "e": "【題目中文翻譯】\n在 Dernal 女士休假期間，她的公司帳戶和私人帳戶將分別由 Jian Wu 和 David Dembo 負責監督。\n\n【答案選項中文說明與詞性】\n(A) respectively (副詞)：分別地、各自地\n(B) almost (副詞)：幾乎\n(C) likewise (副詞)：同樣地\n(D) even (副詞)：甚至\n\n【文法觀點與解析】\n考點類型：字彙\n正確答案：(A) respectively\n解析說明：respectively 放在句尾，表示兩組項目（公司與私人帳戶 vs Jian Wu 與 David Dembo）依序對應。"},
    {"id": "TOEIC_Part5_130_12", "no": "130", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Improvements in irrigation technology throughout the region were followed by ------- gains in corn production.", "o": ["(A) proportionally", "(B) proportional", "(C) proportioning", "(D) proportions"], "a": "B", "e": "【題目中文翻譯】\n該地區灌溉技術的改善伴隨著玉米產量的相應成比例增長。\n\n【答案選項中文說明與詞性】\n(A) proportionally (副詞)\n(B) proportional (形容詞)：成比例的、相稱的\n(C) proportioning (分詞)\n(D) proportions (名詞複數)\n\n【文法觀點與解析】\n考點類型：詞性\n正確答案：(B) proportional\n解析說明：修飾名詞 gains，應填入形容詞 proportional。"},
    {"id": "TOEIC_Part5_A2-例題-1", "no": "A2-例題-1", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The organization carried out research to obtain ------- about cellphone use among teenagers.", "o": ["(A) results", "(B) result", "(C) resultant", "(D) resulted"], "a": "A", "e": "【題目中文翻譯】該組織展開研究以取得關於青少年使用手機的結果資訊。\n【考點解析】及物動詞 obtain 後接複數名詞 results。"},
    {"id": "TOEIC_Part5_A2-例題-2", "no": "A2-例題-2", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "After the merger, the two corporations have made huge efforts to build a strong and ------- relationship.", "o": ["(A) endures", "(B) enduring", "(C) endurance", "(D) endure"], "a": "B", "e": "【題目中文翻譯】合併後，兩間公司付出了巨大的努力以建立強大且持久的關係。\n【考點解析】由 and 與 strong 平行對稱，修飾 relationship，需填入形容詞 enduring（持久的）。"},
    {"id": "TOEIC_Part5_A2-例題-3", "no": "A2-例題-3", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Because of the ------- high volume of orders received, the workers will have to work overtime this month.", "o": ["(A) exactly", "(B) excitedly", "(C) extremely", "(D) extensively"], "a": "C", "e": "【題目中文翻譯】由於收到極高數量的訂單，工人本月必須加班。\n【考點解析】修飾形容詞 high，應填入副詞 extremely（極度地）。"},
    {"id": "TOEIC_Part5_A2-例題-4", "no": "A2-例題-4", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "As Jack was asked to move out before the lease expired, he got ------- from the landlord for his moving cost.", "o": ["(A) republication", "(B) reassessment", "(C) reconsideration", "(D) reimbursement"], "a": "D", "e": "【題目中文翻譯】由於傑克在租約到期前被要求搬離，他從房東那裡獲得了搬家費用的補償。\n【考點解析】reimbursement 意為「補償/退款/報銷」。"},
    {"id": "TOEIC_Part5_A2-例題-5", "no": "A2-例題-5", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "After browsing the e-commerce site for an hour, Samantha added 17 items to the shopping cart, which ------- $258.50, inclusive of a shipping fee.", "o": ["(A) totaled", "(B) grossed", "(C) netted", "(D) summed"], "a": "A", "e": "【題目中文翻譯】在瀏覽電子商務網站一小時後，薩曼莎將17件商品加入購物車，含運費總計258.50美元。\n【考點解析】totaled 意為「總計為」。"},
    {"id": "TOEIC_Part5_A2-例題-6", "no": "A2-例題-6", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The black coffee was so ------- that the customer demanded the waiter make another cup for him.", "o": ["(A) flat", "(B) light", "(C) weak", "(D) thin"], "a": "C", "e": "【題目中文翻譯】這杯黑咖啡味道太淡了，顧客要求服務生重新為他做一杯。\n【考點解析】描述茶或咖啡味道淡用 weak。"},
    {"id": "TOEIC_Part5_A2-例題-7", "no": "A2-例題-7", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The company's revenue has been increasing over the past few years, ------- its expenses have also been rising significantly.", "o": ["(A) so", "(B) as", "(C) for", "(D) but"], "a": "D", "e": "【題目中文翻譯】公司過去幾年的收入一直在增加，但支出也大幅上升。\n【考點解析】前後句呈現轉折語意，選擇對等連接詞 but。"},
    {"id": "TOEIC_Part5_A2-例題-8", "no": "A2-例題-8", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "We can either upgrade the existing equipment in the factory ------- invest in new machinery to improve efficiency.", "o": ["(A) or", "(B) and", "(C) nor", "(D) but"], "a": "A", "e": "【題目中文翻譯】我們要麼升級工廠現有設備，要麼投資新機械以提高效率。\n【考點解析】固定相關連接詞搭配 either...or。"},
    {"id": "TOEIC_Part5_A2-例題-9", "no": "A2-例題-9", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Mr. Smith didn't receive any reply, ------- he made a complaint to the hotel clerk about the noise from next-door guests.", "o": ["(A) unless", "(B) as if", "(C) though", "(D) despite"], "a": "C", "e": "【題目中文翻譯】史密斯先生沒有收到任何回覆，儘管他就隔壁客人產生的噪音向飯店櫃檯投訴了。\n【考點解析】though 表轉折引導從屬子句。"},
    {"id": "TOEIC_Part5_A2-例題-10", "no": "A2-例題-10", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "The company ran a background check on the applicant ------- employing him as a mechanical engineer.", "o": ["(A) if", "(B) before", "(C) whereas", "(D) as for"], "a": "B", "e": "【題目中文翻譯】公司在僱用該申請人擔任機械工程師之前，對其進行了背景調查。\n【考點解析】before 可作介系詞後接動名詞 employing。"},
    {"id": "TOEIC_Part5_A2-例題-11", "no": "A2-例題-11", "f": {"分類": "連接副詞"}, "ref": "Part 5", "q": "Our package tour makes it more affordable for people to travel in Canada; -------, people can have an extra 10 percent off when buying the tour by June 22.", "o": ["(A) therefore", "(B) however", "(C) moreover", "(D) otherwise"], "a": "C", "e": "【題目中文翻譯】我們的套裝行程讓人們前往加拿大旅遊更加負擔得起；此外，於6月22日前購買該行程的人還可享有額外9折優惠。\n【考點解析】moreover 意為「此外/而且」，補充說明優惠資訊。"},
    {"id": "TOEIC_Part5_A2-例題-12", "no": "A2-例題-12", "f": {"分類": "連接副詞"}, "ref": "Part 5", "q": "Click \"Return to Questionnaire\" if you want to make any changes to your answers; -------, scroll to the end of the webpage and click \"Submit.\"", "o": ["(A) however", "(B) instead", "(C) otherwise", "(D) furthermore"], "a": "C", "e": "【題目中文翻譯】若想修改答案請點擊「返回問卷」；否則，請滾動至網頁底部並點擊「提交」。\n【考點解析】otherwise 意為「否則/不然」。"},
    {"id": "TOEIC_Part5_A2-例題-13", "no": "A2-例題-13", "f": {"分類": "介系詞片語"}, "ref": "Part 5", "q": "Due to the new safety regulations, employees must wear protective gear ------- handling hazardous materials.", "o": ["(A) in spite of", "(B) in case of", "(C) in addition to", "(D) while"], "a": "D", "e": "【題目中文翻譯】由於新的安全法規，員工在處理危險物品時必須佩戴防護裝備。\n【考點解析】while + V-ing 表示「在……期間/處理……時」。"},
    {"id": "TOEIC_Part5_A2-例題-14", "no": "A2-例題-14", "f": {"分類": "介系詞片語"}, "ref": "Part 5", "q": "------- the recent company feedback, the marketing team decided to revise their marketing strategies.", "o": ["(A) In light of", "(B) By means of", "(C) In charge of", "(D) On behalf of"], "a": "A", "e": "【題目中文翻譯】鑑於公司最近的反饋，行銷團隊決定修改其行銷策略。\n【考點解析】In light of 意為「鑑於/考量到」。"},
    {"id": "TOEIC_Part5_A2-例題-15", "no": "A2-例題-15", "f": {"分類": "If條件子句"}, "ref": "Part 5", "q": "If the marketing team ------- more data, they would be able to make informed decisions on advertising strategies.", "o": ["(A) have", "(B) had", "(C) has", "(D) having"], "a": "B", "e": "【題目中文翻譯】如果行銷團隊有更多數據，他們就能在廣告策略上做出明智決定。\n【考點解析】與現在事實相反的假設語氣：If + S + 過去式動詞 (had), S + would + V。"},
    {"id": "TOEIC_Part5_A2-例題-16", "no": "A2-例題-16", "f": {"分類": "If條件子句"}, "ref": "Part 5", "q": "If the client ------- their requirements clearly, the project would have been completed on time.", "o": ["(A) states", "(B) stated", "(C) would state", "(D) had stated"], "a": "D", "e": "【題目中文翻譯】如果客戶當時清楚說明需求，專案就能按時完成了。\n【考點解析】與過去事實相反的假設語氣：If + S + had + Vpp (had stated), S + would have + Vpp。"},
    {"id": "TOEIC_Part5_A2-例題-17", "no": "A2-例題-17", "f": {"分類": "分詞構句"}, "ref": "Part 5", "q": "The team ------- the new software features has been working overtime to meet the launch deadline.", "o": ["(A) implements", "(B) implementing", "(C) implemented", "(D) to implement"], "a": "B", "e": "【題目中文翻譯】負責實施新軟體功能的團隊一直在加班以趕上發布截止日期。\n【考點解析】現在分詞片語 implementing... 主動修飾主詞 The team。"},
    {"id": "TOEIC_Part5_A2-例題-18", "no": "A2-例題-18", "f": {"分類": "分詞構句"}, "ref": "Part 5", "q": "------- by the new marketing strategy, the company's sales increased by 20% in the last quarter.", "o": ["(A) Inspiring", "(B) Inspires", "(C) Inspired", "(D) To inspire"], "a": "C", "e": "【題目中文翻譯】受到新行銷策略的鼓舞，公司的銷售額在上季度增加了20%。\n【考點解析】過去分詞片語 Inspired by... 被動修飾主詞 the company's sales。"},
    {"id": "TOEIC_Part5_1", "no": "1", "f": {"分類": "形容詞"}, "ref": "Part 5", "q": "The leader demanded that the team redesign the second sample because it was very ------- to the first one.", "o": ["(A) specific", "(B) essential", "(C) same", "(D) similar"], "a": "D", "e": "【題目中文翻譯】組長要求團隊重新設計第二個樣品，因為它與第一個樣品非常相似。\n【考點解析】be similar to 為固定搭配片語，表示「與……相似」。"},
    {"id": "TOEIC_Part5_2", "no": "2", "f": {"分類": "比較級"}, "ref": "Part 5", "q": "The president's motto is \"The harder you work, the ------- the outcome will be.\"", "o": ["(A) worse", "(B) worst", "(C) better", "(D) best"], "a": "C", "e": "【題目中文翻譯】總裁的格言是「你越努力工作，結果就會越好」。\n【考點解析】句型「The + 比較級..., the + 比較級...」表示「越……就越……」。"},
    {"id": "TOEIC_Part5_3", "no": "3", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "As a ------- of gratitude for your patronage, here is a coupon for a free appetizer on your next visit.", "o": ["(A) token", "(B) mark", "(C) signal", "(D) step"], "a": "A", "e": "【題目中文翻譯】為表達對您光顧的感謝，這是一張您下次光臨可免費獲得前菜的優惠券。\n【考點解析】as a token of gratitude 為固定片語，意為「作為感謝的表示/象徵」。"},
    {"id": "TOEIC_Part5_4", "no": "4", "f": {"分類": "關係代名詞"}, "ref": "Part 5", "q": "The artist, ------- paintings are displayed in the gallery, is from Brazil.", "o": ["(A) whom", "(B) whose", "(C) which", "(D) where"], "a": "B", "e": "【題目中文翻譯】那位畫作展出於畫廊的藝術家來自巴西。\n【考點解析】空格後接名詞 paintings，需用關係代名詞所有格 whose 表示「該藝術家的畫作」。"},
    {"id": "TOEIC_Part5_5", "no": "5", "f": {"分類": "代名詞"}, "ref": "Part 5", "q": "These vacation packages are mainly designed for ------- who are interested in outdoor activities.", "o": ["(A) that", "(B) these", "(C) this", "(D) those"], "a": "D", "e": "【題目中文翻譯】這些度假行程套裝主要是為對戶外活動感興趣的人設計的。\n【考點解析】those who... 為固定搭配，表示「那些……的人」。"},
    {"id": "TOEIC_Part5_6", "no": "6", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "By partnering with some well-known fashion designers, James Sports has achieved its highest sales -------.", "o": ["(A) still", "(B) ever", "(C) far", "(D) instead"], "a": "B", "e": "【題目中文翻譯】透過與幾位知名時裝設計師合作，James Sports 達到了有史以來的最高銷售額。\n【考點解析】highest sales ever 意為「有史以來最高的銷售額」，ever 用於最高級後表示「有史以來/有過之最」。"},
    {"id": "TOEIC_Part5_7", "no": "7", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "Solving the grave financial crisis as ------- as possible is the new CFO's first urgent task.", "o": ["(A) quickly", "(B) quickness", "(C) quicken", "(D) quicker"], "a": "A", "e": "【題目中文翻譯】儘快解決嚴重的財務危機是新任財務長的首要緊急任務。\n【考點解析】as + 副詞 + as possible 結構，修飾動名詞 solving，應選副詞 quickly。"},
    {"id": "TOEIC_Part5_8", "no": "8", "f": {"分類": "分詞"}, "ref": "Part 5", "q": "The documents ------- on the manager's desk are important and need immediate attention.", "o": ["(A) lay", "(B) lying", "(C) laid", "(D) lays"], "a": "B", "e": "【題目中文翻譯】擺在經理桌上的文件很重要，需要立即處理。\n【考點解析】lie（擺放/平躺）的現在分詞為 lying，用作分詞片語修飾主詞 documents。"},
    {"id": "TOEIC_Part5_9", "no": "9", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "According to the famous designer Maya Ono, one should be good at ------- trends to be successful in the fashion business.", "o": ["(A) mentioning", "(B) conducting", "(C) predicting", "(D) tackling"], "a": "C", "e": "【題目中文翻譯】根據知名設計師小野真由的說法，要在時尚界獲得成功，必須擅長預測趨勢。\n【考點解析】predicting trends 意為「預測趨勢」。"},
    {"id": "TOEIC_Part5_10", "no": "10", "f": {"分類": "名詞"}, "ref": "Part 5", "q": "Henry Warren, a ------- from the non-profit organization, Good 365, is one of the panelists at the conference.", "o": ["(A) represent", "(B) represented", "(C) representation", "(D) representative"], "a": "D", "e": "【題目中文翻譯】亨利·華倫是來自非營利組織 Good 365 的代表，也是本次會議的座談小組成員之一。\n【考點解析】不定冠詞 a 後接可數單數名詞指人，應選 representative（代表）。"},
    {"id": "TOEIC_Part5_11", "no": "11", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "The popular fashion magazine, Beauty Life, is published ------- with a circulation of approximately 50,000.", "o": ["(A) along", "(B) bimonthly", "(C) overtime", "(D) elsewhere"], "a": "B", "e": "【題目中文翻譯】熱門時尚雜誌《Beauty Life》雙月出版一次，發行量約 50,000 份。\n【考點解析】bimonthly 作副詞表示「雙月一次地/每兩月一次地」。"},
    {"id": "TOEIC_Part5_12", "no": "12", "f": {"分類": "假設語氣"}, "ref": "Part 5", "q": "If Jake ------- the warning signs, he wouldn't have entered the restricted area.", "o": ["(A) saw", "(B) would see", "(C) had seen", "(D) sees"], "a": "C", "e": "【題目中文翻譯】如果傑克當時有看到警告標誌，他就不會進入管制區域了。\n【考點解析】與過去事實相反的假設語氣：If + 主詞 + had Vpp, 主詞 + would/could/might + have Vpp。"},
    {"id": "TOEIC_Part5_13", "no": "13", "f": {"分類": "關係代名詞"}, "ref": "Part 5", "q": "The author's latest novel, which focuses on the people and places ------- inspired her creativity, is on the New York Times best-seller list.", "o": ["(A) that", "(B) who", "(C) what", "(D) where"], "a": "A", "e": "【題目中文翻譯】該作者的最新小說聚焦於激發她創作靈感的人與地方，已登上紐約時報暢銷書排行榜。\n【考點解析】先行詞同時包含「人與物」（people and places）時，關係代名詞必須使用 that。"},
    {"id": "TOEIC_Part5_14", "no": "14", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "The celebration to mark the corporate anniversary was held in the landscaped garden ------- the hotel.", "o": ["(A) throughout", "(B) among", "(C) beyond", "(D) outside"], "a": "D", "e": "【題目中文翻譯】慶祝公司週年的慶典在飯店外面的景觀花園舉行。\n【考點解析】outside 為介系詞，表示「在……外面」。"},
    {"id": "TOEIC_Part5_15", "no": "15", "f": {"分類": "形容詞"}, "ref": "Part 5", "q": "To the president's relief, more than 80 percent of the people surveyed found the company's after-sale service -------.", "o": ["(A) satisfactory", "(B) satisfactorily", "(C) satisfy", "(D) satisfied"], "a": "A", "e": "【題目中文翻譯】讓總裁鬆了一口氣的是，超過80%受訪者認為公司的售後服務令人滿意。\n【考點解析】find + 受詞 + 形容詞補語，描述事物本身令人滿意用 satisfactory。"},
    {"id": "TOEIC_Part5_16", "no": "16", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The Heat Infinity is a new ------- to Adventure Life's ski clothing series.", "o": ["(A) addition", "(B) injection", "(C) relation", "(D) section"], "a": "A", "e": "【題目中文翻譯】Heat Infinity 是 Adventure Life 滑雪服飾系列的新產品。\n【考點解析】a new addition to... 表示「……的新增項目/新成員」。"},
    {"id": "TOEIC_Part5_17", "no": "17", "f": {"分類": "被動語態"}, "ref": "Part 5", "q": "The study which ------- by Brandon University in February indicated that nearly 72 percent of young people want to start an online business.", "o": ["(A) had released", "(B) was released", "(C) released", "(D) was releasing"], "a": "B", "e": "【題目中文翻譯】布蘭登大學二月份發布的研究指出，將近 72% 的年輕人想創業做網路生意。\n【考點解析】研究是被發布（was released），關係子句中使用過去式被動語態。"},
    {"id": "TOEIC_Part5_18", "no": "18", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "------- the fact that attendance is quite low, we still have to go through all of the agenda items.", "o": ["(A) Whether", "(B) Given", "(C) Although", "(D) Despite"], "a": "D", "e": "【題目中文翻譯】儘管出席率相當低，我們仍然必須逐一討論所有議程項目。\n【考點解析】Despite the fact that... 表示「儘管……的事實」，介系詞 Despite 後接名詞片語 the fact。"},
    {"id": "TOEIC_Part5_19", "no": "19", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "The chairman started the board meeting ------- at 9:30 a.m. after the attendees had taken their seats.", "o": ["(A) sharply", "(B) totally", "(C) promptly", "(D) rightly"], "a": "C", "e": "【題目中文翻譯】在與會者就座後，主席於上午 9:30 準時開始了董事會會議。\n【考點解析】promptly at + 時間，表示「在……時間準時」。"},
    {"id": "TOEIC_Part5_20", "no": "20", "f": {"分類": "形容詞"}, "ref": "Part 5", "q": "Because of the ------- construction noise outside, the project manager had difficulty giving his presentation.", "o": ["(A) faint", "(B) active", "(C) constant", "(D) eternal"], "a": "C", "e": "【題目中文翻譯】由於外面持續不斷的施工噪音，專案經理在進行簡報時遇到困難。\n【考點解析】constant noise 表示「持續不斷的噪音」。"},
    {"id": "TOEIC_Part5_21", "no": "21", "f": {"分類": "動詞片語"}, "ref": "Part 5", "q": "The quality management team will pick ------- the discussion on quality control after taking a forty-minute lunch break.", "o": ["(A) out", "(B) over", "(C) up", "(D) on"], "a": "C", "e": "【題目中文翻譯】品質管理團隊在午餐休息 40 分鐘後，將繼續開會討論品質管制。\n【考點解析】pick up a discussion 表示「中斷後重啟/繼續討論」。"},
    {"id": "TOEIC_Part5_22", "no": "22", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Tired of ------- customer complaints all the time, Sophia Meyer is considering resigning her position of customer service manager.", "o": ["(A) dealing", "(B) filing", "(C) serving", "(D) handling"], "a": "D", "e": "【題目中文翻譯】厭倦了總是處理客戶抱怨，索菲亞·梅爾正考慮辭去客服經理的職務。\n【考點解析】handling customer complaints 表示「處理客戶投訴/抱怨」；若用 deal 需搭配 with（dealing with）。"},
    {"id": "TOEIC_Part5_23", "no": "23", "f": {"分類": "名詞"}, "ref": "Part 5", "q": "This elegant hotel offers ------- with fabulous views of Lake Motosu and a hot spring pool for guests to bathe in.", "o": ["(A) accommodate", "(B) accommodations", "(C) accommodating", "(D) accommodated"], "a": "B", "e": "【題目中文翻譯】這家典雅的飯店提供可欣賞本棲湖絕佳景色之客房住宿，並設有溫泉池供住客浸泡。\n【考點解析】及物動詞 offer 後接名詞受詞，accommodations 為複數名詞，意為「住宿/客房」。"},
    {"id": "TOEIC_Part5_24", "no": "24", "f": {"分類": "片語"}, "ref": "Part 5", "q": "If ------- you'd like to change or cancel your flight reservation, you will need to contact our customer service specialist online or by phone.", "o": ["(A) for any reason", "(B) in addition to", "(C) in that case", "(D) even though"], "a": "A", "e": "【題目中文翻譯】如果出於任何原因您想變更或取消機票預訂，您需要透過網路或電話聯繫我們的客服專員。\n【考點解析】if for any reason 意為「如果出於任何原因/萬一」。"},
    {"id": "TOEIC_Part5_25", "no": "25", "f": {"分類": "形容詞"}, "ref": "Part 5", "q": "Owing to the nation's ------- political situation, foreign investors have started to pull funds out of the stock market.", "o": ["(A) unequal", "(B) anxious", "(C) unstable", "(D) hostile"], "a": "C", "e": "【題目中文翻譯】由於該國局勢不穩定的政治狀況，外國投資者已開始將資金撤出股市。\n【考點解析】unstable political situation 表示「不穩定的政治局勢」。"},
    {"id": "TOEIC_Part5_B2-例題-1", "no": "B2-例題-1", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The workplace emergency drill, which is scheduled at 9:30 a.m. on July 18, will take ------- four hours to complete.", "o": ["(A) approximation", "(B) approximate", "(C) approximated", "(D) approximately"], "a": "D", "e": "【題目中文翻譯】預定於 7 月 18 日上午 9:30 進行的職場緊急演習，大約需要四個小時才能完成。\n【考點解析】修飾數量片語 four hours，應選副詞 approximately（大約）。"},
    {"id": "TOEIC_Part5_B2-例題-2", "no": "B2-例題-2", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "Martha's Natural Foods is committed to ------- high-quality health foods to improve the well-being of all their customers.", "o": ["(A) manufactures", "(B) manufacturing", "(C) manufacture", "(D) manufactured"], "a": "B", "e": "【題目中文翻譯】瑪莎天然食品致力於製造高品質的健康食品，以改善所有客戶的福祉。\n【考點解析】be committed to 中的 to 為介系詞，後接動名詞 manufacturing。"},
    {"id": "TOEIC_Part5_B2-例題-3", "no": "B2-例題-3", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The director frowned throughout the rehearsal; -------, it didn't live up to his expectations.", "o": ["(A) evidence", "(B) evident", "(C) evidently", "(D) evidenced"], "a": "C", "e": "【題目中文翻譯】導演在整個排練過程中都皺著眉頭；顯然地，這沒有達到他的預期。\n【考點解析】空格位於分號後獨立修飾整句，應填入副詞 evidently（顯然地）。"},
    {"id": "TOEIC_Part5_B2-例題-4", "no": "B2-例題-4", "f": {"分類": "詞性"}, "ref": "Part 5", "q": "The banker indicated that the home loan interest ------- varies according to the credit history of the borrower.", "o": ["(A) rate", "(B) rates", "(C) rated", "(D) rater"], "a": "A", "e": "【題目中文翻譯】銀行家指出，房屋貸款利率根據借款人的信用記錄而有所不同。\n【考點解析】interest rate 為複合名詞，表示「利率」。謂語動詞為單數 varies，故主詞選擇單數 rate。"},
    {"id": "TOEIC_Part5_B2-例題-5", "no": "B2-例題-5", "f": {"分類": "介系詞搭配"}, "ref": "Part 5", "q": "After thoroughly discussing the marketing strategy, the team agreed ------- launching the campaign next month.", "o": ["(A) in", "(B) on", "(C) with", "(D) to"], "a": "B", "e": "【題目中文翻譯】在深入討論行銷策略後，團隊同意於下個月啟動該活動。\n【考點解析】agree on + V-ing/名詞 表示「對（計畫/事件）達成共識」。"},
    {"id": "TOEIC_Part5_B2-例題-6", "no": "B2-例題-6", "f": {"分類": "介系詞搭配"}, "ref": "Part 5", "q": "To apply for the Work-Study Program, Asher sent the university an email ------- the necessary documents attached.", "o": ["(A) at", "(B) through", "(C) with", "(D) for"], "a": "C", "e": "【題目中文翻譯】為了申請勤工儉學計畫，亞瑟給大學發了一封附有必要文件的電子郵件。\n【考點解析】with + 名詞 + attached 表示「附有……的（隨附）」。"},
    {"id": "TOEIC_Part5_B2-例題-7", "no": "B2-例題-7", "f": {"分類": "時態"}, "ref": "Part 5", "q": "The Spice Kitchen ------- as the city's best Indian restaurant since it was established 16 years ago.", "o": ["(A) was regarded", "(B) will be regarded", "(C) is being regarded", "(D) has been regarded"], "a": "D", "e": "【題目中文翻譯】自從16年前成立以來，Spice Kitchen 一直被視為本市最好的印度餐廳。\n【考點解析】since + 過去點，主要子句搭配現在完成被動式 has been regarded。"},
    {"id": "TOEIC_Part5_B2-例題-8", "no": "B2-例題-8", "f": {"分類": "時態"}, "ref": "Part 5", "q": "The company ------- a good marketing strategy before they launched their new product.", "o": ["(A) develops", "(B) was developing", "(C) had developed", "(D) has developed"], "a": "C", "e": "【題目中文翻譯】該公司在推出新產品之前已經制定了良好的行銷策略。\n【考點解析】動作發生於過去動作（launched）之前，使用過去完成式 had developed。"},
    {"id": "TOEIC_Part5_1_2", "no": "1", "f": {"分類": "限定詞"}, "ref": "Part 5", "q": "We are offering a fifteen percent discount on ------- these cheese and yogurt products in this section today.", "o": ["(A) total", "(B) whole", "(C) all", "(D) any"], "a": "C", "e": "【題目中文翻譯】我們今天對該區域的所有起司和優格產品提供八五折優惠。\n【考點解析】all these + 複數名詞，表示「所有這些……」。"},
    {"id": "TOEIC_Part5_2_2", "no": "2", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "The robotics engineer explained the ------- of an AI robot by showing a virtual 3D model to the audience.", "o": ["(A) novice", "(B) concept", "(C) definition", "(D) motive"], "a": "B", "e": "【題目中文翻譯】機器人工程師透過向觀眾展示虛擬3D模型，解釋了AI機器人的概念。\n【考點解析】concept of an AI robot 表示「AI機器人的概念」。"},
    {"id": "TOEIC_Part5_3_2", "no": "3", "f": {"分類": "連結詞"}, "ref": "Part 5", "q": "Please fill out this form so that we can contact you ------- your lost purse turns up.", "o": ["(A) as soon as", "(B) upon", "(C) until", "(D) no matter"], "a": "A", "e": "【題目中文翻譯】請填寫此表格，以便您遺失的手提包一找到我們就能聯繫您。\n【考點解析】as soon as 引導時間副詞子句，表示「一……就……」。"},
    {"id": "TOEIC_Part5_4_2", "no": "4", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "Because of the ------- high volume of orders received, the workers will have to work overtime this month.", "o": ["(A) extremely", "(B) exactly", "(C) excitedly", "(D) extensively"], "a": "A", "e": "【題目中文翻譯】由於收到極高數量的訂單，工人本月必須加班。\n【考點解析】修飾形容詞 high，填入副詞 extremely（極度地）。"},
    {"id": "TOEIC_Part5_5_2", "no": "5", "f": {"分類": "介系詞"}, "ref": "Part 5", "q": "In general, new hires will be provided a tour of the workplace and introduced to the team ------- the first week of employment.", "o": ["(A) during", "(B) while", "(C) among", "(D) anytime"], "a": "A", "e": "【題目中文翻譯】一般來說，新員工將在入職第一週獲得工作場所參觀並介紹給團隊。\n【考點解析】during + 時間名詞片語（the first week）。"},
    {"id": "TOEIC_Part5_6_2", "no": "6", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "With enormous help from the ground staff, the passenger was able to ------- his lost baggage.", "o": ["(A) react", "(B) retrieve", "(C) refresh", "(D) remake"], "a": "B", "e": "【題目中文翻譯】在地勤人員的巨大幫助下，該乘客得以找回遺失的行李。\n【考點解析】retrieve 意為「找回/取回」。"},
    {"id": "TOEIC_Part5_7_2", "no": "7", "f": {"分類": "動名詞"}, "ref": "Part 5", "q": "------- early can help you avoid morning traffic and ensure a smoother, faster commute to work.", "o": ["(A) Leaving", "(B) If leave", "(C) Leave", "(D) Left"], "a": "A", "e": "【題目中文翻譯】提早出門可以幫助您避開晨間交通，確保上班通勤更順暢快速。\n【考點解析】Leaving early 為動名詞片語作句子的主詞。"},
    {"id": "TOEIC_Part5_8_2", "no": "8", "f": {"分類": "形容詞"}, "ref": "Part 5", "q": "The store sells a wide variety of ------- travel items, such as backpacks, tents, trekking poles, and so on.", "o": ["(A) resourceful", "(B) electronic", "(C) lightweight", "(D) sophisticated"], "a": "C", "e": "【題目中文翻譯】該店銷售各種輕便的旅遊用品，例如背包、帳篷、登山杖等。\n【考點解析】lightweight 意為「輕便的/輕量級的」。"},
    {"id": "TOEIC_Part5_9_2", "no": "9", "f": {"分類": "關係代名詞"}, "ref": "Part 5", "q": "The animal rights activists ran the campaign to boycott the products of Vanity Cosmetics ------- had been tested on animals.", "o": ["(A) whom", "(B) that", "(C) what", "(D) whose"], "a": "B", "e": "【題目中文翻譯】動保人士發起活動，抵制 Vanity 化妝品公司經過動物實驗的產品。\n【考點解析】關係代名詞 that 指代先行詞 products 作子句的主詞。"},
    {"id": "TOEIC_Part5_10_2", "no": "10", "f": {"分類": "不定代名詞"}, "ref": "Part 5", "q": "------- spends over $65 in our shop today will have a chance to win a round-trip ticket to New Zealand.", "o": ["(A) Anyone", "(B) One another", "(C) Others", "(D) Whoever"], "a": "D", "e": "【題目中文翻譯】今天在我們店裡消費超過65美元的任何人，都有機會獲得前往紐西蘭的往返機票。\n【考點解析】Whoever 引導名詞子句作主詞，等於 Anyone who。"},
    {"id": "TOEIC_Part5_11_2", "no": "11", "f": {"分類": "分詞"}, "ref": "Part 5", "q": "Life Without Fear is an international nonprofit organization ------- to providing free shelter and counseling to women and children who suffer domestic violence.", "o": ["(A) dedicator", "(B) dedicate", "(C) dedicated", "(D) dedication"], "a": "C", "e": "【題目中文翻譯】Life Without Fear 是一個國際非營利組織，致力於為遭受家庭暴力的婦女和兒童提供免費庇護所和心理諮詢。\n【考點解析】be dedicated to... 省略為分詞片語 dedicated to...。"},
    {"id": "TOEIC_Part5_12_2", "no": "12", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Before signing a contract, the designer gave the storekeeper an ------- of $13,500 for the store renovation.", "o": ["(A) expectation", "(B) estimate", "(C) evaluation", "(D) example"], "a": "B", "e": "【題目中文翻譯】在簽訂合約前，設計師給了店主一份13,500美元的店面裝修估價單。\n【考點解析】an estimate of $13,500 意為「13,500美元的估價單」。"},
    {"id": "TOEIC_Part5_13_2", "no": "13", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "The data analyst's recommendations for future strategies indicate that he has ------- made much progress since he worked for the firm.", "o": ["(A) yet", "(B) amid", "(C) indeed", "(D) more"], "a": "C", "e": "【題目中文翻譯】數據分析師對未來策略的建議表明，自從他在該公司工作以來，他確實取得了很大的進步。\n【考點解析】indeed 意為「確實/著實」，用來加強語氣。"},
    {"id": "TOEIC_Part5_14_2", "no": "14", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "Since the manager has fifteen years of practical experience in risk management, she is ------- qualified to give advice.", "o": ["(A) enough", "(B) far", "(C) much", "(D) well"], "a": "D", "e": "【題目中文翻譯】由於經理在風險管理方面擁有十五年的實務經驗，她非常具備提供建議的資格。\n【考點解析】well qualified 意為「具備充分資格的」。"},
    {"id": "TOEIC_Part5_15_2", "no": "15", "f": {"分類": "分詞"}, "ref": "Part 5", "q": "The well-known author's adventure novel, ------- The Lost World, has become a best-seller around the world.", "o": ["(A) entitle", "(B) entitling", "(C) entitled", "(D) entitlement"], "a": "C", "e": "【題目中文翻譯】這位知名作者題為《失落的世界》的冒險小說已成為全球暢銷書。\n【考點解析】entitled The Lost World 作分詞片語被動修飾 novel，意為「名為/題為……」。"},
    {"id": "TOEIC_Part5_16_2", "no": "16", "f": {"分類": "助動詞被動"}, "ref": "Part 5", "q": "At the management meeting, the president listed a couple of measures that ------- immediately to cut operating costs.", "o": ["(A) was taken", "(B) had been taken", "(C) have been taken", "(D) must be taken"], "a": "D", "e": "【題目中文翻譯】在管理會議上，總裁列出了幾項必須立即採取的措施以削減營運成本。\n【考點解析】must be taken 表示「必須被採取」，符合句意要求。"},
    {"id": "TOEIC_Part5_17_2", "no": "17", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Mars Automobile has recently recalled over one million vehicles owing to its faulty design that might lead to brake -------.", "o": ["(A) halt", "(B) malfunction", "(C) withdrawal", "(D) collapse"], "a": "B", "e": "【題目中文翻譯】火星汽車最近召回了超過一百萬輛汽車，原因是設計缺陷可能導致煞車故障。\n【考點解析】brake malfunction 意為「煞車故障」。"},
    {"id": "TOEIC_Part5_18_2", "no": "18", "f": {"分類": "關係代名詞"}, "ref": "Part 5", "q": "The report, ------- we received last week, contains detailed information on the new project.", "o": ["(A) that", "(B) who", "(C) which", "(D) when"], "a": "C", "e": "【題目中文翻譯】我們上週收到的報告包含了新專案的詳細資訊。\n【考點解析】非限定用法關係代名詞，先行詞為事物 report，逗號後需用 which。"},
    {"id": "TOEIC_Part5_19_2", "no": "19", "f": {"分類": "代名詞"}, "ref": "Part 5", "q": "The Michelin three-star restaurant has six private dining rooms, ------- holding eight people.", "o": ["(A) each", "(B) which", "(C) everything", "(D) somewhat"], "a": "A", "e": "【題目中文翻譯】這家米其林三星餐廳有六間私人包廂，每間可容納八人。\n【考點解析】each holding... 獨立分詞構句，each 指代每間包廂。"},
    {"id": "TOEIC_Part5_20_2", "no": "20", "f": {"分類": "形容詞"}, "ref": "Part 5", "q": "The head demanded that the team members fix a ------- date for the completion of the product development project.", "o": ["(A) magnificant", "(B) transparent", "(C) complex", "(D) specific"], "a": "D", "e": "【題目中文翻譯】主管要求團隊成員確定完成產品開發專案的具體日期。\n【考點解析】a specific date 表示「具體的/明確的日期」。"},
    {"id": "TOEIC_Part5_21_2", "no": "21", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "In the interview, the director said that he intentionally blurred the ------- between good and evil in the actors of his new TV series.", "o": ["(A) outline", "(B) border", "(C) boundary", "(D) margin"], "a": "C", "e": "【題目中文翻譯】在專訪中，導演表示他在新電視劇的角色中刻意模糊了善與惡的界線。\n【考點解析】boundary between good and evil 意為「善與惡之間的界線」。"},
    {"id": "TOEIC_Part5_22_2", "no": "22", "f": {"分類": "名詞"}, "ref": "Part 5", "q": "Jenny Green has proved that her work is an excellent ------- to this exhibition.", "o": ["(A) add", "(B) addition", "(C) additional", "(D) additionally"], "a": "B", "e": "【題目中文翻譯】珍妮·格林證明了她的作品是本次展覽的一個絕佳補充/亮點。\n【考點解析】冠詞 an + 形容詞 excellent 後接單數名詞 addition。"},
    {"id": "TOEIC_Part5_23_2", "no": "23", "f": {"分類": "字彙"}, "ref": "Part 5", "q": "Many researchers have stated that children should not consume food that ------- too much sugar because it affects their concentration on learning.", "o": ["(A) secures", "(B) concludes", "(C) contains", "(D) proposes"], "a": "C", "e": "【題目中文翻譯】許多研究人員指出，兒童不應食用含有過多糖分的食物，因為這會影響他們的學習注意力。\n【考點解析】contains too much sugar 意為「含有過多的糖」。"},
    {"id": "TOEIC_Part5_24_2", "no": "24", "f": {"分類": "副詞"}, "ref": "Part 5", "q": "The international exchange students are ------- required to meet with their mentors.", "o": ["(A) frequented", "(B) frequently", "(C) frequency", "(D) frequent"], "a": "B", "e": "【題目中文翻譯】國際交換生被頻繁要求與他們的導師會面。\n【考點解析】be + 副詞 (frequently) + Vpp (required)。"},
    {"id": "TOEIC_Part5_25_2", "no": "25", "f": {"分類": "代名詞"}, "ref": "Part 5", "q": "Karen Wallens is taking ------- first trip to the continent of Africa, and she is so excited about it.", "o": ["(A) she", "(B) her", "(C) hers", "(D) herself"], "a": "B", "e": "【題目中文翻譯】凱倫·華倫斯正在踏上她前往非洲大陸的第一次旅行，她對此感到非常興奮。\n【考點解析】修飾名詞片語 first trip，使用所有格代名詞 her。"},
  ]
});

